    j = _js_skip_ws(text, j)
    if j >= n or text[j] != "(":
        raise _JSExprFail("Reflect.apply without paren")
    sliced, j = _js_parse_f534_bound_slice_triple(text,
                                                  _js_skip_ws(text, j + 1),
                                                  depth, state)
    j = _js_skip_ws(text, j)
    if j >= n or text[j] != ")":
        raise _JSExprFail("F534 with extra args")
