        sj = _js_expect(stmts, sj, ")")
        sj = _js_skip_ws(stmts, sj)
        if sj >= len(stmts) or stmts[sj] != ".":
            raise _JSExprFail("F600 keys no dot")
        _mn, sj = _js_parse_ident(stmts, _js_skip_ws(stmts, sj + 1))
