def _js_parse_f602_set_elements(text, j, depth, state):
    """Parse `new Set([...])` at text[j] (F602).

    Returns (elements, next_index): the SameValueZero-deduped
    insertion-ordered element list (node v24.20.0 verified --
    first occurrence wins). Elements must be plain string
    literals (numeric/marker/nested elements fail closed, the F494
    discipline); each element charges one part (F452). Never evals.
    """
    n = len(text)
    j0 = _js_match_kw(text, j, "new")
    if j0 is None:
        raise _JSExprFail("F602 not new")
    j = _js_skip_ws(text, j0)
    if _js_match_kw(text, j, "Set") is None:
        raise _JSExprFail("F602 not new Set")
    j = _js_skip_ws(text, j + len("Set"))
    j = _js_expect(text, j, "(")
    j = _js_skip_ws(text, j)
    if j >= n or text[j] != "[":
        raise _JSExprFail("F602 Set arg not an array literal")
    arr, j = _js_parse_array(text, j, depth, state)
    seen = set()
    elements = []
    for e in arr.elements:
        if not isinstance(e, str) or isinstance(e, _JSNumStr):
            raise _JSExprFail("F602 Set of non-string literals")
        state["parts"] += 1
        if state["parts"] > _JS_EXPR_MAX_PARTS:
            raise _JSExprFail("too many parts")
        if e not in seen:
            seen.add(e)
            elements.append(e)
    j = _js_skip_ws(text, j)
    j = _js_expect(text, j, ")")
    return elements, j


def _js_parse_f608_setspread_args(text, j, depth, state):
    """Parse `...new Set([LITS])` at text[j] (F608).

    The call-argument spread form: the spread expands to the Set's
    SameValueZero-deduped insertion-ordered element list (the F602
    discipline -- validated by delegating to
    `_js_parse_f602_set_elements`, so the F494 plain-string-literal
    rule and the F452 per-element part charging apply unchanged).

    Returns (raw_texts, next_index): *raw_texts* is the raw source
    text of each element's first occurrence, in dedupe order -- the
    form the iife binders substitute (raw source preserves the exact
    escape encoding, so the downstream additive parse is
    byte-identical to a literal call-site arg). The dedupe order is
    asserted to agree with `_js_parse_f602_set_elements`; any
    divergence fails closed (never mis-decoded). Never evals.
    """
    n = len(text)
    if j + 3 > n or not text.startswith("...", j):
        raise _JSExprFail("F608 not spread")
    sj = _js_skip_ws(text, j + 3)
    elements, k = _js_parse_f602_set_elements(text, sj, depth, state)
    # Recover each element's raw literal source text. The F602 parse
    # above validated the array shape (plain string literals only),
    # so the quote-span scan below is total; guards stay anyway.
    arr = text.index("[", sj)  # safe: no strings precede the `[`
    t = arr + 1
    pairs = []
    while True:
        t = _js_skip_ws(text, t)
        if t >= n:
            raise _JSExprFail("F608 setspan overrun")
        if text[t] == "]":
            break
        if text[t] not in "'\"":
            raise _JSExprFail("F608 setspan non-literal")
        q0 = t
        val, t = _js_parse_string(text, t)
        pairs.append((val, text[q0:t]))
        t = _js_skip_ws(text, t)
        if t < n and text[t] == ",":
            t += 1
            continue
        if t < n and text[t] == "]":
            break
        raise _JSExprFail("F608 setspan bad separator")
    seen = set()
    raw_texts = []
    dedup = []
    for val, raw in pairs:
        if val not in seen:
            seen.add(val)
            raw_texts.append(raw)
            dedup.append(val)
    if dedup != elements:
        # Defensive: the rescan's first-occurrence dedupe order
        # must agree with `_js_parse_f602_set_elements` exactly;
        # anything else is a miss, never a guess.
        raise _JSExprFail("F608 setspan dedupe mismatch")
    return raw_texts, k


def _js_parse_map_numkey(text, t):
    """Parse a numeric Map key at text[t] (F615/F625); return (str(num), next).

    Mirrors the _JSNumStr identity the F494 validator computes for
    numeric keys: decimal and 0x integers via `_js_parse_number`
    (str of the int value), unary minus via the F483 rule
    (`"-" + str(int(digits))`). The F494 parse already accepted the
    key (it currently rejects unary-minus keys itself -- the `-`
    branch here is defensive, kept so the rescan stays total if the
    validator ever admits them), so any form here that disagrees
    with the validator fails closed downstream at the
    order-agreement check.
    """
    n = len(text)
    neg = False
    if t < n and text[t] == "-":
        neg = True
        t = _js_skip_ws(text, t + 1)
    num, t = _js_parse_number(text, t)
    return ("-" + str(num) if neg else str(num)), t


def _js_parse_f615_mapspread_args(text, j, depth, state):
    """Parse `...new Map([[k,v],...]).values()` at text[j] (F615).

    The Map twin of F608's Set-spread source: spreading a Map's
    values iterator expands to the values in iteration order with
    later-wins on duplicate keys (the F494 discipline -- validated
    by delegating to `_js_parse_new_map_values`, so the
    plain-string-literal rule and the F452 part/ops charging apply
    unchanged).

    Returns (raw_texts, next_index): *raw_texts* is the raw source
    text of each surviving value's literal, in values-iteration
    order -- the form the iife binders substitute (raw source
    preserves the exact escape encoding, so the downstream additive
    parse is byte-identical to a literal call-site arg). Later-wins
    mirrors the F494 validator's `index`/`order` bookkeeping
    exactly; any divergence between the rescan and the validated
    `_JSArr` fails closed (never mis-decoded). Never evals.
    """
    n = len(text)
    if j + 3 > n or not text.startswith("...", j):
        raise _JSExprFail("F615 not spread")
    sj = _js_skip_ws(text, j + 3)
    arr, k = _js_parse_new_map_values(text, sj, depth, state)
    # Recover each surviving value's raw literal source text. The
    # F494 parse above validated the entries (string/numeric literal
    # keys, plain string-literal values), so the span scan below is
    # total; guards stay anyway.
    arr_open = text.find("[", sj)
    if arr_open < 0:  # defensive: the validator already consumed it
        raise _JSExprFail("F615 mapspan no array")
    t = arr_open + 1
    order = []  # (value, raw) in later-wins iteration order
    index = {}
    while True:
        t = _js_skip_ws(text, t)
        if t >= n:
            raise _JSExprFail("F615 mapspan overrun")
        if text[t] == "]":
            break
        if text[t] != "[":
            raise _JSExprFail("F615 mapspan entry not a pair")
        t = _js_skip_ws(text, t + 1)
        if t < n and text[t] in "'\"":
            kval, t = _js_parse_string(text, t)
            kid = ("s", kval)
        else:
            ks, t = _js_parse_map_numkey(text, t)
            kid = ("n", ks)
        t = _js_skip_ws(text, t)
        if t >= n or text[t] != ",":
            raise _JSExprFail("F615 mapspan bad key separator")
        t = _js_skip_ws(text, t + 1)
        if t >= n or text[t] not in "'\"":
            raise _JSExprFail("F615 mapspan value not a literal")
        v0 = t
        vval, t = _js_parse_string(text, t)
        raw = text[v0:t]
        t = _js_skip_ws(text, t)
        if t >= n or text[t] != "]":
            raise _JSExprFail("F615 mapspan pair not closed")
        t = _js_skip_ws(text, t + 1)
        if kid in index:
            order[index[kid]] = (vval, raw)
        else:
            index[kid] = len(order)
            order.append((vval, raw))
        t = _js_skip_ws(text, t)
        if t < n and text[t] == ",":
            t += 1
            continue
        if t < n and text[t] == "]":
            break
        raise _JSExprFail("F615 mapspan bad separator")
    vals = [v for v, _ in order]
    if vals != list(arr.elements):
        # Defensive: the rescan's later-wins order must agree with
        # `_js_parse_new_map_values` exactly; anything else is a
        # miss, never a guess.
        raise _JSExprFail("F615 mapspan value mismatch")
    return [r for _, r in order], k


def _js_parse_f625_mapspread_args(text, j, depth, state):
    """Parse `...new Map([[k,v],...]).entries()` / `.keys()` at text[j] (F625).

    The Map entries()/keys() spread sources: spreading `entries()`
    expands to the [k,v] pairs in iteration order (later-wins on
    duplicate keys), spreading `keys()` to the keys in iteration
    order (node v24.20.0). Entry validation is the shared
    `_js_parse_new_map_head` (F494/F625 -- plain-string-literal
    rule, SameValueZero identity, F452 part/ops charging unchanged);
    the rescan below recovers each surviving entry's raw source
    text (pair span for entries, key span for keys) with the same
    later-wins order, and the decoded (key, value) pairs must agree
    with the validated head exactly -- any divergence fails closed
    (never mis-decoded). Raw source preserves the exact escape
    encoding, so the downstream binders substitute byte-identical
    text. `.values()` is refused here (F615 owns that source);
    Set spreads are refused (F608). Never evals.

    Returns (spread_texts, next_index, kind): *spread_texts* is the
    raw source text of each spread element in iteration order (pair
    spans for "entries", key spans for "keys"), *kind* is
    "entries" or "keys".
    """
    n = len(text)
    if j + 3 > n or not text.startswith("...", j):
        raise _JSExprFail("F625 not spread")
    sj = _js_skip_ws(text, j + 3)
    pairs, k = _js_parse_new_map_head(text, sj, depth, state)
    k = _js_skip_ws(text, k)
    if k >= n or text[k] != ".":
        raise _JSExprFail("F625 expected member")
    km = _js_match_kw(text, _js_skip_ws(text, k + 1), "entries")
    kind = "entries"
    if km is None:
        km = _js_match_kw(text, _js_skip_ws(text, k + 1), "keys")
        kind = "keys"
    if km is None:
        # `.values()` (F615) and anything else are not F625's.
        raise _JSExprFail("F625 not entries()/keys()")
    k = _js_expect(text, km, "(")
    k = _js_expect(text, k, ")")
    # Rescan the entry-array span for raw key/value/pair source
    # texts, mirroring the F615 rescan discipline (the head already
    # validated the entries, so the span scan is total; guards stay
    # anyway).
    arr_open = text.find("[", sj)
    if arr_open < 0:  # defensive: the validator already consumed it
        raise _JSExprFail("F625 mapspan no array")
    t = arr_open + 1
    order = []  # (kid, kval, vval, pair_raw, kraw, vraw), later-wins
    index = {}
    while True:
        t = _js_skip_ws(text, t)
        if t >= n:
            raise _JSExprFail("F625 mapspan overrun")
        if text[t] == "]":
            break
        if text[t] != "[":
            raise _JSExprFail("F625 mapspan entry not a pair")
        p0 = t
        t = _js_skip_ws(text, t + 1)
        if t < n and text[t] in "'\"":
            k0 = t
            kval, t = _js_parse_string(text, t)
            kraw = text[k0:t]
            kid = ("s", kval)
        else:
            k0 = t
            ks, t = _js_parse_map_numkey(text, t)
            kraw = text[k0:t]
            kval = ks
            kid = ("n", ks)
        t = _js_skip_ws(text, t)
        if t >= n or text[t] != ",":
            raise _JSExprFail("F625 mapspan bad key separator")
        t = _js_skip_ws(text, t + 1)
        if t >= n or text[t] not in "'\"":
            raise _JSExprFail("F625 mapspan value not a literal")
        v0 = t
        vval, t = _js_parse_string(text, t)
        vraw = text[v0:t]
        t = _js_skip_ws(text, t)
        if t >= n or text[t] != "]":
            raise _JSExprFail("F625 mapspan pair not closed")
        t = _js_skip_ws(text, t + 1)
        pair_raw = text[p0:t]
        if kid in index:
            order[index[kid]] = (kid, kval, vval, pair_raw, kraw, vraw)
        else:
            index[kid] = len(order)
            order.append((kid, kval, vval, pair_raw, kraw, vraw))
        t = _js_skip_ws(text, t)
        if t < n and text[t] == ",":
            t += 1
            continue
        if t < n and text[t] == "]":
            break
        raise _JSExprFail("F625 mapspan bad separator")
    if ([(kid, kval, vval) for kid, kval, vval, _, _, _ in order]
            != [(kid, k, v) for kid, k, v in pairs]):
        # Defensive: the rescan's later-wins order must agree with
        # the validated head exactly; anything else is a miss,
        # never a guess.
        raise _JSExprFail("F625 mapspan pair mismatch")
    state["ops"] += 1  # the iterable-spread source is obfuscation-shaped
    if kind == "entries":
        return [pr for _, _, _, pr, _, _ in order], k, kind
    return [kr for _, _, _, _, kr, _ in order], k, kind


def _js_bind_f625_pair_arguments(body_expr, arg_texts, names):
    """Bind fixed params to [k,v] pair raws in *body_expr* (F625).

    The entries-spread twin of `_js_bind_destructure_arguments`: each
    param IS a [k,v] pair array in the engine (node v24.20.0), so
    every code-span occurrence of a bound name must be bare `a`
    (the pair) or `a[N]` with N in {0,1} -- the engine index read.
    The ident is rewritten to the pair's raw source text, leaving
    `[N]` in place (`a[1]` -> `['a','f1'][1]`, which the additive
    grammar parses node-exactly). Any other use (`a.M`, `a(`,
    `...a`, `.a`, `a['x']`, `a[2]`) fails closed, as do params
    beyond the call args (the engine coerces `undefined`, which the
    decoder never guesses -- the F524 discipline). Guards mirror
    `_js_bind_destructure_arguments` (no nested function/delete/
    new/class, no bare assignment, no arrow-param shadowing).
    Substitution never touches string-literal contents. Plain string
    scanning throughout -- zero new regexes. Never evals.
    """
    if len(names) > len(arg_texts):
        raise _JSExprFail("F625 arity")
    segs = _js_split_code_strings(body_expr)
    code = "".join(s for is_code, s in segs if is_code)
    for kw, msg in (("function", "nested function in bound body"),
                    ("delete", "delete in bound body"),
                    ("new", "new in bound body"),
                    ("class", "class in bound body")):
        if _js_code_find_idents(code, kw):
            raise _JSExprFail(msg)
    if _js_code_has_bare_assign(code):
        raise _JSExprFail("assignment in bound body")
    for nm in names:
        if _js_code_has_ident_arrow_param(code, nm):
            raise _JSExprFail("bound ident as arrow param")
    by_name = {nm: k for k, nm in enumerate(names)}
    out = []
    for is_code, s in segs:
        if not is_code:
            out.append(s)
            continue
        occ = []
        for nm, k in by_name.items():
            for st in _js_code_find_idents(s, nm):
                occ.append((st, nm, k))
        occ.sort()
        pos = 0
        buf = []
        for st, nm, k in occ:
            en = st + len(nm)
            if st > 0 and s[st - 1] == ".":
                raise _JSExprFail("F625 member receiver use")
            if s[max(0, st - 3):st].endswith("..."):
                raise _JSExprFail("F625 spread use")
            rest = s[en:]
            br = _js_parse_bracket_index(rest)
            if br is not None:
                idx, consumed = br
                if idx not in (0, 1):
                    raise _JSExprFail("F625 index not 0/1")
                buf.append(s[pos:st])
                buf.append(arg_texts[k])
                pos = en  # the [N] bracket stays in place
                continue
            if rest[:1] in (".", "[", "("):
                raise _JSExprFail("F625 unmodeled pair use")
            buf.append(s[pos:st])
            buf.append(arg_texts[k])
            pos = en
        buf.append(s[pos:])
        out.append("".join(buf))
    rewritten = "".join(out)
    # Defensive: every code-span occurrence must have been consumed.
    # (String spans may legitimately contain the word.)
    rcode = "".join(s for is_code, s in _js_split_code_strings(rewritten)
                    if is_code)
    for nm in names:
        if _js_code_find_idents(rcode, nm):
            raise _JSExprFail("F625 pair ident left unsubstituted")
    return rewritten


def _js_parse_f602_set_forof_iife(text, i, depth, state):
    """Parse `(function(){var|let S='';for(var|let|const X of new Set([LITS])){S+=X;}return S;})()` (F602).

    Node-exact desugar (v24.20.0): for-of over a Set yields the
    deduped values in insertion order, so the accumulator is the
    element join. The loop grammar mirrors _js_parse_f533_forof_accum
    (braces optional, var/let/const loopvar) with the source fixed
    to the `new Set([...])` literal. Returns (value,
    next_index), or None on mismatch/guard failure. Never evals.

    Bounds (all fail closed): a non-empty accumulator, `const`
    accumulator, a loop variable shadowing the accumulator, a
    loop body other than `S+=X`, non-string-literal Set elements,
    call args on the IIFE.
    """
    j = _js_parse_f6xx_iife_head(text, i)
    if j is None:
        return None
    try:
        brace = j
        inner_start, inner_end, j = _js_span_braced(text, brace)
        stmts = text[inner_start:inner_end]
        sj = _js_skip_ws(stmts, 0)
        acc, sj = _js_parse_f6xx_accum_decl(stmts, sj)
        sj = _js_skip_ws(stmts, sj)
        m = _js_match_kw(stmts, sj, "for")
        if m is None:
            raise _JSExprFail("F602 no for")
        sj = _js_skip_ws(stmts, m)
        sj = _js_expect(stmts, sj, "(")
        sj = _js_skip_ws(stmts, sj)
        m = _js_match_kw(stmts, sj, "var")
        if m is None:
            m = _js_match_kw(stmts, sj, "let")
        if m is None:
            m = _js_match_kw(stmts, sj, "const")
        if m is None:
            raise _JSExprFail("F602 loopvar not var/let/const")
        sj = _js_skip_ws(stmts, m)
        loopvar, sj = _js_parse_ident(stmts, sj)
        if loopvar == acc:
            raise _JSExprFail("F602 loopvar shadows accum")
        sj = _js_skip_ws(stmts, sj)
        m = _js_match_kw(stmts, sj, "of")
        if m is None:
            raise _JSExprFail("F602 no of")
        sj = _js_skip_ws(stmts, m)
        elements, sj = _js_parse_f602_set_elements(stmts, sj, depth,
                                                   state)
        sj = _js_skip_ws(stmts, sj)
        sj = _js_expect(stmts, sj, ")")
        sj = _js_skip_ws(stmts, sj)
        braced = False
        if sj < len(stmts) and stmts[sj] == "{":
            braced = True
            sj = _js_skip_ws(stmts, sj + 1)
        acc2, sj = _js_parse_ident(stmts, sj)
        if acc2 != acc:
            raise _JSExprFail("F602 accum mismatch")
        sj = _js_skip_ws(stmts, sj)
        if not stmts.startswith("+=", sj):
            raise _JSExprFail("F602 body not +=")
        sj = _js_skip_ws(stmts, sj + 2)
        v2, sj = _js_parse_ident(stmts, sj)
        if v2 != loopvar:
            raise _JSExprFail("F602 body reads another ident")
        sj = _js_skip_ws(stmts, sj)
        sj = _js_expect(stmts, sj, ";")
        sj = _js_skip_ws(stmts, sj)
        if braced:
            sj = _js_expect(stmts, sj, "}")
            sj = _js_skip_ws(stmts, sj)
        _js_parse_f6xx_return_acc(stmts, sj, acc)
        if depth >= _JS_EXPR_MAX_DEPTH:
            raise _JSExprFail("too deep")
        return _js_parse_f6xx_iife_tail(text, j, depth, state,
                                        "".join(elements))
    except _JSExprFail:
        return None


def _js_parse_f602_set_foreach_iife(text, i, depth, state):
    """Parse `(function(){var|let S='';var|let|const ST=new Set([LITS]);ST.forEach(CB);return S;})()` (F602).

    Node-exact desugar (v24.20.0): Set.prototype.forEach calls CB
    once per element in insertion order with (value, value, set);
    the modeled callbacks accumulate `S+=E` per call. The Set is
    bound to a var/let/const one statement before the forEach --
    the binding is single-assignment (the exact-shape grammar has
    no room for reassignment). Same callback/accumulator
    discipline as F601. Returns (value, next_index), or None on
    mismatch/guard failure. Never evals.

    Bounds (all fail closed): a non-empty accumulator, `const`
    accumulator, a non-`new Set` binding, non-string-literal Set
    elements, forEach on a different ident, a callback that is not
    the exact `S+=E` shape, params shadowing the accumulator or
    the Set binding, non-string E values, call args on the IIFE.
    """
    j = _js_parse_f6xx_iife_head(text, i)
    if j is None:
        return None
    try:
        brace = j
        inner_start, inner_end, j = _js_span_braced(text, brace)
        stmts = text[inner_start:inner_end]
        sj = _js_skip_ws(stmts, 0)
        acc, sj = _js_parse_f6xx_accum_decl(stmts, sj)
        sj = _js_skip_ws(stmts, sj)
        m = _js_match_kw(stmts, sj, "var")
        if m is None:
            m = _js_match_kw(stmts, sj, "let")
        if m is None:
            m = _js_match_kw(stmts, sj, "const")
        if m is None:
            raise _JSExprFail("F602 set decl not var/let/const")
        sj = _js_skip_ws(stmts, m)
        setname, sj = _js_parse_ident(stmts, sj)
        if setname == acc:
            raise _JSExprFail("F602 set shadows accum")
        sj = _js_skip_ws(stmts, sj)
        sj = _js_expect(stmts, sj, "=")
        sj = _js_skip_ws(stmts, sj)
        elements, sj = _js_parse_f602_set_elements(stmts, sj, depth,
                                                   state)
        sj = _js_skip_ws(stmts, sj)
        sj = _js_expect(stmts, sj, ";")
        sj = _js_skip_ws(stmts, sj)
        recv, sj = _js_parse_ident(stmts, sj)
        if recv != setname:
            raise _JSExprFail("F602 forEach on another ident")
        sj = _js_skip_ws(stmts, sj)
        sj = _js_expect(stmts, sj, ".")
        _mn, sj = _js_parse_ident(stmts, _js_skip_ws(stmts, sj))
        if _mn != "forEach":
            raise _JSExprFail("F602 not forEach")
        sj = _js_skip_ws(stmts, sj)
        sj = _js_expect(stmts, sj, "(")
        params, E, sj = _js_parse_foreach_accum_callback(
            stmts, sj, acc, depth, state)
        if acc in params or setname in params:
            raise _JSExprFail("F602 param shadows")
        sj = _js_skip_ws(stmts, sj)
        sj = _js_expect(stmts, sj, ")")
        sj = _js_skip_ws(stmts, sj)
        sj = _js_expect(stmts, sj, ";")
        _js_parse_f6xx_return_acc(stmts, _js_skip_ws(stmts, sj), acc)
        if depth >= _JS_EXPR_MAX_DEPTH:
            raise _JSExprFail("too deep")
        parts = []
        for e in elements:
            # The engine passes (value, value, set): P1 and P2 both
            # bind the value (node v24.20.0 verified).
            etext = _js_quote_literal(e)
            bindings = [(params[0], etext)]
            if len(params) > 1:
                bindings.append((params[1], etext))
            parts.append(_js_foreach_E_value(
                E, bindings, depth, state))
            state["parts"] += 1  # F452: charge per iteration
            if state["parts"] > _JS_EXPR_MAX_PARTS:
                raise _JSExprFail("too many parts")
        return _js_parse_f6xx_iife_tail(text, j, depth, state,
                                        "".join(parts))
    except _JSExprFail:
        return None


def _js_parse_f719_set_forof_iife(text, i, depth, state):
    """Parse two for-of-over-Set accumulation shapes (F719).

    Shape A (var-bound twin):
      `(function(){var|let S='';var|let|const ST=new Set([LITS]);
      for(var|let|const X of ST){S+=X|S=X+X;}return S;})()`
    Shape B (additive-assign twin):
      `(function(){var|let S='';
      for(var|let|const X of new Set([LITS])){S=S+X;}return S;})()`

    The F602 residual: F602's for-of route requires the inline
    `new Set(...)` immediately after the accumulator decl with an
    `S+=X` body (shape A interposes a var-bound Set decl; shape B
    uses an `S=S+X` body), and F602's forEach route requires a
    `.forEach` call -- so both fail closed on these shapes and this
    route is disjoint from them: no previously-decoded input
    changes behavior.

    Node-exact desugar (v24.20.0): for-of over a Set yields the
    deduped values in insertion order (the F602 element discipline
    via _js_parse_f602_set_elements / _js_parse_f669_set_decl --
    plain string literals, SameValueZero first-occurrence dedup,
    F452 per-element parts charge); `S=S+X` is engine-identical to
    `S+=X` for the empty-string accumulator. The loop grammar
    mirrors _js_parse_f533_forof_accum (braces optional,
    var/let/const loopvar).

    Bounds (all fail closed): a non-empty accumulator, a `const`
    accumulator, a Set binding shadowing the accumulator, a loop
    variable shadowing the accumulator or the Set binding, a loop
    body other than `S+=X` / `S=S+X`, an iteration source other
    than the bound Set (shape A) or an inline `new Set` (shape B),
    non-string-literal Set elements, call args on the IIFE. Never
    evals.
    """
    j = _js_parse_f6xx_iife_head(text, i)
    if j is None:
        return None
    try:
        brace = j
        inner_start, inner_end, j = _js_span_braced(text, brace)
        stmts = text[inner_start:inner_end]
        sj = _js_skip_ws(stmts, 0)
        acc, sj = _js_parse_f6xx_accum_decl(stmts, sj)
        sj = _js_skip_ws(stmts, sj)
        elements = None
        bound = None
        m = _js_match_kw(stmts, sj, "var")
        if m is None:
            m = _js_match_kw(stmts, sj, "let")
        if m is None:
            m = _js_match_kw(stmts, sj, "const")
        if m is not None:
            # Shape A: a var-bound Set decl. Any non-Set decl raises
            # (fail closed -- the shape is not one of ours).
            stname, elements, sj = _js_parse_f669_set_decl(
                stmts, sj, depth, state)
            if stname == acc:
                raise _JSExprFail("F719 Set binding shadows accum")
            bound = stname
            sj = _js_skip_ws(stmts, sj)
        m = _js_match_kw(stmts, sj, "for")
        if m is None:
            raise _JSExprFail("F719 no for")
        sj = _js_skip_ws(stmts, m)
        sj = _js_expect(stmts, sj, "(")
        sj = _js_skip_ws(stmts, sj)
        m = _js_match_kw(stmts, sj, "var")
        if m is None:
            m = _js_match_kw(stmts, sj, "let")
        if m is None:
            m = _js_match_kw(stmts, sj, "const")
        if m is None:
            raise _JSExprFail("F719 loopvar not var/let/const")
        sj = _js_skip_ws(stmts, m)
        loopvar, sj = _js_parse_ident(stmts, sj)
        if loopvar == acc:
            raise _JSExprFail("F719 loopvar shadows accum")
        if bound is not None and loopvar == bound:
            raise _JSExprFail("F719 loopvar shadows Set binding")
        sj = _js_skip_ws(stmts, sj)
        m = _js_match_kw(stmts, sj, "of")
        if m is None:
            raise _JSExprFail("F719 no of")
        sj = _js_skip_ws(stmts, m)
        if bound is not None:
            src, sj = _js_parse_ident(stmts, sj)
            if src != bound:
                raise _JSExprFail("F719 iterates another ident")
        else:
            # Shape B: the inline `new Set` -- F602 owns the
            # inline-`S+=X` twin, so this route only takes the
            # additive-assign body (checked below).
            elements, sj = _js_parse_f602_set_elements(
                stmts, sj, depth, state)
        sj = _js_skip_ws(stmts, sj)
        sj = _js_expect(stmts, sj, ")")
        sj = _js_skip_ws(stmts, sj)
        braced = False
        if sj < len(stmts) and stmts[sj] == "{":
            braced = True
            sj = _js_skip_ws(stmts, sj + 1)
        acc2, sj = _js_parse_ident(stmts, sj)
        if acc2 != acc:
            raise _JSExprFail("F719 accum mismatch")
        sj = _js_skip_ws(stmts, sj)
        if stmts.startswith("+=", sj):
            # S+=X -- shape A only (F602 owns inline S+=X).
            if bound is None:
                raise _JSExprFail("F719 inline S+=X is F602's")
            sj = _js_skip_ws(stmts, sj + 2)
            v2, sj = _js_parse_ident(stmts, sj)
            if v2 != loopvar:
                raise _JSExprFail("F719 body reads another ident")
        elif (sj < len(stmts) and stmts[sj] == "="
                and not stmts.startswith("==", sj)
                and not stmts.startswith("=>", sj)):
            # S=S+X -- engine-identical to S+=X for the empty-string
            # accumulator (node v24.20.0 verified).
            sj = _js_skip_ws(stmts, sj + 1)
            s2, sj = _js_parse_ident(stmts, sj)
            if s2 != acc:
                raise _JSExprFail("F719 additive-assign not accum")
            sj = _js_skip_ws(stmts, sj)
            sj = _js_expect(stmts, sj, "+")
            sj = _js_skip_ws(stmts, sj)
            v2, sj = _js_parse_ident(stmts, sj)
            if v2 != loopvar:
                raise _JSExprFail("F719 body reads another ident")
        else:
            raise _JSExprFail("F719 body not accum append")
        sj = _js_skip_ws(stmts, sj)
        sj = _js_expect(stmts, sj, ";")
        sj = _js_skip_ws(stmts, sj)
        if braced:
            sj = _js_expect(stmts, sj, "}")
            sj = _js_skip_ws(stmts, sj)
        _js_parse_f6xx_return_acc(stmts, sj, acc)
        if depth >= _JS_EXPR_MAX_DEPTH:
            raise _JSExprFail("too deep")
        state["parts"] += 1  # F452: charge the for-of consumption
        if state["parts"] > _JS_EXPR_MAX_PARTS:
            raise _JSExprFail("too many parts")
        return _js_parse_f6xx_iife_tail(text, j, depth, state,
                                        "".join(elements))
    except _JSExprFail:
        return None


def _js_parse_f669_set_decl(stmts, sj, depth, state):
    """Parse `var|let|const NAME=new Set([LITS]|);` at stmts[sj] (F669).

    The Set-construction source reuses the F602 element discipline
    (plain string literals, SameValueZero first-occurrence dedup,
    F452 per-element parts charge); `new Set()` with no argument is
    the node-exact empty set (v24.20.0). Returns (name, elements,
    next_index). Never evals.
    """
    n = len(stmts)
    m = _js_match_kw(stmts, sj, "var")
    if m is None:
        m = _js_match_kw(stmts, sj, "let")
    if m is None:
        m = _js_match_kw(stmts, sj, "const")
    if m is None:
        raise _JSExprFail("F669 set decl not var/let/const")
    sj = _js_skip_ws(stmts, m)
    name, sj = _js_parse_ident(stmts, sj)
    if name in _F611_RESERVED or name == "arguments":
        raise _JSExprFail("F669 set binding reserved")
    sj = _js_skip_ws(stmts, sj)
    sj = _js_expect(stmts, sj, "=")
    sj = _js_skip_ws(stmts, sj)
    j = _js_match_kw(stmts, sj, "new")
    if j is None:
        raise _JSExprFail("F669 set source not new")
    j = _js_match_kw(stmts, _js_skip_ws(stmts, j), "Set")
    if j is None:
        raise _JSExprFail("F669 set source not Set")
    j = _js_expect(stmts, j, "(")
    j = _js_skip_ws(stmts, j)
    if j < n and stmts[j] == ")":
        elements = []
        j += 1
    else:
        elements, j = _js_parse_f602_set_elements(stmts, sj, depth,
                                                  state)
    sj = _js_skip_ws(stmts, j)
    sj = _js_expect(stmts, sj, ";")
    return name, elements, sj


def _js_parse_f669_set_adds(stmts, sj, name, elements, depth, state):
    """Apply `(NAME.add('LIT');)*` mutations at stmts[sj] (F669).

    Node-exact (v24.20.0): Set.prototype.add appends the value with
    SameValueZero dedup (first occurrence wins); a non-string
    literal fails closed (the F602 literal discipline). Returns
    (elements, next_index). Never evals.
    """
    n = len(stmts)
    elements = list(elements)
    seen = set(elements)
    while True:
        q = _js_skip_ws(stmts, sj)
        try:
            rname, q = _js_parse_ident(stmts, q)
        except _JSExprFail:
            break
        if rname != name:
            break
        q = _js_skip_ws(stmts, q)
        if q >= n or stmts[q] != ".":
            break
        q = _js_skip_ws(stmts, q + 1)
        try:
            mname, q = _js_parse_ident(stmts, q)
        except _JSExprFail:
            break
        if mname != "add":
            # Unmodeled mutation: fail the whole shape closed
            # rather than mis-decode (F599 precedent).
            raise _JSExprFail("F669 set member not add")
        q = _js_skip_ws(stmts, q)
        if q >= n or stmts[q] != "(":
            raise _JSExprFail("F669 add without paren")
        q = _js_skip_ws(stmts, q + 1)
        if q >= n or stmts[q] not in "'\"":
            raise _JSExprFail("F669 add arg not a literal")
        val, q = _js_parse_string(stmts, q)
        q = _js_skip_ws(stmts, q)
        if q >= n or stmts[q] != ")":
            raise _JSExprFail("F669 add unterminated")
        q = _js_skip_ws(stmts, q + 1)
        if q >= n or stmts[q] != ";":
            raise _JSExprFail("F669 add without semicolon")
        if val not in seen:
            seen.add(val)
            elements.append(val)
        state["parts"] += 1  # the mutation is obfuscation-shaped
        if state["parts"] > _JS_EXPR_MAX_PARTS:
            raise _JSExprFail("too many parts")
        sj = q + 1
    return elements, sj


def _js_parse_f669_map_decl(stmts, sj, depth, state):
    """Parse `var|let|const NAME=new Map();` or `var|let|const NAME=new Map([[K,V],...]);` at stmts[sj] (F669).

    Returns (name, pairs, next_index): pairs is the
    insertion-ordered [(kid, key, value)] with later-wins dedup (the
    F494 discipline, node-exact: the empty-ctor form starts empty
    and the caller applies `.set()` mutations). The ctor-arg form
    reuses `_js_parse_new_map_head`; each pair charges the parts
    budget (F452). Never evals.
    """
    n = len(stmts)
    m = _js_match_kw(stmts, sj, "var")
    if m is None:
        m = _js_match_kw(stmts, sj, "let")
    if m is None:
        m = _js_match_kw(stmts, sj, "const")
    if m is None:
        raise _JSExprFail("F669 map decl not var/let/const")
    sj = _js_skip_ws(stmts, m)
    name, sj = _js_parse_ident(stmts, sj)
    if name in _F611_RESERVED or name == "arguments":
        raise _JSExprFail("F669 map binding reserved")
    sj = _js_skip_ws(stmts, sj)
    sj = _js_expect(stmts, sj, "=")
    sj = _js_skip_ws(stmts, sj)
    j = _js_match_kw(stmts, sj, "new")
    if j is None:
        raise _JSExprFail("F669 map source not new")
    j = _js_match_kw(stmts, _js_skip_ws(stmts, j), "Map")
    if j is None:
        raise _JSExprFail("F669 map source not Map")
    j = _js_expect(stmts, j, "(")
    j = _js_skip_ws(stmts, j)
    if j < n and stmts[j] == ")":
        pairs = []
        j += 1
    else:
        pairs, j = _js_parse_new_map_head(stmts, sj, depth, state)
        for _ in pairs:
            state["parts"] += 1  # F452: charge per entry
            if state["parts"] > _JS_EXPR_MAX_PARTS:
                raise _JSExprFail("too many parts")
    sj = _js_skip_ws(stmts, j)
    sj = _js_expect(stmts, sj, ";")
    return name, pairs, sj


def _js_parse_f669_map_sets(stmts, sj, name, pairs, depth, state):
    """Apply `(NAME.set(K,V);)*` mutations at stmts[sj] (F669).

    Node-exact (v24.20.0): K is a string literal or numeric literal
    (SameValueZero: 1 and '1' are distinct keys, the F494 kid
    discipline); V is a plain string literal; a later set on an
    existing key replaces the value at its original insertion
    position. Returns (pairs, next_index). Never evals.
    """
    n = len(stmts)
    pairs = list(pairs)
    index = {}
    for pos, (kid, _k, _v) in enumerate(pairs):
        index[kid] = pos
    while True:
        q = _js_skip_ws(stmts, sj)
        try:
            rname, q = _js_parse_ident(stmts, q)
        except _JSExprFail:
            break
        if rname != name:
            break
        q = _js_skip_ws(stmts, q)
        if q >= n or stmts[q] != ".":
            break
        q = _js_skip_ws(stmts, q + 1)
        try:
            mname, q = _js_parse_ident(stmts, q)
        except _JSExprFail:
            break
        if mname != "set":
            # Unmodeled mutation: fail the whole shape closed
            # rather than mis-decode (F599 precedent).
            raise _JSExprFail("F669 map member not set")
        q = _js_skip_ws(stmts, q)
        if q >= n or stmts[q] != "(":
            raise _JSExprFail("F669 set without paren")
        q = _js_skip_ws(stmts, q + 1)
        if q < n and stmts[q] in "'\"":
            kval, q = _js_parse_string(stmts, q)
            kid = ("s", kval)
        else:
            try:
                kstr, q = _js_parse_map_numkey(stmts, q)
            except _JSExprFail:
                raise _JSExprFail("F669 set key not a literal")
            kid = ("n", kstr)
        q = _js_skip_ws(stmts, q)
        if q >= n or stmts[q] != ",":
            raise _JSExprFail("F669 set arity")
        q = _js_skip_ws(stmts, q + 1)
        if q >= n or stmts[q] not in "'\"":
            raise _JSExprFail("F669 set value not a literal")
        vval, q = _js_parse_string(stmts, q)
        q = _js_skip_ws(stmts, q)
        if q >= n or stmts[q] != ")":
            raise _JSExprFail("F669 set unterminated")
        q = _js_skip_ws(stmts, q + 1)
        if q >= n or stmts[q] != ";":
            raise _JSExprFail("F669 set without semicolon")
        if kid in index:
            pairs[index[kid]] = (kid, kid[1], vval)
        else:
            index[kid] = len(pairs)
            pairs.append((kid, kid[1], vval))
        state["parts"] += 1  # the mutation is obfuscation-shaped
        if state["parts"] > _JS_EXPR_MAX_PARTS:
            raise _JSExprFail("too many parts")
        sj = q + 1
    return pairs, sj


def _js_parse_f669_spread_head(stmts, sj, name, allowed_members,
                               allow_bare):
    """Parse `return [...NAME(.values()|.keys())?` at stmts[sj] (F669).

    The spread must be the only array element (the F471 bounded
    scope); the member, when present, must be in allowed_members
    (bare spread allowed only when allow_bare -- a bare Map spread
    yields [k,v] pair arrays and fails closed). Returns
    (member, next_index): member is "values"/"keys", or None for a
    bare spread. Never evals.
    """
    n = len(stmts)
    q = _js_skip_ws(stmts, sj)
    m = _js_match_kw(stmts, q, "return")
    if m is None:
        raise _JSExprFail("F669 body not return")
    q = _js_skip_ws(stmts, m)
    q = _js_expect(stmts, q, "[")
    q = _js_skip_ws(stmts, q)
    if not stmts.startswith("...", q):
        raise _JSExprFail("F669 return not spread")
    q = _js_skip_ws(stmts, q + 3)
    rname, q = _js_parse_ident(stmts, q)
    if rname != name:
        raise _JSExprFail("F669 spreads another ident")
    q = _js_skip_ws(stmts, q)
    member = None
    if q < n and stmts[q] == ".":
        q = _js_skip_ws(stmts, q + 1)
        mname, q = _js_parse_ident(stmts, q)
        if mname not in allowed_members:
            raise _JSExprFail("F669 spread member not values/keys")
        q = _js_skip_ws(stmts, q)
        q = _js_expect(stmts, q, "(")
        q = _js_skip_ws(stmts, q)
        q = _js_expect(stmts, q, ")")
        q = _js_skip_ws(stmts, q)
        member = mname
    elif not allow_bare:
        raise _JSExprFail("F669 bare spread not values/keys")
    return member, q


def _js_parse_f669_spread_join(stmts, q, values, state):
    """Parse `].join(SEP);` at stmts[q], end-of-body (F669).

    `.join` takes a string-literal separator or no argument (","
    default, node-exact). Returns (joined, next_index) at
    end-of-body. Never evals.
    """
    n = len(stmts)
    q = _js_expect(stmts, q, "]")
    q = _js_skip_ws(stmts, q)
    q = _js_expect(stmts, q, ".")
    mname, q = _js_parse_ident(stmts, _js_skip_ws(stmts, q))
    if mname != "join":
        raise _JSExprFail("F669 return not join")
    q = _js_skip_ws(stmts, q)
    q = _js_expect(stmts, q, "(")
    q = _js_skip_ws(stmts, q)
    if q < n and stmts[q] == ")":
        sep = ","
        q += 1
    elif q < n and stmts[q] in "'\"":
        sep, q = _js_parse_string(stmts, q)
        q = _js_skip_ws(stmts, q)
        q = _js_expect(stmts, q, ")")
    else:
        raise _JSExprFail("F669 join separator not a literal")
    q = _js_skip_ws(stmts, q)
    if q < n and stmts[q] == ";":
        q += 1
    if _js_skip_ws(stmts, q) != len(stmts):
        raise _JSExprFail("F669 trailing statements")
    result = sep.join(values)
    if len(result) > _MAX_DECODE_BYTES:
        raise _JSExprFail("F669 join too long")
    state["ops"] += 1  # the spread-consume join is obfuscation-shaped
    return result, q


def _js_parse_f669_set_spread_iife(text, i, depth, state):
    """Parse `(function(){var|let|const NAME=new Set([LITS]);(NAME.add('LIT');)*return [...NAME(.values()|.keys())?].join(SEP);})()` (F669).

    Node-exact desugar (v24.20.0): Set spread preserves insertion
    order with SameValueZero first-occurrence dedup;
    `.values()`/`.keys()` are the same value iterator; `.add`
    appends with dedup; `.join(SEP)` uses a string-literal separator
    (no argument = ","). Returns (value, next_index), or None on
    mismatch/guard failure. Never evals.

    Bounds (all fail closed): non-literal elements, reassignment or
    extra statements, `.add` on another ident or with a non-literal
    arg, unmodeled members, spread of another ident, mixed spreads,
    a non-`join` terminal, non-literal separators, call args on the
    IIFE.
    """
    j = _js_parse_f6xx_iife_head(text, i)
    if j is None:
        return None
    try:
        brace = j
        inner_start, inner_end, j = _js_span_braced(text, brace)
        stmts = text[inner_start:inner_end]
        sj = _js_skip_ws(stmts, 0)
        name, elements, sj = _js_parse_f669_set_decl(stmts, sj, depth,
                                                     state)
        elements, sj = _js_parse_f669_set_adds(stmts, sj, name,
                                               elements, depth, state)
        _member, sj = _js_parse_f669_spread_head(
            stmts, sj, name, ("values", "keys"), True)
        value, sj = _js_parse_f669_spread_join(stmts, sj, elements,
                                               state)
        if depth >= _JS_EXPR_MAX_DEPTH:
            raise _JSExprFail("too deep")
        return _js_parse_f6xx_iife_tail(text, j, depth, state, value)
    except _JSExprFail:
        return None


def _js_parse_f669_map_values_spread_iife(text, i, depth, state):
    """Parse `(function(){var|let|const NAME=new Map();(NAME.set(K,V);)*return [...NAME.(values|keys)()].join(SEP);})()` and the `new Map([[K,V],...])` ctor-arg twin (F669).

    Node-exact desugar (v24.20.0): Map values/keys iterate in
    insertion order with later-wins on duplicate keys (the F494 kid
    discipline: 1 and '1' are distinct keys); a bare `[...NAME]`
    spread would yield [k,v] pair arrays and fails closed. Returns
    (value, next_index), or None on mismatch/guard failure. Never
    evals.

    Bounds (all fail closed): non-literal keys/values,
    reassignment or extra statements, `.set` on another ident,
    unmodeled members, bare Map spread, spread of another ident,
    mixed spreads, a non-`join` terminal, non-literal separators,
    call args on the IIFE.
    """
    j = _js_parse_f6xx_iife_head(text, i)
    if j is None:
        return None
    try:
        brace = j
        inner_start, inner_end, j = _js_span_braced(text, brace)
        stmts = text[inner_start:inner_end]
        sj = _js_skip_ws(stmts, 0)
        name, pairs, sj = _js_parse_f669_map_decl(stmts, sj, depth,
                                                  state)
        pairs, sj = _js_parse_f669_map_sets(stmts, sj, name, pairs,
                                            depth, state)
        member, sj = _js_parse_f669_spread_head(
            stmts, sj, name, ("values", "keys"), False)
        if member == "keys":
            values = [k for _kid, k, _v in pairs]
        elif member == "values":
            values = [v for _kid, _k, v in pairs]
        else:
            raise _JSExprFail("F669 map spread not values/keys")
        value, sj = _js_parse_f669_spread_join(stmts, sj, values,
                                               state)
        if depth >= _JS_EXPR_MAX_DEPTH:
            raise _JSExprFail("too deep")
        return _js_parse_f6xx_iife_tail(text, j, depth, state, value)
    except _JSExprFail:
        return None


_F745_SET_METHODS = ("union", "intersection", "difference")


def _js_f745_algebra(method, a_elements, b_elements):
    """Node-exact (v24.20.0) ES2025 set algebra over deduped string-element lists.

    union: A's insertion order, then B's elements not already
    present; intersection: A's elements that occur in B, in A's
    order; difference: A's elements absent from B, in A's order.
    SameValueZero is === for strings. Never evals.
    """
    if method == "union":
        _seen = set(a_elements)
        _res = list(a_elements)
        for _e in b_elements:
            if _e not in _seen:
                _seen.add(_e)
                _res.append(_e)
        return _res
    _bset = set(b_elements)
    if method == "intersection":
        return [_e for _e in a_elements if _e in _bset]
    return [_e for _e in a_elements if _e not in _bset]


def _js_parse_f745_new_set(stmts, j, depth, state):
    """Parse `new Set([LITS])` or `new Set()` at stmts[j] (F745).

    The empty-ctor form is the node-exact empty set; the
    literal form reuses the F602 element discipline (plain string
    literals, SameValueZero first-occurrence dedup, F452
    per-element parts charge). Returns (elements, next_index).
    Never evals.
    """
    n = len(stmts)
    q = _js_skip_ws(stmts, j)
    _nk = _js_match_kw(stmts, q, "new")
    if _nk is None:
        raise _JSExprFail("F745 not new")
    _se = _js_match_kw(stmts, _js_skip_ws(stmts, _nk), "Set")
    if _se is None:
        raise _JSExprFail("F745 not new Set")
    _pk = _js_skip_ws(stmts, _se)
    _pk = _js_expect(stmts, _pk, "(")
    _pk = _js_skip_ws(stmts, _pk)
    if _pk < n and stmts[_pk] == ")":
        return [], _pk + 1
    return _js_parse_f602_set_elements(stmts, q, depth, state)


def _js_f745_set_operand(stmts, j, env, depth, state):
    """Parse an F745 set operand at stmts[j]: `new Set([LITS])`,
    `new Set()`, or a bound set name.

    Returns (elements, next_index). Unbound names fail closed --
    the engine throws TypeError when a set-algebra method runs on
    a non-Set receiver/argument, so a miss here is never a
    mis-decode. Never evals.
    """
    q = _js_skip_ws(stmts, j)
    if _js_match_kw(stmts, q, "new") is not None:
        return _js_parse_f745_new_set(stmts, q, depth, state)
    name, q = _js_parse_ident(stmts, q)
    if name not in env:
        raise _JSExprFail("F745 unbound set name")
    return list(env[name]), q


def _js_parse_f745_set_expr(stmts, j, env, depth, state):
    """Parse `OPERAND (.union|.intersection|.difference(ARG))*` at stmts[j] (F745).

    Returns (elements, next_index, saw_algebra). Each algebra call
    applies `_js_f745_algebra` node-exactly; each result element
    charges one part (F452) and each call one op. A member that is
    not a set-algebra method stops the chain WITHOUT consuming it,
    leaving the caller to fail closed. Never evals.
    """
    n = len(stmts)
    elements, j = _js_f745_set_operand(stmts, j, env, depth, state)
    saw = False
    while True:
        q = _js_skip_ws(stmts, j)
        if q >= n or stmts[q] != ".":
            break
        q = _js_skip_ws(stmts, q + 1)
        try:
            mname, q = _js_parse_ident(stmts, q)
        except _JSExprFail:
            break
        if mname not in _F745_SET_METHODS:
            break  # not algebra: do not consume; caller fails closed
        q = _js_skip_ws(stmts, q)
        q = _js_expect(stmts, q, "(")
        q = _js_skip_ws(stmts, q)
        b_elements, q = _js_f745_set_operand(stmts, q, env, depth,
                                             state)
        q = _js_skip_ws(stmts, q)
        q = _js_expect(stmts, q, ")")
        elements = _js_f745_algebra(mname, elements, b_elements)
        for _ in elements:
            state["parts"] += 1
            if state["parts"] > _JS_EXPR_MAX_PARTS:
                raise _JSExprFail("F745 too many parts")
        state["ops"] += 1  # the algebra call is obfuscation-shaped
        saw = True
        j = q
    return elements, j, saw


def _js_parse_f745_decl(stmts, sj, env, depth, state):
    """Parse `var|let|const NAME = SETEXPR;` at stmts[sj] (F745).

    SETEXPR is an F745 set expression (plain `new Set([LITS])` or
    a set-algebra call chain). Binds NAME in env. Returns (name,
    elements, next_index, saw_algebra). Never evals.
    """
    n = len(stmts)
    m = _js_match_kw(stmts, sj, "var")
    if m is None:
        m = _js_match_kw(stmts, sj, "let")
    if m is None:
        m = _js_match_kw(stmts, sj, "const")
    if m is None:
        raise _JSExprFail("F745 decl not var/let/const")
    sj = _js_skip_ws(stmts, m)
    name, sj = _js_parse_ident(stmts, sj)
    if name in _F611_RESERVED or name == "arguments":
        raise _JSExprFail("F745 set binding reserved")
    sj = _js_skip_ws(stmts, sj)
    sj = _js_expect(stmts, sj, "=")
    sj = _js_skip_ws(stmts, sj)
    elements, sj, saw = _js_parse_f745_set_expr(stmts, sj, env,
                                                depth, state)
    sj = _js_skip_ws(stmts, sj)
    sj = _js_expect(stmts, sj, ";")
    env[name] = elements
    return name, elements, sj, saw


def _js_parse_f745_set_algebra_iife(text, i, depth, state):
    """Parse `(function(){(var|let|const NAME=SETEXPR;)+ return [...SETEXPR].join(SEP)(+'LIT')*;})()` (F745).

    ES2025 set-algebra fragment assembly: var-bound and inline
    `new Set([LITS])` operands composed with .union/.intersection/
    .difference, spread-joined, with an optional additive literal
    tail (the F713 tail discipline, shared helper). Node-exact
    (v24.20.0) via `_js_f745_algebra`. At least one algebra call
    must occur anywhere in the body: methodless shapes stay with
    F669 (tried earlier), so no previously-decoded input changes
    behavior.
    Returns (value, next_index), or None on mismatch/guard
    failure. Never evals.

    Bounds (all fail closed): non-literal elements, unbound names,
    non-Set receivers/args (the engine throws TypeError),
    unmodeled members (`.add`/`.values()` etc.), extra statements,
    non-literal join separators, call args on the IIFE.
    """
    j = _js_parse_f6xx_iife_head(text, i)
    if j is None:
        return None
    try:
        brace = j
        inner_start, inner_end, j = _js_span_braced(text, brace)
        stmts = text[inner_start:inner_end]
        sj = _js_skip_ws(stmts, 0)
        env = {}
        saw_algebra = False
        while True:
            q = _js_skip_ws(stmts, sj)
            if _js_match_kw(stmts, q, "return") is not None:
                break
            _name, _els, sj, _saw = _js_parse_f745_decl(
                stmts, sj, env, depth, state)
            saw_algebra = saw_algebra or _saw
        q = _js_match_kw(stmts, sj, "return")
        if q is None:
            raise _JSExprFail("F745 body not return")
        q = _js_skip_ws(stmts, q)
        q = _js_expect(stmts, q, "[")
        q = _js_skip_ws(stmts, q)
        if not stmts.startswith("...", q):
            raise _JSExprFail("F745 return not spread")
        q = _js_skip_ws(stmts, q + 3)
        elements, q, _saw = _js_parse_f745_set_expr(stmts, q, env,
                                                    depth, state)
        saw_algebra = saw_algebra or _saw
        if not saw_algebra:
            # Methodless: F669's territory (tried first); stay a miss.
            raise _JSExprFail("F745 no algebra call")
        value, q = _js_parse_f713_join_tail(stmts, q, elements,
                                            state)
        if depth >= _JS_EXPR_MAX_DEPTH:
            raise _JSExprFail("too deep")
        return _js_parse_f6xx_iife_tail(text, j, depth, state, value)
    except _JSExprFail:
        return None


def _js_parse_f713_join_tail(stmts, q, values, state):
    """Parse `].join(SEP)(+'LIT')*;` at stmts[q], end-of-body (F713).

    Like `_js_parse_f669_spread_join` but the join is NOT the
    terminal: an additive tail of plain string literals may follow
    (the F713 filed shapes append `+'f2'`). `.join` takes a
    string-literal separator or no argument ("," default,
    node-exact). Returns (joined, next_index) at end-of-body.
    Never evals.
    """
    n = len(stmts)
    q = _js_expect(stmts, q, "]")
    q = _js_skip_ws(stmts, q)
    q = _js_expect(stmts, q, ".")
    mname, q = _js_parse_ident(stmts, _js_skip_ws(stmts, q))
    if mname != "join":
        raise _JSExprFail("F713 return not join")
    q = _js_skip_ws(stmts, q)
    q = _js_expect(stmts, q, "(")
    q = _js_skip_ws(stmts, q)
    if q < n and stmts[q] == ")":
        sep = ","
        q += 1
    elif q < n and stmts[q] in "'\"":
        sep, q = _js_parse_string(stmts, q)
        q = _js_skip_ws(stmts, q)
        q = _js_expect(stmts, q, ")")
    else:
        raise _JSExprFail("F713 join separator not a literal")
    result = sep.join(values)
    q = _js_skip_ws(stmts, q)
    while q < n and stmts[q] == "+":
        q = _js_skip_ws(stmts, q + 1)
        if q >= n or stmts[q] not in "'\"":
            raise _JSExprFail("F713 tail not a string literal")
        tail, q = _js_parse_string(stmts, q)
        if isinstance(tail, _JSNumStr):
            raise _JSExprFail("F713 tail not a plain string")
        result += tail
        state["parts"] += 1  # the additive tail is obfuscation-shaped
        if state["parts"] > _JS_EXPR_MAX_PARTS:
            raise _JSExprFail("too many parts")
    q = _js_skip_ws(stmts, q)
    if q < n and stmts[q] == ";":
        q += 1
    if _js_skip_ws(stmts, q) != len(stmts):
        raise _JSExprFail("F713 trailing statements")
    if len(result) > _MAX_DECODE_BYTES:
        raise _JSExprFail("F713 join too long")
    state["ops"] += 1  # the spread-consume join is obfuscation-shaped
    return result, q


def _js_parse_f713_map_spread_join_tail_iife(text, i, depth, state):
    """Parse `(function(){var|let|const NAME=new Map([[K,V],...]);(NAME.set(K,V);)*return [...NAME(.values()|.keys())?].join(SEP)(+'LIT')*;})()` (F713).

    F669 residual: F669's `_js_parse_f669_map_values_spread_iife`
    requires the join to be the return terminal and fails closed on
    bare Map spreads; the filed shapes append an additive tail
    (`+'f2'`) after the join, and the bare-spread twin spreads the
    literal Map directly. Node-exact desugar (v24.20.0):
    - decl: `var|let|const NAME=new Map([[K,V],...]);` (literal
      ctor, the F494 kid discipline) or `new Map();` with
      `.set(K,V);` tails -- shared `_js_parse_f669_map_decl` /
      `_js_parse_f669_map_sets`.
    - spread: `[...NAME.values()]` / `[...NAME.keys()]` iterate in
      insertion order (later-wins, F494); a BARE `[...NAME]`
      yields [k,v] pair arrays, each stringifying node-exactly as
      `k + ',' + v` (Array.prototype.toString joins the pair with
      ","; numeric keys stringify canonically via _JSNumStr's str).
    - terminal: `.join(SEP)` (string-literal SEP or no-arg ",")
      then zero or more `+'LIT'` additive tail elements, then `;`
      end-of-body.
    Returns (value, next_index), or None on mismatch/guard
    failure. Never evals.

    Bounds (all fail closed): non-literal keys/values,
    reassignment or extra statements, `.set` on another ident,
    unmodeled members, spread of another ident, mixed spreads, a
    non-`join` terminal, non-literal separators or tail elements,
    call args on the IIFE.
    Disjoint from F669 (tried after it): F669 requires the join
    terminal with no tail and fails closed on bare spreads; this
    route requires the F713 tail-or-bare shape and fails closed on
    F669's exact terminal (the tail loop accepts zero elements, but
    F669's parser wins those shapes first, so no
    previously-decoded input changes behavior).
    """
    j = _js_parse_f6xx_iife_head(text, i)
    if j is None:
        return None
    try:
        brace = j
        inner_start, inner_end, j = _js_span_braced(text, brace)
        stmts = text[inner_start:inner_end]
        sj = _js_skip_ws(stmts, 0)
        name, pairs, sj = _js_parse_f669_map_decl(stmts, sj, depth,
                                                  state)
        pairs, sj = _js_parse_f669_map_sets(stmts, sj, name, pairs,
                                            depth, state)
        member, sj = _js_parse_f669_spread_head(
            stmts, sj, name, ("values", "keys"), True)
        if member == "keys":
            values = [str(k) for _kid, k, _v in pairs]
        elif member == "values":
            values = [v for _kid, _k, v in pairs]
        elif member is None:
            # Bare spread: each [k,v] pair stringifies as k+','+v
            # (node v24.20.0: Array.prototype.toString on the pair).
            values = [str(k) + "," + v for _kid, k, v in pairs]
        else:
            raise _JSExprFail("F713 map spread not values/keys")
        value, sj = _js_parse_f713_join_tail(stmts, sj, values,
                                             state)
        if depth >= _JS_EXPR_MAX_DEPTH:
            raise _JSExprFail("too deep")
        return _js_parse_f6xx_iife_tail(text, j, depth, state, value)
    except _JSExprFail:
        return None


def _js_parse_f681_mutator_iife(text, i, depth, state):
    """Parse `(function(){DECL NAME=['LIT',...];STMT*;
    return NAME.join(SEP);})()` (F681).

    Array-mutator fragment assembly beyond F658: a var-bound
    string-literal array mutated by splice/fill statements, then
    joined. Node-exact desugar (v24.20.0):
    - decl: `var|let|const NAME=['LIT',...];` -- string literals
      only (the F644 array grammar); `const` is fine (mutation is
      not reassignment).
    - 1..8 mutation statements, each `NAME.splice(S,D);` or
      `NAME.fill(V,S,E);` on the bound ident:
      - splice(start, deleteCount): start normalized exactly as the
        engine does (negative counts back from the end, clamped to
        [0, len]); deleteCount clamped to [0, len-start]; the
        elements [start, start+deleteCount) are removed.
      - fill(value, start, end): value a string literal; start/end
        literal ints (negative counts back, clamped); elements
        [start, end) are set to value.
      - Only the exact 2-arg splice and 3-arg fill forms are
        modeled; splice insertion args (3+), 1-arg fill, and
        non-literal args fail closed.
    - return: `NAME.join('SEP');` / `NAME.join();` on the bound
      ident (the F434 join discipline; the mutated elements are all
      plain strings).
    - invocation: exactly `()`.
    Disjoint from every earlier IIFE route: F655's statement
    simulator fails closed on splice/fill call statements (they are
    neither declarations nor accumulations); F654 requires a for-of
    head; F611 requires a single declaration; F646 requires a
    forEach head. None of the earlier routes decodes any shape this
    accepts (red-first verified: 2 BREAK on the open tree), so no
    previously-decoded input changes behavior. Tried after F664.
    Bounds (all fail closed -- rejected, never mis-decoded):
    - a named function, parameters, a directive prologue, extra
      statements, reassignment of the array var, non-empty call
      args, more than 8 mutation statements;
    - a non-literal array element, fill value, or join separator;
      a fractional splice/fill index (unconsumed `.5` fails the
      `,`/`)` expect).
    Returns (value, next_index), or None when text[i] is not this
    shape. Never evals.
    """
    n = len(text)
    if depth >= _JS_EXPR_MAX_DEPTH:
        return None
    try:
        j = _js_skip_ws(text, i)
        if j >= n or text[j] != "(":
            return None
        k = _js_skip_ws(text, j + 1)
        if not text.startswith("function", k):
            return None
        k2 = k + len("function")
        if k2 < n and text[k2] in _JS_IDENT_CONT:
            return None  # functionx -- not our shape
        if k2 < n and text[k2] in _JS_IDENT_START:
            return None  # named function -- not our shape
        j = _js_skip_ws(text, k2)
        j = _js_expect(text, j, "(")
        j = _js_expect(text, j, ")")
        brace = _js_skip_ws(text, j)
        j = _js_expect(text, brace, "{")
        inner_start, inner_end, j = _js_span_braced(text, brace)
        sj = _js_skip_ws(text, inner_start)
        _kw, m = _js_match_decl_kw(text, sj)
        if _kw is None:
            raise _JSExprFail("F681 decl not var/const/let")
        sj = _js_skip_ws(text, m)
        aname, sj = _js_parse_ident(text, sj)
        if aname == "arguments" or aname in _F611_RESERVED:
            raise _JSExprFail("F681 reserved binding name")
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, "=")
        sj = _js_skip_ws(text, sj)
        if sj >= n or text[sj] != "[":
            raise _JSExprFail("F681 source not an array literal")
        elems, sj = _js_parse_f644_string_array(text, sj, state)
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, ";")
        # 1..8 mutation statements on the bound array.
        nstmt = 0
        while True:
            sj = _js_skip_ws(text, sj)
            q = sj
            try:
                qname, q = _js_parse_ident(text, q)
            except _JSExprFail:
                break
            if qname != aname:
                break
            q = _js_skip_ws(text, q)
            if q >= n or text[q] != ".":
                break
            try:
                mname, q = _js_parse_ident(text, _js_skip_ws(text,
                                                             q + 1))
            except _JSExprFail:
                break
            if mname not in ("splice", "fill"):
                break
            # Committed: a mutation statement on the bound array --
            # malformed shapes fail closed from here.
            q = _js_skip_ws(text, q)
            q = _js_expect(text, q, "(")
            if mname == "splice":
                start, q = _js_parse_slice_int(text,
                                               _js_skip_ws(text, q))
                q = _js_skip_ws(text, q)
                q = _js_expect(text, q, ",")
                dcount, q = _js_parse_slice_int(text,
                                                _js_skip_ws(text, q))
                q = _js_skip_ws(text, q)
                q = _js_expect(text, q, ")")
                ln = len(elems)
                s = ln + start if start < 0 else start
                s = max(0, min(s, ln))
                dc = max(0, min(dcount, ln - s))
                del elems[s:s + dc]
            else:
                q = _js_skip_ws(text, q)
                if q >= n or text[q] not in "'\"":
                    raise _JSExprFail("F681 fill value not a literal")
                fval, q = _js_parse_string(text, q)
                q = _js_skip_ws(text, q)
                q = _js_expect(text, q, ",")
                fstart, q = _js_parse_slice_int(text,
                                                _js_skip_ws(text, q))
                q = _js_skip_ws(text, q)
                q = _js_expect(text, q, ",")
                fend, q = _js_parse_slice_int(text,
                                              _js_skip_ws(text, q))
                q = _js_skip_ws(text, q)
                q = _js_expect(text, q, ")")
                ln = len(elems)
                rs = ln + fstart if fstart < 0 else fstart
                rs = max(0, min(rs, ln))
                re_ = ln + fend if fend < 0 else fend
                re_ = max(0, min(re_, ln))
                for _fi in range(rs, re_):
                    elems[_fi] = fval
                state["parts"] += 1
                if state["parts"] > _JS_EXPR_MAX_PARTS:
                    raise _JSExprFail("too many parts")
            q = _js_skip_ws(text, q)
            q = _js_expect(text, q, ";")
            state["ops"] += 1  # the mutation is obfuscation-shaped
            nstmt += 1
            if nstmt > 8:
                raise _JSExprFail("F681 too many mutations")
            sj = q
        if nstmt == 0:
            raise _JSExprFail("F681 no mutation statement")
        # Return: `NAME.join('SEP');` / `NAME.join();`.
        sj = _js_skip_ws(text, sj)
        m = _js_match_kw(text, sj, "return")
        if m is None:
            raise _JSExprFail("F681 no return")
        sj = _js_skip_ws(text, m)
        rname, sj = _js_parse_ident(text, sj)
        if rname != aname:
            raise _JSExprFail("F681 return not over bound array")
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, ".")
        jname, sj = _js_parse_ident(text, _js_skip_ws(text, sj))
        if jname != "join":
            raise _JSExprFail("F681 return not join")
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, "(")
        sj = _js_skip_ws(text, sj)
        if sj < n and text[sj] == ")":
            sep = ","
            sj += 1
        elif sj < n and text[sj] in "'\"":
            sep, sj = _js_parse_string(text, sj)
            sj = _js_skip_ws(text, sj)
            sj = _js_expect(text, sj, ")")
        else:
            raise _JSExprFail("F681 join separator not a literal")
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, ";")
        sj = _js_skip_ws(text, sj)
        if sj != inner_end:
            raise _JSExprFail("F681 trailing statements")
        result = sep.join(elems)
        if len(result) > _MAX_DECODE_BYTES:
            raise _JSExprFail("F681 join too long")
        state["ops"] += 1  # the join is obfuscation-shaped
        # Invocation: exactly `()`.
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, "(")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        state["ops"] += 1  # the iife wrapper is obfuscation-shaped
        return result, j
    except _JSExprFail:
        return None


def _js_parse_f684_defaultref_params_iife(text, i, depth, state):
    """Parse `(function({K=V,...}={}){return ADD;})(...)` (F684a).

    Destructuring residual beyond F644/F645: an object-pattern
    parameter whose per-key defaults reference earlier-bound keys.
    Node-exact desugar (v24.20.0): with the call supplying no
    arguments (or `undefined`), the pattern default `{}` applies;
    each key's default evaluates left-to-right, so a default may
    reference earlier keys (`{a='f1',b=a+'f2'}` binds a='f1' then
    b='f1f2'); a forward reference throws ReferenceError in the
    engine (temporal dead zone) -- the left-to-right parse fails
    it closed the same way. The return body resolves bound idents
    via the F645 bound-additive grammar.
    Disjoint from F645: F645's pattern loop fails closed on `=`
    after a key (per-key defaults are its documented residual);
    this requires `=` after EVERY key and the pattern default
    exactly `={}`. Disjoint from F644: F644 has no parameters.
    Bounds (all fail closed -- rejected, never mis-decoded):
    - a named function, extra params, a non-`={}` pattern default,
      a key without a default, a non-additive default, an unbound
      name in a default (TDZ), non-empty non-undefined call args;
    - more than 8 keys (the F430 parts budget also applies).
    Returns (value, next_index), or None when text[i] is not this
    shape. Never evals.
    """
    n = len(text)
    if depth >= _JS_EXPR_MAX_DEPTH:
        return None
    try:
        j = _js_skip_ws(text, i)
        if j >= n or text[j] != "(":
            return None
        k = _js_skip_ws(text, j + 1)
        if not text.startswith("function", k):
            return None
        k2 = k + len("function")
        if k2 < n and text[k2] in _JS_IDENT_CONT:
            return None  # functionx -- not our shape
        if k2 < n and text[k2] in _JS_IDENT_START:
            return None  # named function -- not our shape
        j = _js_skip_ws(text, k2)
        j = _js_expect(text, j, "(")
        j = _js_skip_ws(text, j)
        if j >= n or text[j] != "{":
            return None  # not an object-pattern param
        j = _js_skip_ws(text, j + 1)
        bindings = {}
        nkeys = 0
        while True:
            j = _js_skip_ws(text, j)
            _kn, j = _js_parse_ident(text, j)
            if _kn in bindings or _kn == "arguments":
                raise _JSExprFail("F684a duplicate/reserved key")
            j = _js_skip_ws(text, j)
            # Per-key default REQUIRED (the F645 residual); a bare
            # key falls through to F645's fail-closed path.
            if j >= n or text[j] != "=":
                return None
            j = _js_skip_ws(text, j + 1)
            _dv, j = _js_parse_f645_bound_additive(text, j, depth,
                                                   state, bindings)
            bindings[_kn] = _dv
            nkeys += 1
            if nkeys > 8:
                raise _JSExprFail("F684a too many keys")
            state["ops"] += 1  # each default is obfuscation-shaped
            j = _js_skip_ws(text, j)
            if j < n and text[j] == ",":
                j = _js_skip_ws(text, j + 1)
                continue
            if j < n and text[j] == "}":
                j += 1
                break
            raise _JSExprFail("F684a bad pattern")
        if not bindings:
            return None  # empty pattern -- not our shape
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, "=")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, "{")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, "}")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        brace = _js_skip_ws(text, j)
        j = _js_expect(text, brace, "{")
        inner_start, inner_end, j = _js_span_braced(text, brace)
        sj = _js_skip_ws(text, inner_start)
        m = _js_match_kw(text, sj, "return")
        if m is None:
            raise _JSExprFail("F684a no return")
        sj = _js_skip_ws(text, m)
        val, sj = _js_parse_f645_bound_additive(text, sj, depth,
                                                state, bindings)
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, ";")
        sj = _js_skip_ws(text, sj)
        if sj != inner_end:
            raise _JSExprFail("F684a trailing statements")
        # Close the `(function` wrapper, then the invocation.
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        j = _js_parse_f645_invocation(text, j)
        state["ops"] += 1  # the iife wrapper is obfuscation-shaped
        return val, j
    except _JSExprFail:
        return None


def _js_parse_f684_nested_pattern(text, j, depth, state):
    """Parse an F684b destructuring pattern `{k:v,...}` at text[j].

    Entries: `key` (shorthand), `key:leaf`, or `key:{...}`
    (nested). Returns (entries, has_nested, next_index) where each
    entry is (key, leaf_name_or_None, subpattern_or_None). Depth-
    bounded. Raises _JSExprFail on malformed patterns. Never evals.
    """
    n = len(text)
    if depth >= _JS_EXPR_MAX_DEPTH:
        raise _JSExprFail("F684b pattern too deep")
    j = _js_skip_ws(text, j)
    j = _js_expect(text, j, "{")
    entries = []
    has_nested = False
    j = _js_skip_ws(text, j)
    if j < n and text[j] == "}":
        raise _JSExprFail("F684b empty pattern")
    while True:
        j = _js_skip_ws(text, j)
        _key, j = _js_parse_ident(text, j)
        j = _js_skip_ws(text, j)
        if j < n and text[j] == ":":
            j = _js_skip_ws(text, j + 1)
            if j < n and text[j] == "{":
                _sub, _hn, j = _js_parse_f684_nested_pattern(
                    text, j, depth + 1, state)
                entries.append((_key, None, _sub))
                has_nested = True
            else:
                _leaf, j = _js_parse_ident(text, j)
                entries.append((_key, _leaf, None))
        else:
            entries.append((_key, _key, None))
        j = _js_skip_ws(text, j)
        if j < n and text[j] == ",":
            j = _js_skip_ws(text, j + 1)
            continue
        if j < n and text[j] == "}":
            return entries, has_nested, j + 1
        raise _JSExprFail("F684b bad pattern")


def _js_f684_bind_nested(entries, props, names, raws, state):
    """Bind F684b pattern entries against F535 props (recursive).

    Leaf entries bind the source's string value (re-quoted for the
    F644 rewrite); nested entries recurse into _JSObj values. A
    missing key, a non-string leaf, a non-object nested source, or
    a duplicate bound name fails closed (the engine's semantics
    for the first three are a throw or a mis-decode risk; duplicate
    later-wins is unmodeled -- fail closed, never mis-decoded).
    Never evals.
    """
    for _key, _leaf, _sub in entries:
        if _key not in props:
            raise _JSExprFail("F684b key missing from source")
        _v = props[_key]
        if _sub is not None:
            if not isinstance(_v, _JSObj):
                raise _JSExprFail("F684b nested source not an object")
            _js_f684_bind_nested(_sub, _v.props, names, raws, state)
        else:
            if not isinstance(_v, str):
                raise _JSExprFail("F684b leaf not a string")
            if _leaf in names or _leaf == "arguments":
                raise _JSExprFail("F684b duplicate/reserved name")
            names.append(_leaf)
            raws.append("'" + _v.replace("\\", "\\\\").replace(
                "'", "\\'") + "'")
            state["parts"] += 1
            if state["parts"] > _JS_EXPR_MAX_PARTS:
                raise _JSExprFail("too many parts")


def _js_parse_f684_nested_destructure_iife(text, i, depth, state):
    """Parse `(function(){DECL PAT={LIT};return ADD;})()` with a
    NESTED object pattern (F684b).

    Destructuring residual beyond F644: F644 models flat patterns
    only (`{a,b}`, `{a:x}`); a nested pattern (`{x:{y}}`) fails
    closed there. Node-exact desugar (v24.20.0): the pattern walks
    against the F535 object-literal source (duplicate keys
    later-wins, `__proto__` fails closed -- the F535 grammar);
    each leaf binds its string value; the return body rewrites via
    the F644 destructure substitution (`_js_bind_destructure_
    arguments`) and parses with the normal additive grammar.
    Disjoint from F644: F644 fails closed on `{` after `key:`
    (its rename parse expects an ident); this requires at least
    one nested sub-pattern. Tried after F664 (after F644 in the
    chain, so F644's flat shapes never reach here).
    Bounds (all fail closed -- rejected, never mis-decoded):
    - a flat pattern (F644 owns it), a named function, parameters,
      a directive prologue, extra statements, multi-decl,
      non-empty call args, reassignment (constructive grammar);
    - a binding source outside the F535 object-literal grammar;
    - a missing key, a non-string leaf, a non-object nested
      source, a duplicate bound name.
    Returns (value, next_index), or None when text[i] is not this
    shape. Never evals.
    """
    n = len(text)
    if depth >= _JS_EXPR_MAX_DEPTH:
        return None
    try:
        j = _js_skip_ws(text, i)
        if j >= n or text[j] != "(":
            return None
        k = _js_skip_ws(text, j + 1)
        if not text.startswith("function", k):
            return None
        k2 = k + len("function")
        if k2 < n and text[k2] in _JS_IDENT_CONT:
            return None  # functionx -- not our shape
        if k2 < n and text[k2] in _JS_IDENT_START:
            return None  # named function -- not our shape
        j = _js_skip_ws(text, k2)
        j = _js_expect(text, j, "(")
        j = _js_expect(text, j, ")")
        brace = _js_skip_ws(text, j)
        j = _js_expect(text, brace, "{")
        inner_start, inner_end, j = _js_span_braced(text, brace)
        sj = _js_skip_ws(text, inner_start)
        _kw, m = _js_match_decl_kw(text, sj)
        if _kw is None:
            return None  # not a decl -- F644's fail-closed path
        sj = _js_skip_ws(text, m)
        sj = _js_skip_ws(text, sj)
        if sj >= n or text[sj] != "{":
            return None  # not a pattern -- F644 owns flat idents
        entries, has_nested, sj = _js_parse_f684_nested_pattern(
            text, sj, depth, state)
        if not has_nested:
            return None  # flat pattern -- F644 owns it
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, "=")
        sj = _js_skip_ws(text, sj)
        props, sj = _js_parse_f535_object(text, sj, depth, state)
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, ";")
        names = []
        raws = []
        _js_f684_bind_nested(entries, props, names, raws, state)
        sj = _js_skip_ws(text, sj)
        m = _js_match_kw(text, sj, "return")
        if m is None:
            raise _JSExprFail("F684b no return")
        body_expr = _js_require_single_return(text[sj:inner_end])
        rewritten = _js_bind_destructure_arguments(
            body_expr, raws, names, list(range(len(names))))
        val, _k = _js_parse_additive(rewritten, 0, depth + 1, state)
        _k = _js_skip_ws(rewritten, _k)
        if _k != len(rewritten):
            raise _JSExprFail("F684b return not an additive")
        if not isinstance(val, str):
            raise _JSExprFail("F684b return not a string")
        state["ops"] += 1  # the destructure is obfuscation-shaped
        # Invocation: exactly `()`.
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, "(")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        state["ops"] += 1  # the iife wrapper is obfuscation-shaped
        return val, j
    except _JSExprFail:
        return None


def _js_parse_f693_destructure_default_iife(text, i, depth, state):
    """Parse `(function(){var {K:PAT=DEF}=SRC;return ADD;})()` (F693).

    Destructuring residuals beyond F644/F684: per-key DEFAULTS on
    nested/array patterns with a literal source. Two productions
    (node v24.20.0):
    - rename-nested: `var {a:{b:c}={b:'f1'}}={};` -- key `a` is
      missing from the source, so the per-key default `{b:'f1'}`
      applies (a default applies exactly when the value is
      `undefined`); the nested pattern binds `c` from the default
      object;
    - array-default: `var {a:[b,c]=['f1','f2']}={};` -- the same
      default rule; the default array destructures positionally.
    The source is a literal object (`{}` in the filed shapes); when
    the key IS present in the source the decoder fails closed
    (never mis-decodes -- the present-key form is a documented
    residual, unmodeled).
    Disjoint from F644 (flat patterns -- its splitter fails closed
    on `{` after `key:`), F684a (parameter patterns), and F684b
    (nested patterns WITHOUT defaults -- its pattern parser fails
    closed on `=` after a sub-pattern). Tried after F684b.
    Bounds (all fail closed -- rejected, never mis-decoded):
    - a named function, parameters, a directive prologue, extra
      statements, multi-decl, reassignment, non-empty call args;
    - flat/shorthand/rename-without-default entries (F644/F684b
      own them), a key present in the source, a non-`{}`/non-literal
      source;
    - a nested sub-pattern entry that is not `ident:ident`
      (deeper nesting, string/numeric keys, leaf defaults fail
      closed), a default object with non-string values, a default
      array with non-string elements, fewer default elements than
      pattern names, a duplicate or `arguments` bound name;
    - more than 8 entries (the F430 parts budget also applies).
    Returns (value, next_index), or None when text[i] is not this
    shape. Never evals.
    """
    n = len(text)
    if depth >= _JS_EXPR_MAX_DEPTH:
        return None
    if not _js_peek_arguments_iife_head(text, i):
        return None
    try:
        j = _js_skip_ws(text, i)
        j = _js_expect(text, j, "(")
        j = _js_skip_ws(text, j) + len("function")
        j = _js_expect(text, j, "(")
        j = _js_expect(text, j, ")")
        brace = _js_skip_ws(text, j)
        j = _js_expect(text, brace, "{")
        inner_start, inner_end, j = _js_span_braced(text, brace)
        sj = _js_skip_ws(text, inner_start)
        _kw, m = _js_match_decl_kw(text, sj)
        if _kw is None:
            return None  # not a decl
        sj = _js_skip_ws(text, m)
        if sj >= n or text[sj] != "{":
            return None  # not an object pattern
        sj = _js_skip_ws(text, sj + 1)
        entries = []  # (key, kind, subnames, default)
        while True:
            sj = _js_skip_ws(text, sj)
            if sj >= n:
                raise _JSExprFail("F693 bad pattern")
            if text[sj] == "}":
                sj += 1
                break
            key, sj = _js_parse_ident(text, sj)
            sj = _js_skip_ws(text, sj)
            sj = _js_expect(text, sj, ":")
            sj = _js_skip_ws(text, sj)
            if sj < n and text[sj] == "{":
                # Branch A: nested object sub-pattern with a
                # per-key default object.
                sj = _js_skip_ws(text, sj + 1)
                sub = []
                while True:
                    sj = _js_skip_ws(text, sj)
                    sk, sj = _js_parse_ident(text, sj)
                    sj = _js_skip_ws(text, sj)
                    sj = _js_expect(text, sj, ":")
                    sj = _js_skip_ws(text, sj)
                    nm, sj = _js_parse_ident(text, sj)
                    sub.append((sk, nm))
                    sj = _js_skip_ws(text, sj)
                    if sj < n and text[sj] == ",":
                        sj = _js_skip_ws(text, sj + 1)
                        continue
                    if sj < n and text[sj] == "}":
                        sj += 1
                        break
                    raise _JSExprFail("F693 bad sub-pattern")
                if not sub:
                    raise _JSExprFail("F693 empty sub-pattern")
                sj = _js_skip_ws(text, sj)
                sj = _js_expect(text, sj, "=")
                sj = _js_skip_ws(text, sj)
                if sj >= n or text[sj] != "{":
                    raise _JSExprFail("F693 default not an object")
                dkeys, dvals, sj = _js_parse_object_literal_keys_values(
                    text, sj, depth, state)
                dmap = dict(zip(dkeys, dvals))
                entries.append((key, "obj", sub, dmap))
            elif sj < n and text[sj] == "[":
                # Branch B: array sub-pattern with a per-key
                # default array.
                sj = _js_skip_ws(text, sj + 1)
                sub = []
                while True:
                    sj = _js_skip_ws(text, sj)
                    nm, sj = _js_parse_ident(text, sj)
                    sub.append(nm)
                    sj = _js_skip_ws(text, sj)
                    if sj < n and text[sj] == ",":
                        sj = _js_skip_ws(text, sj + 1)
                        continue
                    if sj < n and text[sj] == "]":
                        sj += 1
                        break
                    raise _JSExprFail("F693 bad array pattern")
                if not sub:
                    raise _JSExprFail("F693 empty array pattern")
                sj = _js_skip_ws(text, sj)
                sj = _js_expect(text, sj, "=")
                sj = _js_skip_ws(text, sj)
                if sj >= n or text[sj] != "[":
                    raise _JSExprFail("F693 default not an array")
                elems, sj = _js_parse_f644_string_array(text, sj,
                                                       state)
                entries.append((key, "arr", sub, elems))
            else:
                # A flat/shorthand/rename entry without a default --
                # F644/F684b own those shapes.
                return None
            sj = _js_skip_ws(text, sj)
            if sj < n and text[sj] == ",":
                sj = _js_skip_ws(text, sj + 1)
                continue
            if sj < n and text[sj] == "}":
                sj += 1
                break
            raise _JSExprFail("F693 bad pattern")
        if not entries:
            return None  # empty pattern -- not our shape
        if len(entries) > 8:
            raise _JSExprFail("F693 too many entries")
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, "=")
        sj = _js_skip_ws(text, sj)
        if sj >= n or text[sj] != "{":
            return None  # not a literal-object source
        skeys, _svals, sj = _js_parse_object_literal_keys_values(
            text, sj, depth, state)
        sset = set(skeys)
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, ";")
        names = []
        raws = []
        for key, kind, sub, dflt in entries:
            if key in sset:
                # The key is present in the source: its default
                # does NOT apply and the nested/array pattern would
                # bind from the present value -- unmodeled, fail
                # closed (never mis-decoded).
                raise _JSExprFail("F693 key present in source")
            if kind == "obj":
                for sk, nm in sub:
                    if sk not in dflt:
                        raise _JSExprFail(
                            "F693 sub-key missing from default")
                    dv = dflt[sk]
                    if type(dv) is not str:
                        # A numeric/non-string default value would
                        # need the F475 provenance model -- fail
                        # closed rather than mis-decode.
                        raise _JSExprFail(
                            "F693 default value not a string")
                    if nm == "arguments" or nm in names:
                        raise _JSExprFail(
                            "F693 duplicate/reserved name")
                    names.append(nm)
                    raws.append("'" + dv.replace("\\", "\\\\").replace(
                        "'", "\\'") + "'")
                    state["parts"] += 1
                    if state["parts"] > _JS_EXPR_MAX_PARTS:
                        raise _JSExprFail("too many parts")
            else:
                if len(sub) > len(dflt):
                    # Node binds `undefined` for the missing
                    # elements -- the decoder never guesses.
                    raise _JSExprFail("F693 default too short")
                for t, nm in enumerate(sub):
                    if nm == "arguments" or nm in names:
                        raise _JSExprFail(
                            "F693 duplicate/reserved name")
                    names.append(nm)
                    dv = dflt[t]
                    raws.append("'" + dv.replace("\\", "\\\\").replace(
                        "'", "\\'") + "'")
                    state["parts"] += 1
                    if state["parts"] > _JS_EXPR_MAX_PARTS:
                        raise _JSExprFail("too many parts")
        sj = _js_skip_ws(text, sj)
        m = _js_match_kw(text, sj, "return")
        if m is None:
            raise _JSExprFail("F693 no return")
        body_expr = _js_require_single_return(text[sj:inner_end])
        rewritten = _js_bind_destructure_arguments(
            body_expr, raws, names, list(range(len(names))))
        val, _k = _js_parse_additive(rewritten, 0, depth + 1, state)
        _k = _js_skip_ws(rewritten, _k)
        if _k != len(rewritten):
            raise _JSExprFail("F693 return not an additive")
        if not isinstance(val, str):
            raise _JSExprFail("F693 return not a string")
        state["ops"] += 1  # the destructure is obfuscation-shaped
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, "(")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        state["ops"] += 1  # the iife wrapper is obfuscation-shaped
        return val, j
    except _JSExprFail:
        return None


def _js_parse_f729_void_stmt_iife(text, i, depth, state):
    """Parse `(function(){var|let|const NAME='LIT';void OPERAND;return EXPR;})()` (F729).

    Void-operator STATEMENT residual beyond F647: F647 models `void`
    only in nullish-coalescing LEFT position (`(void 0??'f1')`); a
    `void` statement (`void x;`) fails every statement grammar
    closed, so the whole IIFE misses while node evaluates the
    fragment read exactly (v24.20.0).

    Node-exact desugar: `void OPERAND` evaluates OPERAND and discards
    the value (always undefined). The modeled OPERANDs are exactly
    the side-effect-free, non-throwing forms: the bound NAME, a
    string / numeric literal, or the `null` / `undefined` / `true` /
    `false` keywords. Anything else fails closed -- a member read
    could invoke a getter, a call could have effects, and an unbound
    identifier throws ReferenceError in the engine (verified
    v24.20.0). The void statement contributes no fragments; the
    return body is processed with the F611 substitution discipline
    (value-position uses only, reassignment guards).

    Disjoint from every earlier route: F611 requires `return`
    immediately after the decl `;`; F655/F679's statement dispatch
    fails closed on `void`; F647 requires a `??` group; F702/F703
    requires Object.assign / __defineGetter__. Tried after F702/F703
    (the last hook before the additive fallback). Returns (value,
    next_index), or None when text[i] is not this shape. Never evals.
    """
    n = len(text)
    if depth >= _JS_EXPR_MAX_DEPTH:
        return None
    if not _js_peek_arguments_iife_head(text, i):
        return None
    try:
        j = _js_skip_ws(text, i)
        j = _js_expect(text, j, "(")
        j = _js_skip_ws(text, j + len("function"))
        j = _js_expect(text, j, "(")
        j = _js_expect(text, j, ")")
        brace = _js_skip_ws(text, j)
        j = _js_expect(text, brace, "{")
        inner_start, inner_end, j = _js_span_braced(text, brace)
        sj = _js_skip_ws(text, inner_start)
        _kw, m = _js_match_decl_kw(text, sj)
        if _kw is None:
            return None  # not a decl -- other routes own it
        sj = _js_skip_ws(text, m)
        name, sj = _js_parse_ident(text, sj)
        if name in _F611_RESERVED or name == "arguments":
            return None  # node throws SyntaxError; never decode
        sj = _js_skip_ws(text, sj)
        if sj >= n or text[sj] != "=" or text[sj + 1:sj + 2] in ("=", ">"):
            return None
        sj = _js_skip_ws(text, sj + 1)
        if text.startswith("atob", sj) and (sj + 4 >= n
                                            or text[sj + 4]
                                            not in _JS_IDENT_CONT):
            init_val, sj = _js_parse_f611_atob(text, sj)
            state["ops"] += 1  # the decode call is obfuscation-shaped
        elif sj < n and text[sj] in "'\"":
            init_val, sj = _js_parse_string(text, sj)
        else:
            return None  # F611 owns other initializers
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, ";")
        # The void statement: `void OPERAND;` -- value discarded.
        vk = _js_match_kw(text, _js_skip_ws(text, sj), "void")
        if vk is None:
            return None  # no void statement -- other routes own it
        sj = _js_skip_ws(text, vk)
        if sj < n and text[sj] in "'\"":
            _, sj = _js_parse_string(text, sj)
        elif sj < n and text[sj] in _ASCII_DIGITS:
            # Numeric literal operand -- value discarded.
            _, sj = _js_parse_number(text, sj)
        elif sj < n and text[sj] in _JS_IDENT_START:
            oname, sj = _js_parse_ident(text, sj)
            if oname in ("null", "undefined", "true", "false"):
                pass  # keyword operand -- no effect, no throw
            elif oname != name:
                # Unbound (or foreign) identifier: the engine throws
                # ReferenceError, so decoding would mis-model.
                # A getter-carrying member read is not an ident at
                # all -- it fails the parse below.
                raise _JSExprFail("f729 void operand not bound")
        else:
            raise _JSExprFail("f729 void operand not modeled")
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, ";")
        state["parts"] += 1  # the void statement is obfuscation-shaped
        if state["parts"] > _JS_EXPR_MAX_PARTS:
            raise _JSExprFail("f729 too many parts")
        sj = _js_skip_ws(text, sj)
        m = _js_match_kw(text, sj, "return")
        if m is None:
            raise _JSExprFail("f729 no return")
        body_expr = _js_require_single_return(text[sj:inner_end])
        # F611 substitution discipline: value-position uses of the
        # bound name (never inside literals, never property names),
        # with reassignment guards.
        try:
            toks = _js_ident_tokens(body_expr)
        except _JSExprFail:
            return None
        _rn = len(body_expr)
        for tname, ts, te in toks:
            if tname != name:
                continue
            jj = te
            while jj < _rn and body_expr[jj] in " \t\n\r":
                jj += 1
            nxt2 = body_expr[jj:jj + 2]
            nxt1 = body_expr[jj:jj + 1]
            if nxt1 == "=" and nxt2 not in ("==", "=>"):
                return None
            if nxt2 in ("+=", "-=", "*=", "/=", "%=", "++", "--"):
                return None
            pp = ts - 1
            while pp >= 0 and body_expr[pp] in " \t\n\r":
                pp -= 1
            if pp >= 1 and body_expr[pp - 1:pp + 1] in ("++", "--"):
                return None
        quoted = _js_f611_quote(init_val)
        out = []
        pos = 0
        for tname, ts, te in toks:
            if tname != name:
                continue
            if ts > 0 and (body_expr[ts - 1] in _JS_IDENT_CONT
                           or body_expr[ts - 1] in ".$"):
                continue
            out.append(body_expr[pos:ts])
            out.append(quoted)
            pos = te
        out.append(body_expr[pos:])
        rewritten = "".join(out)
        try:
            val, rend = _js_parse_additive(rewritten, 0, depth + 1,
                                           state)
        except _JSExprFail:
            return None
        if rend != len(rewritten):
            return None
        if not isinstance(val, str):
            return None
        # Invocation: exactly `()`.
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, "(")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        state["ops"] += 1  # the iife wrapper is obfuscation-shaped
        return val, j
    except _JSExprFail:
        return None


def _js_parse_f754_delete_stmt_iife(text, i, depth, state):
    """Parse `(function(){DECL o=OBJLIT;[delete o.K;|delete o['K'];]+
    return ADD;})()` at text[i] (F754).

    The decoder has no delete-operator production: a delete
    statement in the IIFE body fails the whole decode while node
    evaluates the remaining reads node-exactly (v24.20.0). Filed
    shapes:
    `(function(){var o={x:'f1',y:'junk'};delete o.y;return o.x+'f2';})()`
    and the bracket twin
    `(function(){var o={x:'f1',y:'junk'};delete o['y'];return o.x+'f2';})()`.
    Node-exact desugar (v24.20.0):
    - `var|let|const o={...};` binds the F535 literal object
      (parsed accessor-aware, F716 parity);
    - `delete o.K;` / `delete o['K'];` removes the own property K
      from the tracked object (data or accessor -- the engine
      never invokes a getter on delete) or is a no-op when K is
      absent (the engine returns true);
    - `return ADD;` resolves member reads against the tracked
      object exactly like the engine's own-property lookup (a
      missing key -- including a deleted one -- is engine
      undefined: fail closed, never mis-decoded).

    Bounds (all fail closed -- rejected, never mis-decoded):
    - a named function, parameters, a directive prologue, extra
      statements, reassignment, non-`{}`-literal object binding;
    - a delete whose target is not the bound ident (`delete o`
      bare, `delete x`, `delete other.y`), a non-member delete
      operand (`delete(o.y)` paren form), a non-literal key
      (`delete o[0]`, `delete o[k]`), `__proto__` keys;
    - a return term that is not a string literal or a bound member
      read resolving to a plain string (deleted-key reads fail
      closed: the engine yields undefined there).

    Disjoint from every earlier route: no earlier route accepts a
    `delete` statement head (F729 owns the `void` head;
    F655/F679's statement dispatch fails closed on `delete`;
    F716 requires `Reflect.set(`; red-first verified: 2 BREAK on
    the open tree), so no previously-decoded input changes
    behavior. Returns (value, next_index), or None when text[i]
    is not this shape. Never evals.
    """
    n = len(text)
    if depth >= _JS_EXPR_MAX_DEPTH:
        return None
    try:
        brace = _js_parse_f654_sync_iife_head(text, i)
        if brace is None:
            return None
        inner_start, inner_end, j = _js_span_braced(text, brace)
        sj = _js_skip_ws(text, inner_start)
        _kw, m = _js_match_decl_kw(text, sj)
        if _kw is None:
            raise _JSExprFail("F754 decl not var/const/let")
        sj = _js_skip_ws(text, m)
        oname, sj = _js_parse_ident(text, sj)
        if oname == "arguments":
            raise _JSExprFail("F754 binding named arguments")
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, "=")
        sj = _js_skip_ws(text, sj)
        if sj >= n or text[sj] != "{":
            return None  # not an object-literal target
        props, sj = _js_parse_f535_object(text, sj, depth, state,
                                         accessor_aware=True)
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, ";")
        sj = _js_skip_ws(text, sj)
        tracked = dict(props)
        ndel = 0
        while True:
            q = _js_skip_ws(text, sj)
            r = _js_match_kw(text, q, "return")
            if r is not None:
                sj = q
                break
            dk = _js_match_kw(text, q, "delete")
            if dk is None:
                raise _JSExprFail("F754 stmt not delete")
            q = _js_skip_ws(text, dk)
            tname, q = _js_parse_ident(text, q)
            if tname != oname:
                raise _JSExprFail("F754 delete target not bound")
            q = _js_skip_ws(text, q)
            if q < n and text[q] == ".":
                q = _js_skip_ws(text, q + 1)
                key, q = _js_parse_ident(text, q)
            elif q < n and text[q] == "[":
                qb = _js_skip_ws(text, q + 1)
                if qb >= n or text[qb] not in "'\"":
                    raise _JSExprFail(
                        "F754 delete key not a string literal")
                key, q = _js_parse_string(text, qb)
                q = _js_skip_ws(text, q)
                q = _js_expect(text, q, "]")
            else:
                raise _JSExprFail("F754 delete not a member")
            if not key or key == "__proto__":
                raise _JSExprFail("F754 delete bad key")
            # Node-exact (v24.20.0): delete removes the own
            # property (data or accessor -- never invoked) or is a
            # no-op when the key is absent.
            tracked.pop(key, None)
            q = _js_skip_ws(text, q)
            q = _js_expect(text, q, ";")
            state["ops"] += 1  # the delete indirection is
            # obfuscation-shaped
            ndel += 1
            sj = _js_skip_ws(text, q)
        if ndel == 0:
            raise _JSExprFail("F754 no delete statement")

        def _f754_term(sj):
            # One additive term: a string literal, or a member read
            # on the bound object resolving to a plain string (the
            # F716 term discipline).
            sj = _js_skip_ws(text, sj)
            if sj < n and text[sj] in "'\"":
                return _js_parse_string(text, sj)
            _rname, sj = _js_parse_ident(text, sj)
            if _rname != oname:
                raise _JSExprFail("F754 term not bound ident")
            sj = _js_skip_ws(text, sj)
            if sj < n and text[sj] == ".":
                sj = _js_skip_ws(text, sj + 1)
                _mem, sj = _js_parse_ident(text, sj)
            elif sj < n and text[sj] == "[":
                _qb = _js_skip_ws(text, sj + 1)
                if _qb < n and text[_qb] in "'\"":
                    _mem, sj = _js_parse_bracket_member(text, sj)
                else:
                    raise _JSExprFail("F754 term key not a literal")
            else:
                raise _JSExprFail("F754 term not a member read")
            if _mem == "__proto__":
                raise _JSExprFail("F754 term __proto__")
            _raw = tracked.get(_mem)
            if _raw is None:
                raise _JSExprFail("F754 term missing key")
            _rv = _raw.value if isinstance(_raw, _JSAccessor) \
                else _raw
            if (not isinstance(_rv, str)
                    or isinstance(_rv, (_JSNumStr, _JSBigInt))
                    or _js_str_is_unsafe_int(_rv)):
                raise _JSExprFail(
                    "F754 term value not a plain string")
            state["ops"] += 1  # the member read is
            # obfuscation-shaped
            return _rv, sj

        m = _js_match_kw(text, sj, "return")
        sj = _js_skip_ws(text, m)
        total = None
        while True:
            _val, sj = _f754_term(sj)
            state["parts"] += 1
            if state["parts"] > _JS_EXPR_MAX_PARTS:
                raise _JSExprFail("too many parts")
            if total is None:
                total = _val
            else:
                if len(total) + len(_val) > _MAX_DECODE_BYTES:
                    raise _JSExprFail("concat too long")
                total = total + _val
            sj = _js_skip_ws(text, sj)
            if sj < n and text[sj] == "+":
                sj = sj + 1
                continue
            break
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, ";")
        sj = _js_skip_ws(text, sj)
        if sj != inner_end:
            raise _JSExprFail("F754 trailing statements")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, "(")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        state["ops"] += 1  # the IIFE wrapper is obfuscation-shaped
        return total, j
    except _JSExprFail:
        return None


def _js_parse_f730_entries_source(text, j, depth, state):
    """Parse `Object.entries({LITS})` at text[j] (F730).

    Returns (keys, vals, next_index): the engine-exact entries pairs
    of the object literal via _js_parse_object_literal_keys_values
    (integer-index keys ascending first, then string keys in
    insertion order; `__proto__` fails closed there; values are
    string literals only). Raises _JSExprFail on any other shape.
    Never evals.
    """
    n = len(text)
    j = _js_skip_ws(text, j)
    if not text.startswith("Object", j):
        raise _JSExprFail("f730 not Object.entries")
    j += len("Object")
    if j < n and text[j] in _JS_IDENT_CONT:
        raise _JSExprFail("f730 Objectx")
    j = _js_skip_ws(text, j)
    j = _js_expect(text, j, ".")
    ek = _js_match_kw(text, _js_skip_ws(text, j), "entries")
    if ek is None:
        raise _JSExprFail("f730 not entries")
    j = _js_skip_ws(text, ek)
    j = _js_expect(text, j, "(")
    j = _js_skip_ws(text, j)
    if j >= n or text[j] != "{":
        raise _JSExprFail("f730 entries source not a literal")
    keys, vals, j = _js_parse_object_literal_keys_values(text, j,
                                                         depth, state)
    j = _js_skip_ws(text, j)
    j = _js_expect(text, j, ")")
    return keys, vals, j


def _js_parse_f730_nested_pattern(text, j):
    """Parse `[[K1,V1],[K2,V2],...]` at text[j] (F730).

    Each element is a 2-slot array: `[IDENT,IDENT]` or `[,IDENT]`
    (key elision). Returns (pairs, next_index) where pairs is a list
    of (key_name_or_None, val_name). Raises _JSExprFail on deeper
    nesting, non-identifier leaves, defaults, rest elements, or any
    other shape. Never evals.
    """
    n = len(text)
    j = _js_skip_ws(text, j)
    if j >= n or text[j] != "[":
        raise _JSExprFail("f730 pattern not an array")
    j = _js_skip_ws(text, j + 1)
    pairs = []
    while True:
        j = _js_skip_ws(text, j)
        if j >= n or text[j] != "[":
            raise _JSExprFail("f730 pattern element not an array")
        j = _js_skip_ws(text, j + 1)
        if j < n and text[j] == ",":
            kname = None  # key elision: [,V]
            j = _js_skip_ws(text, j + 1)
        else:
            kname, j = _js_parse_ident(text, j)
            j = _js_skip_ws(text, j)
            if j >= n or text[j] != ",":
                raise _JSExprFail("f730 pattern element arity")
            j = _js_skip_ws(text, j + 1)
        vname, j = _js_parse_ident(text, j)
        j = _js_skip_ws(text, j)
        if j >= n or text[j] != "]":
            raise _JSExprFail("f730 pattern element not closed")
        j = j + 1
        pairs.append((kname, vname))
        j = _js_skip_ws(text, j)
        if j < n and text[j] == ",":
            j = _js_skip_ws(text, j + 1)
            continue
        if j < n and text[j] == "]":
            return pairs, j + 1
        raise _JSExprFail("f730 pattern not closed")


def _js_parse_f730_nested_entries_iife(text, i, depth, state):
    """Parse `(function(){var|let|const PAT=Object.entries({LITS});return ADD;})()` (F730).

    Nested-ARRAY destructuring residual beyond F644/F684b/F693:
    F644 models flat patterns only; F684b models nested OBJECT
    patterns (`{x:{y}}`); F693 models per-key defaults. A nested
    array pattern over `Object.entries` (`[[k1,v1],[k2,v2]]`, or
    `[[,v1],[,v2]]` with key elision) fails closed in all three,
    while node evaluates the fragment reads exactly (v24.20.0).

    Two productions (node-exact):
    - direct: `var|let|const PAT=Object.entries({LITS});`
    - var-bound twin: `var|let|const E=Object.entries({LITS});`
      then `var|let|const PAT=E;` (the second RHS must be exactly
      the bound name).

    Node-exact desugar: Object.entries yields [key, value] pairs in
    engine-exact enumeration order; each pattern element binds
    positionally against its pair. More pattern pairs than entries
    throws TypeError in the engine (verified v24.20.0), so it fails
    closed here -- never mis-decoded. The return body rewrites via
    _js_bind_destructure_arguments over the flattened quoted pair
    values and parses with the normal additive grammar.

    Bounds (all fail closed -- rejected, never mis-decoded):
    - a non-`[` pattern head (F684b owns `{`), deeper nesting,
      non-identifier leaves, defaults, rest elements, computed keys;
    - a duplicate or `arguments` / reserved-word bound name;
    - a non-literal-values entries source (`__proto__` fails closed
      in the literal parser);
    - more pattern pairs than entries, a named function, params, a
      directive prologue, extra statements, non-empty call args.
    Disjoint from F644 (its array-pattern parse fails closed on `[`
    after `[`), F684b (`{` head), and F693 (requires `=` defaults
    after a sub-pattern). Tried after F693. Returns (value,
    next_index), or None when text[i] is not this shape. Never evals.
    """
    n = len(text)
    if depth >= _JS_EXPR_MAX_DEPTH:
        return None
    if not _js_peek_arguments_iife_head(text, i):
        return None
    try:
        j = _js_skip_ws(text, i)
        j = _js_expect(text, j, "(")
        j = _js_skip_ws(text, j + len("function"))
        j = _js_expect(text, j, "(")
        j = _js_expect(text, j, ")")
        brace = _js_skip_ws(text, j)
        j = _js_expect(text, brace, "{")
        inner_start, inner_end, j = _js_span_braced(text, brace)
        sj = _js_skip_ws(text, inner_start)
        _kw, m = _js_match_decl_kw(text, sj)
        if _kw is None:
            return None  # not a decl -- other routes own it
        sj = _js_skip_ws(text, m)

        bound_entries_name = None
        if sj < n and text[sj] == "[":
            # Direct production: the pattern is the first decl.
            pairs, sj = _js_parse_f730_nested_pattern(text, sj)
            sj = _js_skip_ws(text, sj)
            sj = _js_expect(text, sj, "=")
            keys, vals, sj = _js_parse_f730_entries_source(
                text, sj, depth, state)
        else:
            # Var-bound twin: `var|let|const E=Object.entries(...);`
            ename, sj = _js_parse_ident(text, sj)
            if ename in _F611_RESERVED or ename == "arguments":
                return None
            sj = _js_skip_ws(text, sj)
            sj = _js_expect(text, sj, "=")
            keys, vals, sj = _js_parse_f730_entries_source(
                text, sj, depth, state)
            bound_entries_name = ename
            sj = _js_skip_ws(text, sj)
            sj = _js_expect(text, sj, ";")
            # Second decl: `var|let|const PAT=E;`
            sj = _js_skip_ws(text, sj)
            _kw2, m2 = _js_match_decl_kw(text, sj)
            if _kw2 is None:
                raise _JSExprFail("f730 twin second decl not a decl")
            sj = _js_skip_ws(text, m2)

            pairs, sj = _js_parse_f730_nested_pattern(text, sj)
            sj = _js_skip_ws(text, sj)
            sj = _js_expect(text, sj, "=")
            rname, sj = _js_parse_ident(text, _js_skip_ws(text, sj))
            if rname != bound_entries_name:
                raise _JSExprFail("f730 twin source not the bound name")
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, ";")
        if len(pairs) > len(keys):
            # The engine throws TypeError destructuring undefined --
            # fail closed rather than mis-decode.
            raise _JSExprFail("f730 more pairs than entries")
        # Bind: flatten the quoted pair values; each element binds
        # its slots positionally (key slot may be elided).
        names = []
        flat = []
        pkeys = []
        for (kname, vname), key, val in zip(pairs, keys, vals):
            if kname is not None:
                names.append(kname)
                flat.append(_js_f611_quote(key))
                pkeys.append(len(flat) - 1)
            names.append(vname)
            flat.append(_js_f611_quote(val))
            pkeys.append(len(flat) - 1)
            state["parts"] += 1  # each pair is obfuscation-shaped
            if state["parts"] > _JS_EXPR_MAX_PARTS:
                raise _JSExprFail("f730 too many parts")
        if len(set(names)) != len(names):
            raise _JSExprFail("f730 duplicate bound names")
        if any(nm in _F611_RESERVED or nm == "arguments"
               for nm in names):
            raise _JSExprFail("f730 reserved bound name")
        sj = _js_skip_ws(text, sj)
        m = _js_match_kw(text, sj, "return")
        if m is None:
            raise _JSExprFail("f730 no return")
        body_expr = _js_require_single_return(text[sj:inner_end])
        rewritten = _js_bind_destructure_arguments(
            body_expr, flat, names, pkeys)
        val, _k = _js_parse_additive(rewritten, 0, depth + 1, state)
        _k = _js_skip_ws(rewritten, _k)
        if _k != len(rewritten):
            raise _JSExprFail("f730 return not an additive")
        if not isinstance(val, str):
            raise _JSExprFail("f730 return not a string")
        state["ops"] += 1  # the destructure is obfuscation-shaped
        # Invocation: exactly `()`.
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, "(")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        state["ops"] += 1  # the iife wrapper is obfuscation-shaped
        return val, j
    except _JSExprFail:
        return None


def _js_f685_rewrite_arrow_calls(body_expr, fname, lit_text):
    """Rewrite `F()` call sites to the resolved arg literal (F685).

    *fname* must occur ONLY as a no-arg call `F()`; any other use
    (a bare `F`, `F.x`, `F[...]`, `F(args)`) fails closed -- the
    engine's semantics for those are unmodeled. Guards mirror
    _js_bind_iife_arguments (no nested function/class/new/delete,
    no bare assignment, fname never an arrow param). A defensive
    rescan requires every code-span occurrence consumed and no
    bare `arguments` left (it would be unbound outside the arrow).
    Raises _JSExprFail on any mismatch. Never evals.
    """
    segs = _js_split_code_strings(body_expr)
    code = "".join(s for is_code, s in segs if is_code)
    for kw, msg in (("function", "F685 nested function"),
                    ("delete", "F685 delete"),
                    ("new", "F685 new"),
                    ("class", "F685 class")):
        if _js_code_find_idents(code, kw):
            raise _JSExprFail(msg)
    if _js_code_has_bare_assign(code):
        raise _JSExprFail("F685 assignment in body")
    if _js_code_has_ident_arrow_param(code, fname):
        raise _JSExprFail("F685 fname as arrow param")
    out = []
    for is_code, s in segs:
        if not is_code:
            out.append(s)
            continue
        pos = 0
        buf = []
        for st in _js_code_find_idents(s, fname):
            en = st + len(fname)
            rest = s[en:].lstrip(" \t\n\r")
            if not rest.startswith("("):
                raise _JSExprFail("F685 non-call use of arrow")
            rp = rest[1:].lstrip(" \t\n\r")
            if not rp.startswith(")"):
                raise _JSExprFail("F685 arrow call with args")
            buf.append(s[pos:st])
            buf.append(lit_text)
            pos = en + (len(s[en:]) - len(rp)) + 1
        buf.append(s[pos:])
        out.append("".join(buf))
    rewritten = "".join(out)
    rcode = "".join(s for is_code, s in _js_split_code_strings(
        rewritten) if is_code)
    if _js_code_find_idents(rcode, fname):
        raise _JSExprFail("F685 fname left unsubstituted")
    if _js_code_find_idents(rcode, "arguments"):
        raise _JSExprFail("F685 bare arguments in body")
    return rewritten


def _js_parse_f685_arrow_args_iife(text, i, depth, state):
    """Parse `(function(){DECL F=()=>arguments[N];return ADD;})`
    `(LITS)` (F685).

    Arrow-lexical `arguments` beyond F545: an arrow with no params
    captures the ENCLOSING function's `arguments`; calling the
    arrow reads `arguments[N]` lexically. Node-exact desugar
    (v24.20.0): the decl binds `F` to the arrow; each `F()` call
    site in the return body rewrites to the Nth call-site literal
    (the F509 string-literal arg grammar); the rewritten body
    parses with the normal additive grammar. The arrow's params
    must be empty (a param would shadow nothing here -- the filed
    shapes use `()`); the index must be in range (out-of-range
    reads `undefined` in the engine, which the decoder never
    decodes -- fail closed).
    Disjoint from F509/F545: those bind `arguments` directly or
    via one-hop aliases; an arrow indirection fails closed in
    their head peeks. Tried after F664.
    Bounds (all fail closed -- rejected, never mis-decoded):
    - a named function, non-empty arrow params, a non-`arguments`
      arrow body, a non-literal index, a negative or out-of-range
      index, non-literal call args, extra statements, reassignment
      (constructive grammar);
    - any use of `F` other than a no-arg `F()` call; a bare
      `arguments` elsewhere in the body; nested
      function/class/new/delete or assignment in the body.
    Returns (value, next_index), or None when text[i] is not this
    shape. Never evals.
    """
    n = len(text)
    if depth >= _JS_EXPR_MAX_DEPTH:
        return None
    try:
        j = _js_skip_ws(text, i)
        if j >= n or text[j] != "(":
            return None
        k = _js_skip_ws(text, j + 1)
        if not text.startswith("function", k):
            return None
        k2 = k + len("function")
        if k2 < n and text[k2] in _JS_IDENT_CONT:
            return None  # functionx -- not our shape
        if k2 < n and text[k2] in _JS_IDENT_START:
            return None  # named function -- not our shape
        j = _js_skip_ws(text, k2)
        j = _js_expect(text, j, "(")
        j = _js_expect(text, j, ")")
        brace = _js_skip_ws(text, j)
        j = _js_expect(text, brace, "{")
        inner_start, inner_end, j = _js_span_braced(text, brace)
        sj = _js_skip_ws(text, inner_start)
        _kw, m = _js_match_decl_kw(text, sj)
        if _kw is None:
            raise _JSExprFail("F685 decl not var/const/let")
        sj = _js_skip_ws(text, m)
        fname, sj = _js_parse_ident(text, sj)
        if fname == "arguments" or fname in _F611_RESERVED:
            raise _JSExprFail("F685 reserved binding name")
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, "=")
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, "(")
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, ")")
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, "=")
        sj = _js_expect(text, sj, ">")
        sj = _js_skip_ws(text, sj)
        _am = _js_match_kw(text, sj, "arguments")
        if _am is None:
            raise _JSExprFail("F685 arrow body not arguments")
        sj = _js_skip_ws(text, _am)
        sj = _js_expect(text, sj, "[")
        sj = _js_skip_ws(text, sj)
        _aidx, sj = _js_parse_slice_int(text, sj)
        if _aidx < 0:
            raise _JSExprFail("F685 negative arguments index")
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, "]")
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, ";")
        sj = _js_skip_ws(text, sj)
        _rm = _js_match_kw(text, sj, "return")
        if _rm is None:
            raise _JSExprFail("F685 no return")
        body_expr = _js_require_single_return(text[sj:inner_end])
        # Invocation: string-literal args (the F509 arg grammar).
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, "(")
        args = []
        j = _js_skip_ws(text, j)
        if j >= n or text[j] != ")":
            while True:
                j = _js_skip_ws(text, j)
                if j >= n or text[j] not in "'\"":
                    raise _JSExprFail("F685 arg not a literal")
                _a, j = _js_parse_string(text, j)
                args.append(_a)
                state["parts"] += 1
                if state["parts"] > _JS_EXPR_MAX_PARTS:
                    raise _JSExprFail("too many parts")
                j = _js_skip_ws(text, j)
                if j < n and text[j] == ",":
                    j = _js_skip_ws(text, j + 1)
                    continue
                break
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        if _aidx >= len(args):
            raise _JSExprFail("F685 arguments index out of range")
        _lit = ("'" + args[_aidx].replace("\\", "\\\\").replace(
            "'", "\\'") + "'")
        rewritten = _js_f685_rewrite_arrow_calls(body_expr, fname,
                                                 _lit)
        val, _k = _js_parse_additive(rewritten, 0, depth + 1, state)
        _k = _js_skip_ws(rewritten, _k)
        if _k != len(rewritten):
            raise _JSExprFail("F685 return not an additive")
        if not isinstance(val, str):
            raise _JSExprFail("F685 return not a string")
        state["ops"] += 1  # the arrow-arguments desugar is
                           # obfuscation-shaped
        return val, j
    except _JSExprFail:
        return None


def _js_parse_f646_accum_decl(stmts, j):
    """Parse `var|let NAME='';` or `var|let|const NAME=[];` at stmts[j] (F646).

    The string accumulator reuses the F600/F601/F602 discipline
    (empty-string initializer; a `const` accumulator throws at
    runtime on `+=` and fails closed). The array accumulator takes
    the exact empty-array literal (a non-empty initializer fails
    closed -- the engine would pre-seed the join); `const` is
    node-legal for the array form (push mutates the array, nothing
    reassigns the binding -- the push grammar has no room for a
    reassignment). Returns (kind, name, next_index) with kind
    "str"|"arr". Never evals.
    """
    try:
        acc, j2 = _js_parse_f6xx_accum_decl(stmts, j)
        return "str", acc, j2
    except _JSExprFail:
        pass
    n = len(stmts)
    m = _js_match_kw(stmts, j, "var")
    if m is None:
        m = _js_match_kw(stmts, j, "let")
    if m is None:
        m = _js_match_kw(stmts, j, "const")
    if m is None:
        raise _JSExprFail("F646 accum decl not var/let/const")
    j = _js_skip_ws(stmts, m)
    acc, j = _js_parse_ident(stmts, j)
    j = _js_skip_ws(stmts, j)
    j = _js_expect(stmts, j, "=")
    j = _js_skip_ws(stmts, j)
    if j >= n or stmts[j] != "[":
        raise _JSExprFail("F646 accum not string/array")
    j = _js_skip_ws(stmts, j + 1)
    if j >= n or stmts[j] != "]":
        raise _JSExprFail("F646 array accum not empty")
    j = _js_skip_ws(stmts, j + 1)
    j = _js_expect(stmts, j, ";")
    return "arr", acc, j


def _js_parse_f646_array_source(stmts, j, depth, state):
    """Parse `['LIT', ...]` at stmts[j] (F646/F651).

    Plain string-literal elements only (the F494 discipline):
    holes, null/undefined, numeric literals, nested arrays, and
    spread fail closed -- forEach skips holes but visits
    null/undefined, while _js_parse_array models both as _JSNil,
    so any _JSNil element is a miss, never a guess; for-of visits
    holes as undefined, also a miss. Returns (elements,
    next_index). Never evals.
    """
    arr, j = _js_parse_array(stmts, j, depth, state)
    elements = []
    for e in arr.elements:
        if not isinstance(e, str) or isinstance(e, _JSNumStr):
            raise _JSExprFail("F646 non-string element")
        state["parts"] += 1  # F452: charge per element
        if state["parts"] > _JS_EXPR_MAX_PARTS:
            raise _JSExprFail("too many parts")
        elements.append(e)
    return elements, j


def _js_parse_f646_push_expr(text, j, acc_name):
    """Parse `ACC.push(X)` at text[j] (F646).

    Returns (X_text, next_index) just past the closing paren. X
    is scanned string/paren-depth-aware to `)` at depth 0 (the
    _js_scan_foreach_E discipline). Never evals.
    """
    j = _js_skip_ws(text, j)
    a2, j = _js_parse_ident(text, j)
    if a2 != acc_name:
        raise _JSExprFail("F646 push accum mismatch")
    j = _js_skip_ws(text, j)
    j = _js_expect(text, j, ".")
    _mn, j = _js_parse_ident(text, _js_skip_ws(text, j))
    if _mn != "push":
        raise _JSExprFail("F646 not push")
    j = _js_skip_ws(text, j)
    j = _js_expect(text, j, "(")
    X, k = _js_scan_foreach_E(text, j, ")")
    return X, k + 1


def _js_parse_f646_push_stmt(text, j, acc_name):
    """Parse `ACC.push(X);` at text[j] (F646 block-body form).

    Returns (X_text, next_index) just past the `;`. Never evals.
    """
    X, j = _js_parse_f646_push_expr(text, j, acc_name)
    j = _js_skip_ws(text, j)
    j = _js_expect(text, j, ";")
    return X, j


def _js_parse_f646_push_callback(text, j, acc_name):
    """Parse a forEach push callback at text[j] (F646).

    Recognized (node-verified, v24.20.0):
      `function(P){ACC.push(X);}`, `(P)=>ACC.push(X)`,
      `(P)=>{ACC.push(X);}`, `P=>ACC.push(X)`, `P=>{ACC.push(X);}`
    where P is one or two distinct parameter idents (forEach
    passes (element, index) positionally; a third param would be
    the array itself -- unmodeled, fails closed at param parse)
    and X is an additive expression over the params. Returns
    (params, X_text, next_index) just past the callback. Never
    evals.
    """
    n = len(text)
    params = []
    if _js_match_kw(text, j, "function") is not None:
        j = _js_skip_ws(text, j + len("function"))
        j = _js_expect(text, j, "(")
        params, j = _js_parse_foreach_params(text, j)
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, "{")
        X, j = _js_parse_f646_push_stmt(text, j, acc_name)
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, "}")
        return params, X, j
    # Arrow forms (the bare single-param form is engine-identical,
    # F448 precedent).
    j0 = _js_skip_ws(text, j)
    if j0 >= n:
        raise _JSExprFail("F646 callback not a function")
    if text[j0] == "(":
        j = _js_skip_ws(text, j0 + 1)
        params, j = _js_parse_foreach_params(text, j)
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
    elif text[j0] in _JS_IDENT_START:
        _pname, j = _js_parse_ident(text, j0)
        if _pname == "arguments":
            raise _JSExprFail("F646 param shadowed")
        params = [_pname]
        j = _js_skip_ws(text, j)
    else:
        raise _JSExprFail("F646 callback not a function")
    j = _js_skip_ws(text, j)
    if not text.startswith("=>", j):
        raise _JSExprFail("F646 arrow without =>")
    j = _js_skip_ws(text, j + 2)
    if j < n and text[j] == "{":
        X, j = _js_parse_f646_push_stmt(text, j + 1, acc_name)
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, "}")
        return params, X, j
    # Concise body: `ACC.push(X)` terminated by `)` at depth 0.
    X, j = _js_parse_f646_push_expr(text, j, acc_name)
    return params, X, j


def _js_parse_f646_return_join(stmts, j, acc):
    """Parse `return ACC.join('SEP');` / `return ACC.join();` at stmts[j] (F646).

    The no-argument form joins with the engine's comma default
    (node v24.20.0 verified). The separator must be a string
    literal. Parses through end-of-body like
    _js_parse_f6xx_return_acc. Returns (sep, next_index) with sep
    None for the comma default. Never evals.
    """
    j = _js_skip_ws(stmts, j)
    m = _js_match_kw(stmts, j, "return")
    if m is None:
        raise _JSExprFail("F646 no return")
    j = _js_skip_ws(stmts, m)
    acc2, j = _js_parse_ident(stmts, j)
    if acc2 != acc:
        raise _JSExprFail("F646 returns another ident")
    j = _js_skip_ws(stmts, j)
    j = _js_expect(stmts, j, ".")
    _mn, j = _js_parse_ident(stmts, _js_skip_ws(stmts, j))
    if _mn != "join":
        raise _JSExprFail("F646 not join")
    j = _js_skip_ws(stmts, j)
    j = _js_expect(stmts, j, "(")
    j = _js_skip_ws(stmts, j)
    sep = None
    if j < len(stmts) and stmts[j] in "'\"":
        sep, j = _js_parse_string(stmts, j)
        j = _js_skip_ws(stmts, j)
    j = _js_expect(stmts, j, ")")
    j = _js_skip_ws(stmts, j)
    if j < len(stmts) and stmts[j] == ";":
        j += 1
    if _js_skip_ws(stmts, j) != len(stmts):
        raise _JSExprFail("F646 trailing statements")
    return sep, j


def _js_f6xx_operand_exact(text, i):
    """Parse one additive operand for the concat-exactness check (F646/F651).

    Returns (is_string, end_index). String literals are strings;
    numeric literals are numbers; parenthesized additive chains
    recurse. Anything else raises _JSExprFail (fail closed).
    Never evals.
    """
    i = _js_skip_ws(text, i)
    if i >= len(text):
        raise _JSExprFail("F6xx exactness truncated")
    c = text[i]
    if c == chr(34) or c == "'":
        _, j = _js_parse_string(text, i)
        return True, j
    if c == "(":
        inner_str, j = _js_f6xx_additive_exact(text, i + 1)
        j = _js_expect(text, j, ")")
        return inner_str, j
    if c.isdigit():
        j = i
        while j < len(text) and (text[j].isdigit() or text[j] == "."):
            j += 1
        return False, j
    raise _JSExprFail("F6xx exactness non-literal")


def _js_f6xx_additive_exact(text, i):
    """Parse an additive chain for the concat-exactness check (F646/F651).

    Returns (is_string, end_index). A '+' whose operands are both
    numbers raises _JSExprFail: the engine adds numerically there
    while the string-typed decoder would concatenate -- a silent
    mis-decode (false negative), e.g. `(i+1)` gives node '12' vs
    decoder '0111'. Refused coded, never mis-decoded. Never evals.
    """
    is_str, i = _js_f6xx_operand_exact(text, i)
    while True:
        j = _js_skip_ws(text, i)
        if j >= len(text) or text[j] != "+":
            return is_str, i
        rhs_str, i = _js_f6xx_operand_exact(text, j + 1)
        if not is_str and not rhs_str:
            raise _JSExprFail("F6xx exactness numeric plus")
        is_str = True


def _js_f6xx_check_E_concat_exact(E, template_bindings):
    """Fail closed unless every '+' in E is string-concat (F646/F651).

    *E* is the raw `S+=E` (or push-argument) text; *template_bindings*
    maps each bound name to a type template ("''" for engine-strings
    such as elements, "0" for engine-numbers such as indices).
    After template substitution, every '+' in the additive AST must
    have a string operand -- otherwise the engine's numeric '+'
    diverges from the decoder's string-typed '+' and the shape is
    refused coded rather than mis-decoded. Raises _JSExprFail on any
    violation. Never evals.
    """
    rewritten = E
    for pname, ptext in template_bindings:
        rewritten = _js_bind_foreach_param(rewritten, pname, ptext)
    _, j = _js_f6xx_additive_exact(rewritten, 0)
    j = _js_skip_ws(rewritten, j)
    if j != len(rewritten):
        raise _JSExprFail("F6xx exactness trailing junk")


def _js_parse_f646_array_foreach_iife(text, i, depth, state):
    """Parse `(function(){var|let S='';['LIT',...].forEach(CB);return S;})()` and the push/join twin (F646).

    Node-exact desugar (v24.20.0): Array.prototype.forEach calls
    CB once per element in ascending index order with (element,
    index, array). Two callback disciplines: the `S+=E`
    accumulation (the F600/F601/F602 callback grammar reused
    verbatim) and the `P.push(X)` / `return P.join('SEP')` twin
    (join with no argument uses the engine's comma default).
    Params are positional: P1=element, P2=index (a third param
    would be the array itself -- unmodeled, fails closed at param
    parse). Returns (value, next_index), or None on mismatch or
    guard failure. Bounded by the part/depth budgets; the wrapper
    charges one op (obfuscation-shaped). Never evals.

    Bounds (all fail closed -- rejected, never mis-decoded): a
    non-empty accumulator initializer, a `const` accumulator,
    non-literal array elements, holes, a callback that is not the
    exact accumulation/push shape, params shadowing the
    accumulator, non-string E/X values, a non-literal join
    separator, call args on the IIFE.
    """
    j = _js_parse_f6xx_iife_head(text, i)
    if j is None:
        return None
    try:
        brace = j
        inner_start, inner_end, j = _js_span_braced(text, brace)
        stmts = text[inner_start:inner_end]
        sj = _js_skip_ws(stmts, 0)
        kind, acc, sj = _js_parse_f646_accum_decl(stmts, sj)
        sj = _js_skip_ws(stmts, sj)
        elements, sj = _js_parse_f646_array_source(stmts, sj, depth,
                                                   state)
        sj = _js_skip_ws(stmts, sj)
        if sj >= len(stmts) or stmts[sj] != ".":
            raise _JSExprFail("F646 no dot")
        _mn, sj = _js_parse_ident(stmts, _js_skip_ws(stmts, sj + 1))
        if _mn != "forEach":
            raise _JSExprFail("F646 not forEach")
        sj = _js_skip_ws(stmts, sj)
        sj = _js_expect(stmts, sj, "(")
        sj = _js_skip_ws(stmts, sj)
        if kind == "str":
            params, E, sj = _js_parse_foreach_accum_callback(
                stmts, sj, acc, depth, state)
        else:
            params, E, sj = _js_parse_f646_push_callback(
                stmts, sj, acc)
        if acc in params:
            raise _JSExprFail("F646 param shadows accum")
        sj = _js_skip_ws(stmts, sj)
        sj = _js_expect(stmts, sj, ")")
        sj = _js_skip_ws(stmts, sj)
        sj = _js_expect(stmts, sj, ";")
        if kind == "str":
            _js_parse_f6xx_return_acc(stmts, _js_skip_ws(stmts, sj),
                                      acc)
            joiner = ""
        else:
            sep, _sj2 = _js_parse_f646_return_join(
                stmts, _js_skip_ws(stmts, sj), acc)
            joiner = "," if sep is None else sep
        if depth >= _JS_EXPR_MAX_DEPTH:
            raise _JSExprFail("too deep")
        # Spec-axis (concat exactness): the shared additive grammar
        # is string-typed, so a '+' applied to two numbers (the index
        # combined with itself or a numeric literal) would mis-decode
        # instead of failing closed. Refuse coded.
        _js_f6xx_check_E_concat_exact(
            E, [(params[0], "''")] +
               ([(params[1], "0")] if len(params) > 1 else []))
        parts = []
        for idx, elem in enumerate(elements):
            bindings = [(params[0], _js_quote_literal(elem))]
            if len(params) > 1:
                bindings.append((params[1], str(idx)))
            parts.append(_js_foreach_E_value(E, bindings, depth,
                                             state))
            state["parts"] += 1  # F452: charge per iteration
            if state["parts"] > _JS_EXPR_MAX_PARTS:
                raise _JSExprFail("too many parts")
        return _js_parse_f6xx_iife_tail(text, j, depth, state,
                                        joiner.join(parts))
    except _JSExprFail:
        return None



def _js_parse_args_entries_values_iife(text, i, depth, state):
    """Parse `(function(){DECL a=arguments; BODY})(lit, ...)` (F543).

    Desugars enumeration builtins on the arguments alias:
    - `return Object.entries(a).map(CB)POSTFIX;` where CB is the
      F543 pair-projection `e[1]` (the four forms in
      _js_parse_f543_pair_projection); the entries of the arguments
      object are the [index-string, value] pairs in ascending index
      order (node v24.20.0), so the map is element-identical to the
      argument array and the POSTFIX parses over it via the normal
      postfix grammar.
    - `return Object.values(a)(.map(ID))?POSTFIX;` (POSTFIX
      required, non-empty); the values array is element-identical
      to the argument array (node v24.20.0); an optional identity
      map (the four `x=>x` forms) is a no-op desugar, and the
      POSTFIX parses over the values via the normal postfix
      grammar.
    DECL is var/const/let (all three bind identically here, node
    verified). Call args are string literals (the F509/F516 arg
    grammar). Returns (value, next_index), or None when the head
    does not match or a guard fails (the caller falls through to
    the F529/F516 paths). Bounded by the part/depth budgets; the
    IIFE wrapper charges one op (obfuscation-shaped). Never evals.

    Bounds (all fail closed -- rejected, never mis-decoded):
    - a source other than bare `arguments`, an alias rebound
      anywhere (the exact-shape grammar has no room for
      reassignment), a non-alias receiver (`Object.entries(x)`),
      entries without the `e[1]` map (the pairs are not string
      values -- the decoder never guesses a join), a values body
      without postfix, a non-identity pair projection, non-literal
      call args, and any other body shape.
    """
    if not _js_peek_arguments_iife_head(text, i):
        return None
    n = len(text)
    try:
        j = _js_skip_ws(text, i)
        j = _js_expect(text, j, "(")
        j = _js_skip_ws(text, j) + len("function")
        j = _js_expect(text, j, "(")
        j = _js_expect(text, j, ")")
        brace = _js_skip_ws(text, j)
        j = _js_expect(text, brace, "{")
        inner_start, inner_end, j = _js_span_braced(text, brace)
        stmts = text[inner_start:inner_end]
        # F560: skip a leading directive prologue
        # ('use strict'; ...) before matching the binding
        # declaration (node-exact: directives are inert
        # string-literal statements at body start; anything
        # else fails closed as before).
        stmts = stmts[_js_skip_directive_prologue(stmts, state):]
        sj = _js_skip_ws(stmts, 0)
        _kw, m = _js_match_decl_kw(stmts, sj)
        if m is None:
            raise _JSExprFail("F543 decl not var/const/let")
        sj = _js_skip_ws(stmts, m)
        alias, sj = _js_parse_ident(stmts, sj)
        if alias == "arguments":
            raise _JSExprFail("F543 alias named arguments")
        sj = _js_skip_ws(stmts, sj)
        sj = _js_expect(stmts, sj, "=")
        m = _js_match_kw(stmts, _js_skip_ws(stmts, sj), "arguments")
        if m is None:
            raise _JSExprFail("F543 source not arguments")
        sj = _js_skip_ws(stmts, m)
        sj = _js_expect(stmts, sj, ";")
        rest = stmts[sj:]
        rj = _js_skip_ws(rest, 0)
        rk = _js_match_kw(rest, rj, "return")
        if rk is None:
            raise _JSExprFail("F543 body not return")
        rj = _js_skip_ws(rest, rk)
        member, q = _js_parse_f543_entries_values_head(rest, rj, alias)
        if member == "entries":
            q = _js_skip_ws(rest, q)
            q = _js_expect(rest, q, ".")
            mm = _js_match_kw(rest, _js_skip_ws(rest, q), "map")
            if mm is None:
                raise _JSExprFail("F543 entries without map")
            q = _js_expect(rest, _js_skip_ws(rest, mm), "(")
            q = _js_parse_f543_pair_projection(rest, q)
            q = _js_skip_ws(rest, q)
            q = _js_expect(rest, q, ")")
        else:
            # Optional identity map over the values array (a no-op
            # desugar -- the values are already element-identical to
            # the argument array).
            qq = _js_skip_ws(rest, q)
            if qq < len(rest) and rest[qq] == ".":
                mm = _js_match_kw(rest, _js_skip_ws(rest, qq + 1), "map")
                if mm is not None:
                    mq = _js_expect(rest, _js_skip_ws(rest, mm), "(")
                    mq = _js_parse_f543_identity_map(rest, mq)
                    mq = _js_skip_ws(rest, mq)
                    mq = _js_expect(rest, mq, ")")
                    q = mq
        be = len(rest)
        while be > q and rest[be - 1] in " \t\n\r":
            be -= 1
        if be > q and rest[be - 1] == ";":
            be -= 1
        postfix_text = rest[q:be]
        if not postfix_text.strip():
            raise _JSExprFail("F543 empty postfix")
        if depth >= _JS_EXPR_MAX_DEPTH:
            raise _JSExprFail("too deep")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, "(")
        args = []
        j = _js_skip_ws(text, j)
        if j < n and text[j] == ")":
            j += 1
        else:
            while True:
                j = _js_skip_ws(text, j)
                if j >= n or text[j] not in "'\"":
                    raise _JSExprFail("F543 arg not string literal")
                aval, j = _js_parse_string(text, j)
                args.append(aval)
                state["parts"] += 1
                if state["parts"] > _JS_EXPR_MAX_PARTS:
                    raise _JSExprFail("too many parts")
                j = _js_skip_ws(text, j)
                if j >= n:
                    raise _JSExprFail("unterminated iife call")
                if text[j] == ",":
                    j = _js_skip_ws(text, j + 1)
                    continue
                if text[j] == ")":
                    j += 1
                    break
                raise _JSExprFail("bad iife call")
        values = _JSArr(list(args))
        val, k = _js_parse_postfix(postfix_text, 0, values, depth, state)
        if _js_skip_ws(postfix_text, k) != len(postfix_text):
            raise _JSExprFail("F543 postfix trailing junk")
        state["ops"] += 1  # the iife wrapper is obfuscation-shaped
        return val, j
    except _JSExprFail:
        return None


def _js_parse_args_alias_return_iife(text, i, depth, state):
    """Parse `(function(){DECL a=arguments;return a;})(lit, ...)` (F581).

    Desugars the arguments-alias return: the IIFE returns the
    `arguments` exotic object itself, which the decoder models as the
    call-site argument array (element-identical for string-literal
    args, node v24.20.0 -- `Object.entries`/`Object.values` of the
    exotic are the index pairs / values in ascending index order,
    exactly as on the plain array). DECL is var/const/let (all three
    bind identically here, node verified); call args are string
    literals (the F509/F516 arg grammar). Returns (_JSArr,
    next_index), or None when the head does not match or a guard
    fails (the caller falls through to the F516 path). Bounded by
    the part/depth budgets; the IIFE wrapper charges one op
    (obfuscation-shaped). Never evals.

    Bounds (all fail closed -- rejected, never mis-decoded):
    - a source other than bare `arguments`, an alias rebound
      anywhere (the exact-shape grammar has no room for
      reassignment), a body other than exactly `return <alias>;`
      (the bare-alias additive body `return a[0]+a[1];` is F546's,
      not this; the `return arguments;` form is F489's), non-literal
      call args, and any other body shape.
    """
    if not _js_peek_arguments_iife_head(text, i):
        return None
    n = len(text)
    try:
        j = _js_skip_ws(text, i)
        j = _js_expect(text, j, "(")
        j = _js_skip_ws(text, j) + len("function")
        j = _js_expect(text, j, "(")
        j = _js_expect(text, j, ")")
        brace = _js_skip_ws(text, j)
        j = _js_expect(text, brace, "{")
        inner_start, inner_end, j = _js_span_braced(text, brace)
        stmts = text[inner_start:inner_end]
        # F560: skip a leading directive prologue
        # ('use strict'; ...) before matching the binding
        # declaration (node-exact: directives are inert
        # string-literal statements at body start; anything
        # else fails closed as before).
        stmts = stmts[_js_skip_directive_prologue(stmts, state):]
        sj = _js_skip_ws(stmts, 0)
        _kw, m = _js_match_decl_kw(stmts, sj)
        if m is None:
            raise _JSExprFail("F581 decl not var/const/let")
        sj = _js_skip_ws(stmts, m)
        alias, sj = _js_parse_ident(stmts, sj)
        if alias == "arguments":
            raise _JSExprFail("F581 alias named arguments")
        sj = _js_skip_ws(stmts, sj)
        sj = _js_expect(stmts, sj, "=")
        m = _js_match_kw(stmts, _js_skip_ws(stmts, sj), "arguments")
        if m is None:
            raise _JSExprFail("F581 source not arguments")
        sj = _js_skip_ws(stmts, m)
        sj = _js_expect(stmts, sj, ";")
        rest = stmts[sj:]
        rj = _js_skip_ws(rest, 0)
        rk = _js_match_kw(rest, rj, "return")
        if rk is None:
            raise _JSExprFail("F581 body not return")
        rj = _js_skip_ws(rest, rk)
        ralias, rj = _js_parse_ident(rest, rj)
        if ralias != alias:
            raise _JSExprFail("F581 returns another ident")
        rj = _js_skip_ws(rest, rj)
        rj = _js_expect(rest, rj, ";")
        if _js_skip_ws(rest, rj) != len(rest):
            raise _JSExprFail("F581 trailing statements")
        if depth >= _JS_EXPR_MAX_DEPTH:
            raise _JSExprFail("too deep")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, "(")
        args = []
        j = _js_skip_ws(text, j)
        if j < n and text[j] == ")":
            j += 1
        else:
            while True:
                j = _js_skip_ws(text, j)
                if j >= n or text[j] not in "'\"":
                    raise _JSExprFail("F581 arg not string literal")
                aval, j = _js_parse_string(text, j)
                args.append(aval)
                state["parts"] += 1
                if state["parts"] > _JS_EXPR_MAX_PARTS:
                    raise _JSExprFail("too many parts")
                j = _js_skip_ws(text, j)
                if j >= n:
                    raise _JSExprFail("unterminated iife call")
                if text[j] == ",":
                    j = _js_skip_ws(text, j + 1)
                    continue
                if text[j] == ")":
                    j += 1
                    break
                raise _JSExprFail("bad iife call")
        state["ops"] += 1  # the iife wrapper is obfuscation-shaped
        return _JSArr(list(args)), j
    except _JSExprFail:
        return None


def _js_parse_args_enumerated_iife(text, i, depth, state):
    """Parse `(function(){DECL a=arguments; BODY})(lit, ...)` (F529).

    Desugars the arguments-alias enumeration composition: a one-hop
    alias of the `arguments` exotic object (`var`/`const`/`let` -- all
    three bind identically here, node v24.20.0 verified) enumerated
    back into the call-site argument values via either
    - `return Object.keys(a).map(CB)POSTFIX;` where CB is one of
      `p=>a[p]`, `(p)=>a[p]`, `p=>{return a[p];}`,
      `function(p){return a[p];}` (the F517 callback discipline with
      the alias indexed by its own parameter); or
    - `var s='';for(var K in a){s+=a[K];}return s;` (the F517 for-in
      idiom over the alias; loop braces optional).
    Node-exact desugars (v24.20.0): `Object.keys` on the arguments
    object is the index list `['0',...]` in ascending order
    (`length`/`callee` are non-enumerable), so the map rebuilds the
    argument array and the POSTFIX parses over it via the normal
    postfix grammar; for-in yields the same ascending indices, so the
    accumulator is the argument join. Call args are string literals
    (the F509/F516 arg grammar). Returns (value, next_index), or None
    when the head does not match or a guard fails (the caller falls
    through to the F516/F517 paths). Bounded by the part/depth
    budgets; the IIFE wrapper charges one op (obfuscation-shaped).
    Never evals.

    Bounds (all fail closed -- rejected, never mis-decoded):
    - a source other than bare `arguments` (Array.from/Object.values
      aliases, rest params, destructuring are their own findings'
      scope), an alias rebound anywhere (the exact-shape grammar has
      no room for reassignment), non-identity map projections,
      a callback parameter shadowing the alias, bare `arguments`
      (not the alias) as the enumeration source, non-literal call
      args, and any other body shape.
    """
    if not _js_peek_arguments_iife_head(text, i):
        return None
    n = len(text)
    try:
        j = _js_skip_ws(text, i)
        j = _js_expect(text, j, "(")
        j = _js_skip_ws(text, j) + len("function")
        j = _js_expect(text, j, "(")
        j = _js_expect(text, j, ")")
        brace = _js_skip_ws(text, j)
        j = _js_expect(text, brace, "{")
        inner_start, inner_end, j = _js_span_braced(text, brace)
        stmts = text[inner_start:inner_end]
        # F560: skip a leading directive prologue
        # ('use strict'; ...) before matching the binding
        # declaration (node-exact: directives are inert
        # string-literal statements at body start; anything
        # else fails closed as before).
        stmts = stmts[_js_skip_directive_prologue(stmts, state):]
        sj = _js_skip_ws(stmts, 0)
        _kw, m = _js_match_decl_kw(stmts, sj)
        if m is None:
            raise _JSExprFail("F529 decl not var/const/let")
        sj = _js_skip_ws(stmts, m)
        alias, sj = _js_parse_ident(stmts, sj)
        if alias == "arguments":
            raise _JSExprFail("F529 alias named arguments")
        sj = _js_skip_ws(stmts, sj)
        sj = _js_expect(stmts, sj, "=")
        m = _js_match_kw(stmts, _js_skip_ws(stmts, sj), "arguments")
        if m is None:
            raise _JSExprFail("F529 source not arguments")
        sj = _js_skip_ws(stmts, m)
        sj = _js_expect(stmts, sj, ";")
        rest = stmts[sj:]
        rj = _js_skip_ws(rest, 0)
        if _js_match_kw(rest, rj, "return") is not None:
            form = "keys"
        elif _js_match_kw(rest, rj, "var") is not None:
            form = "forin"
        else:
            raise _JSExprFail("F529 body not modeled")
        postfix_text = None
        if form == "keys":
            rk = _js_match_kw(rest, rj, "return")
            q = _js_parse_f529_keys_head(
                rest, _js_skip_ws(rest, rk), alias)
            q = _js_skip_ws(rest, q)
            q = _js_expect(rest, q, ".")
            m = _js_match_kw(rest, _js_skip_ws(rest, q), "map")
            if m is None:
                raise _JSExprFail("F529 not a map")
            q = _js_expect(rest, _js_skip_ws(rest, m), "(")
            q = _js_parse_alias_index_callback(rest, q, alias)
            q = _js_skip_ws(rest, q)
            q = _js_expect(rest, q, ")")
            be = len(rest)
            while be > q and rest[be - 1] in " \t\n\r":
                be -= 1
            if be > q and rest[be - 1] == ";":
                be -= 1
            postfix_text = rest[q:be]
        else:
            _js_parse_f529_forin_accum(rest, rj, alias)
        if depth >= _JS_EXPR_MAX_DEPTH:
            raise _JSExprFail("too deep")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, "(")
        args = []
        j = _js_skip_ws(text, j)
        if j < n and text[j] == ")":
            j += 1
        else:
            while True:
                j = _js_skip_ws(text, j)
                if j >= n or text[j] not in "'\"":
                    raise _JSExprFail("F529 arg not string literal")
                aval, j = _js_parse_string(text, j)
                args.append(aval)
                state["parts"] += 1
                if state["parts"] > _JS_EXPR_MAX_PARTS:
                    raise _JSExprFail("too many parts")
                j = _js_skip_ws(text, j)
                if j >= n:
                    raise _JSExprFail("unterminated iife call")
                if text[j] == ",":
                    j = _js_skip_ws(text, j + 1)
                    continue
                if text[j] == ")":
                    j += 1
                    break
                raise _JSExprFail("bad iife call")
        values = _JSArr(list(args))
        if form == "keys":
            val, k = _js_parse_postfix(
                postfix_text, 0, values, depth, state)
            if _js_skip_ws(postfix_text, k) != len(postfix_text):
                raise _JSExprFail("F529 postfix trailing junk")
        else:
            val = "".join(args)
        state["ops"] += 1  # the iife wrapper is obfuscation-shaped
        return val, j
    except _JSExprFail:
        return None


def _js_span_balanced_braces(text, i):
    """Return the index just past the `}` matching text[i] == '{' (F517).

    `'...'` / `"..."` spans are skipped with escape handling so a
    brace inside a string never terminates the scan. Backticks fail
    closed (the F509 body grammar already excludes them; a template
    inside the for-in object is outside the modeled grammar).
    Raises _JSExprFail on unterminated input. Never evals.
    """
    n = len(text)
    depth = 0
    k = i
    while k < n:
        c = text[k]
        if c in "'\"":
            k = _js_skip_quoted(text, k)
            continue
        if c == "`":
            raise _JSExprFail("template in forin object")
        if c == "{":
            depth += 1
        elif c == "}":
            depth -= 1
            if depth == 0:
                return k + 1
        k += 1
    raise _JSExprFail("unterminated object in forin")


def _js_split_forin_accum(text, a, b):
    """Split the for-in accumulation statements in text[a:b] (F517/F592/F632).

    The exact modeled shape (ws-tolerant):
        var ACC='';
        var OBJ={...};
    or (F632: the two independent declarations in either order --
    engine-identical, node v24.20.0 verified):
        var OBJ={...};
        var ACC='';
    then:
        for(var K in OBJ)ACC+=OBJ[K](.MEM|['MEM'])?(||OBJ[K](.MEM|['MEM'])?)*;
        return ACC;
    The loop body braces are optional (engine-identical, node
    v24.20.0 verified -- the F529 alias grammar already models
    this; F592 extends it to the object-literal source). The body
    may read `OBJ[K]` (F517), `OBJ[K].MEM` with a single dot
    identifier member or `OBJ[K]['MEM']` with a bracket-string
    member (F592: the nested-object twin -- each enumerated value
    must be an object for the read to resolve; F632: the bracket
    form is engine-identical to the dot form for identifier names,
    node v24.20.0 verified; see the F592 desugar), or a `||` chain
    of such member reads on the same indexed value (F632:
    `s+=o[k].p||o[k].q` -- the compound member-expression twin;
    each operand re-reads `OBJ[K]`, engine-exact). Returns (acc_ident,
    obj_ident, key_ident, objlit_text, member, or_members) where
    member is None or the single member ident string (F517/F592)
    and or_members is None or the non-empty `||`-chain member list
    (F632; the first element is the initial member read). Any other
    statement, extra statement, or shape mismatch fails closed.
    Never evals.
    """
    n = len(text)
    j = _js_skip_ws(text, a)
    if j >= b:
        raise _JSExprFail("forin empty body")
    m = _js_match_kw(text, j, "var")
    if m is None:
        raise _JSExprFail("forin first decl not var")
    j = _js_skip_ws(text, m)
    first, j = _js_parse_ident(text, j)
    j = _js_skip_ws(text, j)
    j = _js_expect(text, j, "=")
    j = _js_skip_ws(text, j)
    acc = None
    obj = None
    objlit_text = None
    if j < n and text[j] in "'\"":
        # Accumulator-first order (the F517/F592 filed shape).
        acc = first
        q0 = j
        _, j = _js_parse_string(text, j)
        if text[q0:j] != "''" and text[q0:j] != '""':
            raise _JSExprFail("forin accum not empty")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ";")
        j = _js_skip_ws(text, j)
        m = _js_match_kw(text, j, "var")
        if m is None:
            raise _JSExprFail("forin obj not var")
        j = _js_skip_ws(text, m)
        obj, j = _js_parse_ident(text, j)
        if obj == acc:
            raise _JSExprFail("forin obj shadows accum")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, "=")
        j = _js_skip_ws(text, j)
        if j >= n or text[j] != "{":
            raise _JSExprFail("forin obj not a literal")
        lit_start = j
        j = _js_span_balanced_braces(text, j)
        objlit_text = text[lit_start:j]
    elif j < n and text[j] == "{":
        # F632: object-first order. The two declarations are
        # independent, so the order is engine-identical (node
        # v24.20.0 verified); the F632 filed shapes declare the
        # object first.
        obj = first
        lit_start = j
        j = _js_span_balanced_braces(text, j)
        objlit_text = text[lit_start:j]
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ";")
        j = _js_skip_ws(text, j)
        m = _js_match_kw(text, j, "var")
        if m is None:
            raise _JSExprFail("forin accum not var")
        j = _js_skip_ws(text, m)
        acc, j = _js_parse_ident(text, j)
        if acc == obj:
            raise _JSExprFail("forin accum shadows obj")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, "=")
        j = _js_skip_ws(text, j)
        if j >= n or text[j] not in "'\"":
            raise _JSExprFail("forin accum not a string")
        q0 = j
        _, j = _js_parse_string(text, j)
        if text[q0:j] != "''" and text[q0:j] != '""':
            raise _JSExprFail("forin accum not empty")
    else:
        raise _JSExprFail("forin first decl not accum-or-obj")
    j = _js_skip_ws(text, j)
    j = _js_expect(text, j, ";")
    j = _js_skip_ws(text, j)
    m = _js_match_kw(text, j, "for")
    if m is None:
        raise _JSExprFail("forin no for")
    j = _js_skip_ws(text, m)
    j = _js_expect(text, j, "(")
    j = _js_skip_ws(text, j)
    m = _js_match_kw(text, j, "var")
    if m is None:
        raise _JSExprFail("forin key not var")
    j = _js_skip_ws(text, m)
    keyvar, j = _js_parse_ident(text, j)
    if keyvar == acc or keyvar == obj:
        raise _JSExprFail("forin key shadows")
    j = _js_skip_ws(text, j)
    m = _js_match_kw(text, j, "in")
    if m is None:
        raise _JSExprFail("forin no in")
    j = _js_skip_ws(text, m)
    obj2, j = _js_parse_ident(text, j)
    if obj2 != obj:
        raise _JSExprFail("forin iterates another object")
    j = _js_skip_ws(text, j)
    j = _js_expect(text, j, ")")
    j = _js_skip_ws(text, j)
    # F592: the loop-body braces are optional (engine-identical,
    # node v24.20.0 verified).
    braced = False
    if j < b and text[j] == "{":
        braced = True
        j = _js_skip_ws(text, j + 1)
    acc2, j = _js_parse_ident(text, j)
    if acc2 != acc:
        raise _JSExprFail("forin accum mismatch")
    j = _js_skip_ws(text, j)
    if not text.startswith("+=", j):
        raise _JSExprFail("forin body not +=")
    j = _js_skip_ws(text, j + 2)
    obj3, j = _js_parse_ident(text, j)
    if obj3 != obj:
        raise _JSExprFail("forin body reads another object")
    j = _js_skip_ws(text, j)
    j = _js_expect(text, j, "[")
    key2, j = _js_parse_ident(text, _js_skip_ws(text, j))
    if key2 != keyvar:
        raise _JSExprFail("forin body indexes another key")
    j = _js_skip_ws(text, j)
    j = _js_expect(text, j, "]")
    j = _js_skip_ws(text, j)
    # F592: an optional single member read on the indexed value
    # (`s+=o[k].v` -- dot identifier; F632: `s+=o[k]['v']` --
    # bracket-string, engine-identical for identifier names, node
    # v24.20.0 verified); anything else (a call, a deeper chain)
    # fails closed.
    member = None
    or_members = None
    if j < b and text[j] == ".":
        j = _js_skip_ws(text, j + 1)
        member, j = _js_parse_ident(text, j)
        j = _js_skip_ws(text, j)
    elif j < b and text[j] == "[":
        # F632: the bracket-string member form. Engine-identical to
        # the dot form for the identifier names
        # `_js_parse_bracket_member` accepts (node v24.20.0
        # verified); it flows through the same single-member path
        # as the dot form.
        member, j = _js_parse_bracket_member(text, j)
        j = _js_skip_ws(text, j)
    if member is not None:
        # F632: a `||` chain of member reads on the same indexed
        # value (`s+=o[k].p||o[k].q`). Each operand re-reads
        # `OBJ[KEY]`; `||=` (logical assignment) is engine-different
        # and fails closed here.
        j2 = _js_skip_ws(text, j)
        if j2 < b and text.startswith("||", j2) \
                and not text.startswith("||=", j2):
            or_members = [member]
            member = None
            j = j2
            while True:
                j = _js_skip_ws(text, j + 2)
                obj4, j = _js_parse_ident(text, j)
                if obj4 != obj:
                    raise _JSExprFail("F632 or reads another object")
                j = _js_skip_ws(text, j)
                j = _js_expect(text, j, "[")
                key3, j = _js_parse_ident(text, _js_skip_ws(text, j))
                if key3 != keyvar:
                    raise _JSExprFail("F632 or indexes another key")
                j = _js_skip_ws(text, j)
                j = _js_expect(text, j, "]")
                j = _js_skip_ws(text, j)
                if j < b and text[j] == ".":
                    j = _js_skip_ws(text, j + 1)
                    mname, j = _js_parse_ident(text, j)
                elif j < b and text[j] == "[":
                    mname, j = _js_parse_bracket_member(text, j)
                else:
                    raise _JSExprFail("F632 or operand not a read")
                or_members.append(mname)
                j = _js_skip_ws(text, j)
                j2 = j
                if j2 < b and text.startswith("||", j2) \
                        and not text.startswith("||=", j2):
                    j = j2
                    continue
                break
    j = _js_expect(text, j, ";")
    j = _js_skip_ws(text, j)
    if braced:
        j = _js_expect(text, j, "}")
        j = _js_skip_ws(text, j)
    m = _js_match_kw(text, j, "return")
    if m is None:
        raise _JSExprFail("forin no return")
    j = _js_skip_ws(text, m)
    acc3, j = _js_parse_ident(text, j)
    if acc3 != acc:
        raise _JSExprFail("forin returns another ident")
    j = _js_skip_ws(text, j)
    if j < n and text[j] == ";":
        j += 1
    j = _js_skip_ws(text, j)
    if j != b:
        raise _JSExprFail("forin trailing statements")
    return acc, obj, keyvar, objlit_text, member, or_members


def _js_parse_f578_defineprop_stmt(text, sj, oname, depth, state):
    """Parse one `Object.defineProperty(o,'K',DESC);` statement at
    text[sj] (F578).

    The target must be the bare bound ident *oname*; the key a
    string literal (`__proto__` fails closed); the descriptor parsed
    by `_js_parse_f548f550_descriptor` (F550's exact discipline,
    F591's `set` shape included). Returns (key, kind, dval,
    next_index) just after the statement's `;`. Raises _JSExprFail
    on any mismatch (the caller treats it as end-of-sequence or a
    hard fail). Never evals.
    """
    n = len(text)
    sj = _js_skip_ws(text, sj)
    if not text.startswith("Object", sj):
        raise _JSExprFail("F578 not defineProperty")
    q = sj + len("Object")
    if q < n and text[q] in _JS_IDENT_CONT:
        raise _JSExprFail("F578 Objectx")
    q = _js_skip_ws(text, q)
    q = _js_expect(text, q, ".")
    q = _js_skip_ws(text, q)
    if not text.startswith("defineProperty", q):
        raise _JSExprFail("F578 not defineProperty member")
    q2 = q + len("defineProperty")
    if q2 < n and text[q2] in _JS_IDENT_CONT:
        raise _JSExprFail("F578 defineProperties")
    q = _js_skip_ws(text, q2)
    q = _js_expect(text, q, "(")
    q = _js_skip_ws(text, q)
    tname, q = _js_parse_ident(text, q)
    if tname != oname:
        raise _JSExprFail("F578 defineProperty other target")
    q = _js_skip_ws(text, q)
    q = _js_expect(text, q, ",")
    q = _js_skip_ws(text, q)
    if q >= n or text[q] not in "'\"":
        raise _JSExprFail("F578 key not a literal")
    key, q = _js_parse_string(text, q)
    if key == "__proto__":
        raise _JSExprFail("F578 __proto__ fails closed")
    q = _js_skip_ws(text, q)
    q = _js_expect(text, q, ",")
    q = _js_skip_ws(text, q)
    if q >= n or text[q] != "{":
        raise _JSExprFail("F578 descriptor not an object")
    dkind, dval, q = _js_parse_f548f550_descriptor(text, q, depth,
                                                       state)
    q = _js_skip_ws(text, q)
    q = _js_expect(text, q, ")")
    q = _js_skip_ws(text, q)
    q = _js_expect(text, q, ";")
    return key, dkind, dval, q


def _js_parse_f591_assign_stmt(text, sj, oname, setters, new_props,
                               depth, state):
    """Parse one `o.c='lit';` assignment at text[sj] (F591).

    The target must be the bare bound ident *oname* with a `.ident`
    / `['literal']` member naming a key that has a recorded
    `set`-descriptor (F591): the engine invokes the setter with
    `this === o`, storing the assigned literal at the setter's
    target property node-exactly. The assigned value must be a
    string literal (carrier-escape tolerant, F590). An assignment
    to a key with no recorded setter raises _JSExprFail (the caller
    treats it as end-of-sequence -- the F578 exact-shape grammar
    has no room for rebinding, unchanged). Never evals.
    """
    n = len(text)
    sj = _js_skip_ws(text, sj)
    aname, q = _js_parse_ident(text, sj)
    if aname != oname:
        raise _JSExprFail("F591 assigns another ident")
    q = _js_skip_ws(text, q)
    if q < n and text[q] == "[":
        member, q = _js_parse_bracket_member(text, q)
    elif q < n and text[q] == ".":
        q = _js_skip_ws(text, q + 1)
        member, q = _js_parse_ident(text, q)
    else:
        raise _JSExprFail("F591 assignment not a member")
    if member not in setters:
        raise _JSExprFail("F591 assignment without setter")
    if setters[member] == member:
        # Self-recursive setter: the engine invokes the setter again
        # on `this[member] = v`, recursing to a RangeError (node
        # v24.20.0 verified) -- a throwing shape cannot exfiltrate,
        # so fail closed rather than emit a variant for it.
        raise _JSExprFail("F591 setter self-recursion throws")
    q = _js_skip_ws(text, q)
    q = _js_expect(text, q, "=")
    q = _js_skip_ws(text, q)
    aval, q = _js_parse_string_carrier_tolerant(text, q)
    if not isinstance(aval, str):
        raise _JSExprFail("F591 assigns non-string")
    q = _js_skip_ws(text, q)
    q = _js_expect(text, q, ";")
    new_props[setters[member]] = aval
    state["parts"] += 1  # the setter invocation is obfuscation-shaped
    if state["parts"] > _JS_EXPR_MAX_PARTS:
        raise _JSExprFail("too many parts")
    return q


def _js_parse_f578_defineprop_iife(text, i, depth, state):
    """Parse `(function(){DECL o=OBJLIT;Object.defineProperty(o,K,D);
    return o.M;})(...)` at text[i] (F578).

    Descriptor replacement on a var-bound literal target: F550
    models `Object.defineProperty` on a DIRECT literal target, but a
    target bound to a var (the IIFE statement-sequence form) is a
    different production. Node-exact desugar (v24.20.0): the var
    binds the parsed literal (F535 object -- string values,
    canonical ints, nested objects; getters evaluated at parse
    time), the defineProperty call replaces key K's descriptor per
    the engine's descriptor-merge semantics, and the IIFE evaluates
    to the return member read on the replaced object (defineProperty
    returns the target itself).

    The exact modeled shape (ws-tolerant):
        (function(){var|const|let o={...};
         Object.defineProperty(o,'K',{value:V} | {get:FN} | {set:SF});
         [o.J='lit'; ...];
         return EXPR;})()
    One or more defineProperty statements may follow the binding
    (descriptor merge is a per-key overwrite, so sequences apply
    node-exactly in order). F591: a `{set:function(v){this._c=v;}}`
    descriptor records a setter; a later `o.J='lit';` statement
    invokes it node-exactly (the engine calls the setter with
    `this === o`, storing the literal at `this._c`). The return
    EXPR is an additive concatenation of `o.M` member reads and
    string literals with at least one member read (F591); the
    legacy `return o.M;` is the single-operand case.
    The descriptor is parsed by `_js_parse_f548f550_descriptor` --
    F550's exact discipline: `{value: V}` installs V; `{get:
    function(){return EXPR}}` installs the getter's evaluated
    return; `set`/unknown keys fail closed; `{get, writable}` and
    `{value, get}` throw in the engine and fail closed here.
    Descriptor merge is an overwrite of the key (node-exact for the
    modeled classes: data->data value swap, data->accessor getter
    install, accessor->data replacement -- verified against node
    v24.20.0).

    Returns (value, next_index), or None when text[i] is not this
    shape (the caller falls through to F535). The invocation must be
    exactly `()` -- the filed shapes take no arguments.

    Bounds (all fail closed -- rejected, never mis-decoded):
    - a named function, parameters, or any other body shape (extra
      statements, reassignment of the var -- the exact-shape
      grammar has no room for rebinding);
    - a defineProperty target other than the bare bound ident, a
      non-literal key, `__proto__`;
    - a return member other than `.ident` / `['literal']` on the
      bound ident; a missing key (the engine yields undefined --
      not a decodable value);
    - non-empty call arguments (the engine ignores them for a
      zero-param function, but the lane stays conservative --
      documented boundary).
    Residual (documented, negligible): a descriptor carrying
    `configurable:false` followed by a redefine throws TypeError in
    the engine, but F550's shared descriptor parser accepts-and-
    ignores the flag, so the decoder yields the later value on a
    throwing shape. Throwing shapes cannot exfiltrate (the engine
    never produces a value), and the flag grammar is F550's -- out
    of this lane's scope.
    Never evals.
    """
    n = len(text)
    j = _js_skip_ws(text, i)
    if j >= n or text[j] != "(":
        return None
    k = _js_skip_ws(text, j + 1)
    if not text.startswith("function", k):
        return None
    k2 = k + len("function")
    if k2 < n and text[k2] in _JS_IDENT_CONT:
        return None  # functionx -- not our shape
    if k2 < n and text[k2] in _JS_IDENT_START:
        return None  # named function -- not our shape
    try:
        j = _js_skip_ws(text, k2)
        j = _js_expect(text, j, "(")
        j = _js_expect(text, j, ")")
        brace = _js_skip_ws(text, j)
        j = _js_expect(text, brace, "{")
        inner_start, inner_end, j = _js_span_braced(text, brace)
        # F560: skip a leading directive prologue ('use strict'; ...)
        # before matching the binding declaration (node-exact:
        # directives are inert string-literal statements at body
        # start).
        sj = inner_start + _js_skip_directive_prologue(
            text[inner_start:inner_end], state)
        sj = _js_skip_ws(text, sj)
        _kw, m = _js_match_decl_kw(text, sj)
        if _kw is None:
            raise _JSExprFail("F578 decl not var/const/let")
        sj = _js_skip_ws(text, m)
        oname, sj = _js_parse_ident(text, sj)
        if oname == "arguments":
            raise _JSExprFail("F578 binding named arguments")
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, "=")
        sj = _js_skip_ws(text, sj)
        if sj >= n or text[sj] != "{":
            raise _JSExprFail("F578 binding not an object literal")
        props, sj = _js_parse_f535_object(text, sj, depth, state)
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, ";")
        # One or more `Object.defineProperty(o,'K',DESC);`
        # statements -- descriptor merge is a per-key overwrite, so
        # a sequence applies node-exactly in order (each statement
        # charges the parts budget via the descriptor parse, and
        # every iteration consumes input, so the loop is bounded).
        new_props = dict(props)
        setters = {}  # F591: key -> setter target prop
        saw_defineprop = False
        while True:
            save = sj
            try:
                key, dkind, dval, sj = _js_parse_f578_defineprop_stmt(
                    text, sj, oname, depth, state)
            except _JSExprFail:
                # F591: `o.c='lit';` setter-invocation statements.
                try:
                    sj = _js_parse_f591_assign_stmt(
                        text, save, oname, setters, new_props,
                        depth, state)
                except _JSExprFail:
                    sj = save
                    break
                continue
            if dkind == "set":
                # The engine installs an accessor with no data
                # value; the setter fires only via assignment.
                setters[key] = dval[1]
            else:
                new_props[key] = dval
            saw_defineprop = True
        if not saw_defineprop:
            raise _JSExprFail("F578 no defineProperty statement")
        # return EXPR; -- F591: EXPR is an additive concatenation
        # of `o.M` member reads on the bound ident and string
        # literals, with at least one member read (a pure literal
        # concat is not this shape). Each member must resolve in
        # new_props (the engine yields undefined otherwise -- not a
        # decodable value); every operand must be a string
        # (node-exact `+` on strings). Previously only `return o.M;`
        # was accepted, so this admits only previously-failing
        # inputs.
        q = _js_skip_ws(text, sj)
        rk = _js_match_kw(text, q, "return")
        if rk is None:
            raise _JSExprFail("F578 body not return")
        q = _js_skip_ws(text, rk)
        parts = []
        saw_member = False
        while True:
            q = _js_skip_ws(text, q)
            if q < n and (text[q] in "'\"" or (
                    text[q] == "\\" and q + 1 < n
                    and text[q + 1] in "'\"")):
                sval, q = _js_parse_string_carrier_tolerant(text, q)
                if not isinstance(sval, str):
                    raise _JSExprFail("F578 return non-string")
                parts.append(sval)
            else:
                rname, q2 = _js_parse_ident(text, q)
                if rname != oname:
                    raise _JSExprFail("F578 returns another ident")
                q = _js_skip_ws(text, q2)
                if q < n and text[q] == "[":
                    member, q = _js_parse_bracket_member(text, q)
                elif q < n and text[q] == ".":
                    q = _js_skip_ws(text, q + 1)
                    member, q = _js_parse_ident(text, q)
                else:
                    raise _JSExprFail("F578 return not a member read")
                if not isinstance(member, str) \
                        or member not in new_props:
                    # The engine yields undefined -- not a decodable
                    # value.
                    raise _JSExprFail("F578 return key missing")
                mval = new_props[member]
                if not isinstance(mval, str):
                    raise _JSExprFail("F578 return member non-string")
                parts.append(mval)
                saw_member = True
            state["parts"] += 1  # each return operand is
                                 # obfuscation-shaped (F452)
            if state["parts"] > _JS_EXPR_MAX_PARTS:
                raise _JSExprFail("too many parts")
            q = _js_skip_ws(text, q)
            if q < n and text[q] == "+":
                q = _js_skip_ws(text, q + 1)
                continue
            break
        if not saw_member:
            raise _JSExprFail("F578 return without member read")
        q = _js_skip_ws(text, q)
        if q < n and text[q] == ";":
            q += 1
        q = _js_skip_ws(text, q)
        if q != inner_end:
            raise _JSExprFail("F578 trailing statements")
        # Invocation: exactly `()`.
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, "(")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        # Descriptor merge is a per-key overwrite (node-exact for the
        # modeled descriptor classes -- data->data, data->accessor,
        # accessor->data); sequences apply in order. The return EXPR
        # was resolved operand-by-operand above (missing keys already
        # failed closed there).
        state["ops"] += 1  # the iife wrapper is obfuscation-shaped
        state["parts"] += 1  # the defineProperty statement(s) are
                           # obfuscation-shaped
        if state["parts"] > _JS_EXPR_MAX_PARTS:
            raise _JSExprFail("too many parts")
        return "".join(parts), j
    except _JSExprFail:
        return None


def _js_parse_f599_params_mutation_iife(text, i, depth, state):
    """Parse `(function(){DECL p=new URLSearchParams('LIT');[MUT;]*return p.getAll('K')<postfix>;})()` at text[i] (F599).

    Statement-form URLSearchParams mutations: F576 models `.get` on
    constructor strings and F584 models `.getAll` on constructor
    strings, but a var-bound params object mutated by `.append`/`.set`
    statements before the terminal read is a different production --
    the constructor-string model never sees the appended pairs.
    Node-exact desugar (v24.20.0):
    - `var|const|let p=new URLSearchParams('LIT')` binds p to the
      _JSURLParams over the form-urlencoded pairs (F576's parse --
      urllib.parse.parse_qsl, node-identical);
    - `p.append('N','V');` appends the (N, V) pair (engine-exact);
    - `p.set('N','V');` replaces the first N-pair's value and drops
      every other N-pair, or appends when N is absent
      (engine-exact, node v24.20.0);
    - `return p.getAll('K')` + the normal postfix chain: F584's
      getAll (all K-values in insertion order as a _JSArr; a missing
      name is the empty array, node-exact) flowing through
      _js_parse_postfix (.join / .slice / indexed reads). The return
      value must be a string to be decodable (a bare getAll yields
      an array, which is not a decodable value).
    The invocation must be exactly `()`.

    Bounds (all fail closed -- rejected, never mis-decoded):
    - a `new URL(...)` binding (the .searchParams receiver is
      modeled by the F617 parser, tried later in the dispatch --
      corrected wave-374; a bare `new URL` binding without
      .searchParams still fails closed), a non-literal constructor
      arg;
    - mutation members other than append/set (sort/delete/has/...
      reorder or remove pairs the model cannot see -- the whole
      shape fails closed rather than mis-decode; documented
      residual);
    - non-literal mutation names/values, extra mutation args, a
      receiver other than the bare bound ident, a missing `;`;
    - a named function, parameters, a directive prologue, extra
      statements, reassignment of the var, non-empty call args.
    Returns (value, next_index), or None when text[i] is not this
    shape. Never evals.
    """
    n = len(text)
    j = _js_skip_ws(text, i)
    if j >= n or text[j] != "(":
        return None
    k = _js_skip_ws(text, j + 1)
    if not text.startswith("function", k):
        return None
    k2 = k + len("function")
    if k2 < n and text[k2] in _JS_IDENT_CONT:
        return None  # functionx -- not our shape
    if k2 < n and text[k2] in _JS_IDENT_START:
        return None  # named function -- not our shape
    try:
        j = _js_skip_ws(text, k2)
        j = _js_expect(text, j, "(")
        j = _js_expect(text, j, ")")
        brace = _js_skip_ws(text, j)
        j = _js_expect(text, brace, "{")
        inner_start, inner_end, j = _js_span_braced(text, brace)
        sj = _js_skip_ws(text, inner_start)
        _kw, m = _js_match_decl_kw(text, sj)
        if _kw is None:
            raise _JSExprFail("F599 decl not var/const/let")
        sj = _js_skip_ws(text, m)
        pname, sj = _js_parse_ident(text, sj)
        if pname == "arguments":
            raise _JSExprFail("F599 binding named arguments")
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, "=")
        sj = _js_skip_ws(text, sj)
        _pv = _js_parse_f576_new_url(text, sj, depth, state)
        if _pv is None or not isinstance(_pv[0], _JSURLParams):
            # A `new URL(...)` binding owns the searchParams receiver
            # (F617, tried later in the dispatch) -- fail closed here.
            raise _JSExprFail("F599 binding not URLSearchParams")
        _pv, sj = _pv
        pairs = list(_pv.pairs)
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, ";")
        # Zero or more `p.append('N','V');` / `p.set('N','V');`
        # mutation statements. Every iteration consumes input, so
        # the loop is bounded; each statement charges the parts
        # budget (F452).
        while True:
            save = sj
            q = _js_skip_ws(text, sj)
            try:
                rname, q = _js_parse_ident(text, q)
            except _JSExprFail:
                break
            if rname != pname:
                break
            q = _js_skip_ws(text, q)
            if q >= n or text[q] not in ".[":
                break
            try:
                _mname, q = _js_f576_member_name(text, q, "f599")
            except _JSExprFail:
                break
            if _mname not in ("append", "set"):
                # sort/delete/has/... are unmodeled mutations --
                # fail the whole shape closed rather than
                # mis-decode (documented residual).
                raise _JSExprFail("F599 member not append/set")
            q = _js_skip_ws(text, q)
            if q >= n or text[q] != "(":
                raise _JSExprFail("F599 mutation without paren")
            q = _js_skip_ws(text, q + 1)
            if q >= n or text[q] not in "'\"":
                raise _JSExprFail("F599 mutation name not a literal")
            _mn, q = _js_parse_string(text, q)
            q = _js_skip_ws(text, q)
            if q >= n or text[q] != ",":
                raise _JSExprFail("F599 mutation arity")
            q = _js_skip_ws(text, q + 1)
            if q >= n or text[q] not in "'\"":
                raise _JSExprFail("F599 mutation value not a literal")
            _mv, q = _js_parse_string(text, q)
            q = _js_skip_ws(text, q)
            if q >= n or text[q] != ")":
                raise _JSExprFail("F599 mutation unterminated")
            q = _js_skip_ws(text, q + 1)
            if q >= n or text[q] != ";":
                raise _JSExprFail("F599 mutation without semicolon")
            if _mname == "append":
                pairs.append((_mn, _mv))
            else:
                # Engine-exact set (node v24.20.0): the first pair
                # with the name takes the new value; every other
                # pair with the name is removed; a missing name
                # appends.
                _seen = False
                _np = []
                for _pn, _pvv in pairs:
                    if _pn != _mn:
                        _np.append((_pn, _pvv))
                    elif not _seen:
                        _seen = True
                        _np.append((_pn, _mv))
                if not _seen:
                    _np.append((_mn, _mv))
                pairs = _np
            state["parts"] += 1  # the mutation is obfuscation-shaped
            if state["parts"] > _JS_EXPR_MAX_PARTS:
                raise _JSExprFail("too many parts")
            sj = q + 1
        # return p.getAll('K')<postfix>;
        q = _js_skip_ws(text, sj)
        rk = _js_match_kw(text, q, "return")
        if rk is None:
            raise _JSExprFail("F599 body not return")
        q = _js_skip_ws(text, rk)
        rname, q = _js_parse_ident(text, q)
        if rname != pname:
            raise _JSExprFail("F599 returns another ident")
        q = _js_skip_ws(text, q)
        if q >= n or text[q] not in ".[":
            raise _JSExprFail("F599 return not a member read")
        _mname, q = _js_f576_member_name(text, q, "f599")
        if _mname != "getAll":
            # `.get` returns only the first value and cannot
            # assemble a credential from fragments (a full value in
            # one literal is already caught by the raw scan); a
            # bare getAll yields an array, not a decodable value.
            raise _JSExprFail("F599 return not getAll")
        q = _js_skip_ws(text, q)
        if q >= n or text[q] != "(":
            raise _JSExprFail("F599 getAll without paren")
        q = _js_skip_ws(text, q + 1)
        if q >= n or text[q] not in "'\"":
            raise _JSExprFail("F599 getAll key not a literal")
        _gkey, q = _js_parse_string(text, q)
        q = _js_skip_ws(text, q)
        if q >= n or text[q] != ")":
            raise _JSExprFail("F599 getAll unterminated")
        _gvals = [_pval for _pname2, _pval in pairs
                  if _pname2 == _gkey]
        state["parts"] += len(_gvals)
        if state["parts"] > _JS_EXPR_MAX_PARTS:
            raise _JSExprFail("too many parts")
        q = _js_skip_ws(text, q + 1)
        # The getAll array flows through the normal postfix chain
        # (F584 precedent: .join / .slice / indexed reads); the
        # return value must be a string to be decodable.
        _rval, q = _js_parse_postfix(text, q, _JSArr(_gvals), depth,
                                     state)
        if not isinstance(_rval, str):
            raise _JSExprFail("F599 return not a string")
        q = _js_skip_ws(text, q)
        if q >= n or text[q] != ";":
            raise _JSExprFail("F599 return without semicolon")
        q = _js_skip_ws(text, q + 1)
        if q != inner_end:
            raise _JSExprFail("F599 trailing statements")
        # Invocation: exactly `()`.
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, "(")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        state["ops"] += 1  # the iife wrapper is obfuscation-shaped
        return _rval, j
    except _JSExprFail:
        return None


def _js_parse_f648_noarg_params_iife(text, i, depth, state):
    """Parse `(function(){DECL p=new URLSearchParams();[MUT;]*return p.getAll('K')<postfix>;})()` at text[i] (F648).

    Statement-form URLSearchParams mutations on the NO-ARGUMENT
    constructor: F599 (CLOSED) models append/set mutations on
    `new URLSearchParams('LIT')` (its grammar requires a literal
    constructor string via `_js_parse_f576_new_url`, which raises on
    empty parens), but the no-arg constructor with the same appends
    and a getAll('K').join('') terminal had no modeled path --
    `var p=new URLSearchParams();p.append('q','f1');
    p.append('q','f2');return p.getAll('q').join('');`
    node-evaluates (v24.20.0) to the assembled credential while the
    decoder produced zero variants. Node-exact desugar (v24.20.0):
    - `var|const|let p=new URLSearchParams()` binds p to the empty
      _JSURLParams (no pairs; the engine starts empty);
    - `p.append('N','V');` / `p.set('N','V');` mutate engine-exactly
      (same set semantics as F599);
    - `return p.getAll('K')` + the normal postfix chain: all
      K-values in insertion order as a _JSArr; a missing name is
      the empty array (node-exact); the return value must be a
      string to be decodable (bare getAll yields an array).
    The invocation must be exactly `()`. Disjoint from F599 (which
    requires the literal ctor arg -- this route fails closed on
    any non-empty ctor arg) and from F606/F610/F616/F617/F626 (all
    require the literal-ctor or `new URL` binding and reject empty
    parens in `_js_parse_f576_new_url`), so no previously-decoded
    input changes behavior. Tried after F626 in the dispatch.
    `.get` terminals fail closed here: get returns only the first
    value (node-exact), so it cannot assemble a credential from
    fragments (a full value in one literal is already caught by
    the raw scan -- verified control, wave-377).

    Bounds (all fail closed -- rejected, never mis-decoded):
    - a non-empty constructor arg (F599 owns it), `new URL(...)`
      bindings (F617), non-literal mutation names/values, extra
      mutation args, mutation members other than append/set
      (sort/delete/has/... -- documented residual, F599
      precedent), a receiver other than the bare bound ident, a
      missing `;`;
    - var-bound mutation names/values (F616-class hybrid --
      documented residual; the wave-374 lane-5 precedent files
      such hybrids as new findings);
    - a named function, parameters, a directive prologue, extra
      statements, reassignment of the var, non-empty call args.
    Returns (value, next_index), or None when text[i] is not this
    shape. Never evals.
    """
    n = len(text)
    j = _js_skip_ws(text, i)
    if j >= n or text[j] != "(":
        return None
    k = _js_skip_ws(text, j + 1)
    if not text.startswith("function", k):
        return None
    k2 = k + len("function")
    if k2 < n and text[k2] in _JS_IDENT_CONT:
        return None  # functionx -- not our shape
    if k2 < n and text[k2] in _JS_IDENT_START:
        return None  # named function -- not our shape
    try:
        j = _js_skip_ws(text, k2)
        j = _js_expect(text, j, "(")
        j = _js_expect(text, j, ")")
        brace = _js_skip_ws(text, j)
        j = _js_expect(text, brace, "{")
        inner_start, inner_end, j = _js_span_braced(text, brace)
        sj = _js_skip_ws(text, inner_start)
        _kw, m = _js_match_decl_kw(text, sj)
        if _kw is None:
            raise _JSExprFail("F648 decl not var/const/let")
        sj = _js_skip_ws(text, m)
        pname, sj = _js_parse_ident(text, sj)
        if pname == "arguments":
            raise _JSExprFail("F648 binding named arguments")
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, "=")
        sj = _js_skip_ws(text, sj)
        # No-arg constructor only: `new URLSearchParams()`. Any
        # argument (even '') belongs to F599/F606/F610/F616.
        _nk = _js_match_kw(text, sj, "new")
        if _nk is None:
            raise _JSExprFail("F648 binding not new")
        _nk = _js_skip_ws(text, _nk)
        _uk = _js_match_kw(text, _nk, "URLSearchParams")
        if _uk is None:
            raise _JSExprFail("F648 binding not URLSearchParams")
        _uk = _js_skip_ws(text, _uk)
        if _uk >= n or text[_uk] != "(":
            raise _JSExprFail("F648 ctor without paren")
        _uk = _js_skip_ws(text, _uk + 1)
        if _uk >= n or text[_uk] != ")":
            raise _JSExprFail("F648 ctor not no-arg")
        sj = _uk + 1
        pairs = []
        state["parts"] += 1  # the binding is obfuscation-shaped
        if state["parts"] > _JS_EXPR_MAX_PARTS:
            raise _JSExprFail("too many parts")
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, ";")
        # Zero or more `p.append('N','V');` / `p.set('N','V');`
        # mutation statements -- the same engine-exact loop as
        # F599 (F599 precedent; every iteration consumes input).
        while True:
            save = sj
            q = _js_skip_ws(text, sj)
            try:
                rname, q = _js_parse_ident(text, q)
            except _JSExprFail:
                break
            if rname != pname:
                break
            q = _js_skip_ws(text, q)
            if q >= n or text[q] not in ".[":
                break
            try:
                _mname, q = _js_f576_member_name(text, q, "f648")
            except _JSExprFail:
                break
            if _mname not in ("append", "set"):
                # sort/delete/has/... are unmodeled mutations --
                # fail the whole shape closed rather than
                # mis-decode (F599 precedent, documented
                # residual).
                raise _JSExprFail("F648 member not append/set")
            q = _js_skip_ws(text, q)
            if q >= n or text[q] != "(":
                raise _JSExprFail("F648 mutation without paren")
            q = _js_skip_ws(text, q + 1)
            if q >= n or text[q] not in "'\"":
                raise _JSExprFail("F648 mutation name not a literal")
            _mn, q = _js_parse_string(text, q)
            q = _js_skip_ws(text, q)
            if q >= n or text[q] != ",":
                raise _JSExprFail("F648 mutation arity")
            q = _js_skip_ws(text, q + 1)
            if q >= n or text[q] not in "'\"":
                raise _JSExprFail("F648 mutation value not a literal")
            _mv, q = _js_parse_string(text, q)
            q = _js_skip_ws(text, q)
            if q >= n or text[q] != ")":
                raise _JSExprFail("F648 mutation unterminated")
            q = _js_skip_ws(text, q + 1)
            if q >= n or text[q] != ";":
                raise _JSExprFail("F648 mutation without semicolon")
            if _mname == "append":
                pairs.append((_mn, _mv))
            else:
                # Engine-exact set (node v24.20.0), same as F599.
                _seen = False
                _np = []
                for _pn, _pvv in pairs:
                    if _pn != _mn:
                        _np.append((_pn, _pvv))
                    elif not _seen:
                        _seen = True
                        _np.append((_pn, _mv))
                if not _seen:
                    _np.append((_mn, _mv))
                pairs = _np
            state["parts"] += 1  # the mutation is obfuscation-shaped
            if state["parts"] > _JS_EXPR_MAX_PARTS:
                raise _JSExprFail("too many parts")
            sj = q + 1
        # return p.getAll('K')<postfix>;
        q = _js_skip_ws(text, sj)
        rk = _js_match_kw(text, q, "return")
        if rk is None:
            raise _JSExprFail("F648 body not return")
        q = _js_skip_ws(text, rk)
        rname, q = _js_parse_ident(text, q)
        if rname != pname:
            raise _JSExprFail("F648 returns another ident")
        q = _js_skip_ws(text, q)
        if q >= n or text[q] not in ".[":
            raise _JSExprFail("F648 return not a member read")
        _mname, q = _js_f576_member_name(text, q, "f648")
        if _mname != "getAll":
            # `.get` returns only the first value and cannot
            # assemble a credential from fragments (verified
            # control: full-value literals are already caught by
            # the raw scan); a bare getAll yields an array, not a
            # decodable value.
            raise _JSExprFail("F648 return not getAll")
        q = _js_skip_ws(text, q)
        if q >= n or text[q] != "(":
            raise _JSExprFail("F648 getAll without paren")
        q = _js_skip_ws(text, q + 1)
        if q >= n or text[q] not in "'\"":
            raise _JSExprFail("F648 getAll key not a literal")
        _gkey, q = _js_parse_string(text, q)
        q = _js_skip_ws(text, q)
        if q >= n or text[q] != ")":
            raise _JSExprFail("F648 getAll unterminated")
        _gvals = [_pval for _pname2, _pval in pairs
                  if _pname2 == _gkey]
        state["parts"] += len(_gvals)
        if state["parts"] > _JS_EXPR_MAX_PARTS:
            raise _JSExprFail("too many parts")
        q = _js_skip_ws(text, q + 1)
        # The getAll array flows through the normal postfix chain
        # (F584 precedent: .join / .slice / indexed reads, F517
        # identity-callback maps); the return value must be a
        # string to be decodable.
        _rval, q = _js_parse_postfix(text, q, _JSArr(_gvals), depth,
                                     state)
        if not isinstance(_rval, str):
            raise _JSExprFail("F648 return not a string")
        q = _js_skip_ws(text, q)
        if q >= n or text[q] != ";":
            raise _JSExprFail("F648 return without semicolon")
        q = _js_skip_ws(text, q + 1)
        if q != inner_end:
            raise _JSExprFail("F648 trailing statements")
        # Invocation: exactly `()`.
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, "(")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        state["ops"] += 1  # the iife wrapper is obfuscation-shaped
        return _rval, j
    except _JSExprFail:
        return None


def _js_f592_member_join(objlit_text, member, depth, state):
    """Join the `MEMBER` reads of a for-in over an object literal (F592).

    Desugars `for(var K in O)S+=O[K].MEM` over a literal object O:
    the enumerated values are the own values in for-in order
    (integer indices ascending, then string keys in insertion order
    -- `_js_ownkeys_order`; symbol keys are not enumerated by
    for-in, node v24.20.0). Each value's `.MEM` read resolves
    node-exactly:
    - a _JSObj value: the member lookup (missing -> the string
      "undefined", the engine's ToString(undefined); a string
      value resolves; a non-string present value fails closed,
      documented);
    - a string value: "undefined" (the engine boxes primitives,
      node-verified `('x').v === undefined`).
    Anything else fails closed. The literal is parsed by
    `_js_parse_f535_object` (its per-property part budget applies),
    so getters/`__proto__`/computed keys fail closed there as
    before. Returns the joined string. Never evals.
    """
    props, _ = _js_parse_f535_object(objlit_text, 0, depth, state)
    out = []
    for key in _js_ownkeys_order(props):
        if not isinstance(key, str):
            continue  # for-in skips symbol keys (node v24.20.0)
        v = props[key]
        if isinstance(v, _JSObj):
            mv = _jsobj_lookup(v, member)
            if mv is None:
                out.append("undefined")
            elif isinstance(mv, str):
                out.append(mv)
            else:
                raise _JSExprFail("F592 member value not a string")
        elif isinstance(v, str):
            # primitive values box: ('x').v is undefined (node-exact)
            out.append("undefined")
        else:
            raise _JSExprFail("F592 value not an object or string")
    return "".join(out)


# Member names that resolve through Object.prototype in the engine
# (node v24.20.0). A for-in OR-chain member read of one of these
# names does NOT yield undefined for a missing own property -- the
# engine returns the prototype's member (a function or object,
# always truthy) -- so the static "missing means falsy" model
# would mis-decode. F632 fails these names closed (documented);
# every other absent name is engine-exactly undefined.
_JS_F632_PROTO_MEMBERS = (
    "__proto__", "constructor", "hasOwnProperty", "isPrototypeOf",
    "propertyIsEnumerable", "toLocaleString", "toString", "valueOf",
    "__defineGetter__", "__defineSetter__", "__lookupGetter__",
    "__lookupSetter__",
)


def _js_scan_f632_numeric_zero(text, members):
    """Detect a numeric `0` property value under a chain-member name
    (F632 helper).

    String-aware scan of an object-literal text: returns True when
    `<member> : 0` (key as a bare identifier or a quoted string)
    appears with a standalone numeric zero outside string/template
    literals. The F535 value grammar coerces numeric literals to
    strings, so a numeric `0` would otherwise be mis-modeled as the
    truthy string `'0'` (the engine's numeric `0` is falsy and falls
    through the `||` chain); the caller fails the OR-chain closed
    instead (documented boundary -- rejected, never mis-decoded).
    Only a standalone `0` matters: every other canonical integer is
    truthy in the engine exactly like its non-empty string coercion,
    and non-canonical numerals fail closed in the literal grammar.
    Longer numerals (`10`), quoted contents (`'a:0'`), and member
    names that merely prefix a longer identifier never match. Never
    evals.
    """
    n = len(text)
    i = 0
    while i < n:
        c = text[i]
        if c in "'\"":
            try:
                _, i = _js_parse_string(text, i)
            except _JSExprFail:
                i += 1
            continue
        if c == "`":
            i += 1
            while i < n and text[i] != "`":
                if text[i] == "\\":
                    i += 1
                i += 1
            i += 1
            continue
        matched_len = 0
        for m in members:
            # Bare-identifier key.
            if text.startswith(m, i) and not (
                    i > 0 and text[i - 1] in _JS_IDENT_CONT) and not (
                    i + len(m) < n
                    and text[i + len(m)] in _JS_IDENT_CONT):
                matched_len = len(m)
                break
            # Quoted key.
            for q in ("'", '"'):
                qq = q + m + q
                if text.startswith(qq, i) and not (
                        i > 0 and text[i - 1] in _JS_IDENT_CONT):
                    matched_len = len(qq)
                    break
            if matched_len:
                break
        if not matched_len:
            i += 1
            continue
        j = _js_skip_ws(text, i + matched_len)
        if j >= n or text[j] != ":":
            i += 1
            continue
        j = _js_skip_ws(text, j + 1)
        if j < n and text[j] == "0" and not (
                j + 1 < n and text[j + 1] in _ASCII_DIGITS):
            return True
        i = j if j > i else i + 1
    return False


def _js_f632_or_join(objlit_text, members, depth, state):
    """Join the `||`-chained member reads of a for-in over an object
    literal (F632).

    Desugars `for(var K in O)S+=O[K].M1||O[K].M2[||...]` over a
    literal object O: each enumerated value's member chain is
    evaluated with the engine's short-circuit `||` semantics (node
    v24.20.0 verified) -- the first truthy operand wins; when every
    operand is falsy the last operand's value is appended (missing
    reads as the string "undefined", the engine's ToString of
    undefined, exactly as F592's single-member convention). Per
    operand, the F592 member discipline applies: a missing own
    property (and any read on a primitive string value, which the
    engine boxes) is falsy; a present string is truthy iff
    non-empty; a present non-string value fails closed (the
    decoder's string domain cannot model it -- documented). A
    numeric `0` property value under a chain-member name fails the
    whole chain closed (the F535 value grammar coerces numbers to
    strings, losing the engine's falsy-`0`; detected by a
    string-aware scan -- documented boundary). Member names
    resolving through Object.prototype fail closed via
    `_JS_F632_PROTO_MEMBERS` (documented). The literal is parsed by
    `_js_parse_f535_object` (its per-property part budget applies),
    so getters/`__proto__`/computed keys fail closed there as
    before. Symbol keys are skipped by for-in (node v24.20.0), as
    in F592. Returns the joined string. Never evals.
    """
    if _js_scan_f632_numeric_zero(objlit_text, members):
        raise _JSExprFail("F632 numeric zero member fails closed")
    props, _ = _js_parse_f535_object(objlit_text, 0, depth, state)
    out = []
    for key in _js_ownkeys_order(props):
        if not isinstance(key, str):
            continue  # for-in skips symbol keys (node v24.20.0)
        v = props[key]
        if isinstance(v, _JSObj):
            def _lookup(m, _v=v):
                return _jsobj_lookup(_v, m)
        elif isinstance(v, str):
            # primitive values box: ('x').m is undefined for every
            # data member name (node-exact); prototype members fail
            # closed before this point.
            def _lookup(m):
                return None
        else:
            raise _JSExprFail("F632 value not an object or string")
        last = None
        resolved = None
        for m in members:
            if m in _JS_F632_PROTO_MEMBERS:
                raise _JSExprFail("F632 prototype member fails closed")
            mv = _lookup(m)
            last = mv
            if isinstance(mv, str):
                if mv != "":
                    resolved = mv
                    break  # truthy: short-circuit, engine-exact
                # empty string: falsy, fall through to next operand
            elif mv is None:
                continue  # missing: falsy, fall through
            else:
                raise _JSExprFail("F632 member value not a string")
        if resolved is None:
            # Every operand falsy: the engine appends the last
            # operand's value (ToString); a missing last operand is
            # undefined -> "undefined".
            resolved = last if isinstance(last, str) else "undefined"
        out.append(resolved)
    return "".join(out)


def _js_parse_forin_accum_iife(text, i, depth, state):
    """Parse a for-in accumulation IIFE at text[i] (F517/F592/F632).

    The exact modeled shape (ws-tolerant):
        (function(){var A='';var O={...};
         for(var K in O){A+=O[K](.MEM|['MEM'])?
         (||O[K](.MEM|['MEM'])?)*;}return A})()

    Desugars the for-in accumulation idiom: the accumulator starts
    as the empty string and appends each enumerated value in
    for-in order. For a fresh object literal (the only modeled
    source -- getters, methods, `__proto__`, and computed keys all
    fail closed in the literal grammar), for-in order is exactly
    the Object.values enumeration order (integer indices ascending
    first, then string keys in insertion order; the prototype
    chain contributes nothing enumerable -- node v24.20.0
    verified), so the idiom is engine-identical to
    `Object.values(<literal>).join('')`. The desugared text is
    parsed by the normal additive grammar at depth+1, so every
    downstream decoder, bound, and fail-closed rule applies
    unchanged. F592 adds two engine-identical extensions (both
    node v24.20.0 verified): optional braces around the loop body
    (the F529 alias grammar already models these), and an optional
    single `.MEM` member read on the indexed value (the nested
    twin -- resolved by `_js_f592_member_join` over the F535
    object parse; a missing member or a primitive value reads as
    the string "undefined", node-exact). F632 adds the compound
    member-expression twin (node v24.20.0 verified): a `||` chain
    of member reads on the same indexed value
    (`s+=o[k].p||o[k].q`, dot or bracket-string members --
    resolved by `_js_f632_or_join` with the engine's short-circuit
    `||` semantics; prototype-chain member names fail closed).
    The IIFE must be anonymous with zero params and zero call args.
    Returns (value, next_index), or None when the head does not
    match or a guard fails. Bounded by the part/depth budgets; the
    wrapper charges one op (obfuscation-shaped). Never evals.
    """
    if not _js_peek_arguments_iife_head(text, i):
        return None
    n = len(text)
    try:
        j = _js_skip_ws(text, i)
        j = _js_expect(text, j, "(")
        j = _js_skip_ws(text, j) + len("function")
        j = _js_expect(text, j, "(")
        j = _js_expect(text, j, ")")
        brace = _js_skip_ws(text, j)
        j = _js_expect(text, brace, "{")
        inner_start, inner_end, j = _js_span_braced(text, brace)
        # F592: a leading directive prologue is inert in the engine
        # (F560/F570 precedent, node-exact); with no directives this
        # is exactly the prior behavior.
        _ps = _js_skip_directive_prologue(text[inner_start:inner_end],
                                          state)
        _, _, _, objlit_text, member, or_members = _js_split_forin_accum(
            text, inner_start + _ps, inner_end)
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, "(")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        if depth >= _JS_EXPR_MAX_DEPTH:
            raise _JSExprFail("too deep")
        if or_members is not None:
            # F632: the `||` chain of member reads desugars over
            # the F535 object parse directly (a text desugar would
            # depend on callback grammars this path cannot
            # assume); the F592 single-member path below is
            # untouched.
            val = _js_f632_or_join(objlit_text, or_members, depth,
                                   state)
        elif member is not None:
            # F592: the nested-member read desugars over the F535
            # object parse directly (a `.map(x=>x.v)` text desugar
            # would depend on callback grammars this path cannot
            # assume); the member=None path below is untouched.
            val = _js_f592_member_join(objlit_text, member, depth,
                                       state)
        else:
            rewritten = "Object.values(" + objlit_text + ").join('')"
            val, k = _js_parse_additive(rewritten, 0, depth + 1, state)
            k = _js_skip_ws(rewritten, k)
            if k != len(rewritten):
                raise _JSExprFail("f517 forin trailing junk")
        state["ops"] += 1  # the iife wrapper is obfuscation-shaped
        return val, j
    except _JSExprFail:
        return None


def _js_parse_f623_forin_from_entries_iife(text, i, depth, state):
    """Parse a for-in accumulation IIFE over a fromEntries result (F623).

    The exact modeled shape (ws-tolerant):
        (function(){DECL o=Object.fromEntries(...);var s='';
         for(var k in o){s+=o[k];}return s;})()

    F517/F592 model for-in accumulation over object LITERALS, but a
    fromEntries-bound source escapes: the F623 finding's third filed
    shape. Node-exact desugar (v24.20.0): for-in over a fresh
    fromEntries result enumerates in Object.values order (the F565
    model already captures the engine's CreateDataPropertyOnObject
    semantics, including `__proto__` as an own data property), so
    the idiom is engine-identical to
    `Object.values(<fromEntries-text>).join('')`, which the F623
    enumeration-source branch then resolves. The desugared text is
    parsed by the normal additive grammar at depth+1, so every
    downstream decoder, bound, and fail-closed rule applies
    unchanged.

    Bounds (all fail closed -- rejected, never mis-decoded):
    - a binding source other than Object.fromEntries (F517's
      literal grammar stays F517's -- disjoint);
    - a non-empty accumulator, extra statements, reassignment, a
      named function, parameters, call args, or a directive
      prologue;
    - a member read on the indexed value (`s+=o[k].v` -- the F592
      member extension is literal-only);
    - the reversed statement order (accumulator first) -- not filed.
    Returns (value, next_index), or None when the head does not
    match or a guard fails. Never evals.
    """
    n = len(text)
    j = _js_skip_ws(text, i)
    if j >= n or text[j] != "(":
        return None
    k = _js_skip_ws(text, j + 1)
    if not text.startswith("function", k):
        return None
    k2 = k + len("function")
    if k2 < n and text[k2] in _JS_IDENT_CONT:
        return None  # functionx -- not our shape
    if k2 < n and text[k2] in _JS_IDENT_START:
        return None  # named function -- not our shape
    try:
        j = _js_skip_ws(text, k2)
        j = _js_expect(text, j, "(")
        j = _js_expect(text, j, ")")
        brace = _js_skip_ws(text, j)
        j = _js_expect(text, brace, "{")
        inner_start, inner_end, j = _js_span_braced(text, brace)
        sj = _js_skip_ws(text, inner_start)
        # DECL o=Object.fromEntries(...);
        _kw, m = _js_match_decl_kw(text, sj)
        if _kw is None:
            raise _JSExprFail("F623 forin decl not var/const/let")
        sj = _js_skip_ws(text, m)
        oname, sj = _js_parse_ident(text, sj)
        if oname == "arguments":
            raise _JSExprFail("F623 forin binding named arguments")
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, "=")
        sj = _js_skip_ws(text, sj)
        fe_start = sj
        _fe = _js_parse_f565_from_entries(text, sj, depth, state)
        if _fe is None:
            raise _JSExprFail("F623 forin source not fromEntries")
        _, fe_end = _fe
        fe_text = text[fe_start:fe_end]
        sj = _js_skip_ws(text, fe_end)
        sj = _js_expect(text, sj, ";")
        # var s='';
        sj = _js_skip_ws(text, sj)
        m = _js_match_kw(text, sj, "var")
        if m is None:
            raise _JSExprFail("F623 forin accum not var")
        sj = _js_skip_ws(text, m)
        sname, sj = _js_parse_ident(text, sj)
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, "=")
        sj = _js_skip_ws(text, sj)
        if sj >= n or text[sj] not in "'\"":
            raise _JSExprFail("F623 forin accum not a string")
        q0 = sj
        _, sj = _js_parse_string(text, sj)
        if text[q0:sj] != "''" and text[q0:sj] != '""':
            raise _JSExprFail("F623 forin accum not empty")
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, ";")
        # for(var k in o){s+=o[k];} -- braces optional (F592 parity).
        sj = _js_skip_ws(text, sj)
        m = _js_match_kw(text, sj, "for")
        if m is None:
            raise _JSExprFail("F623 forin no for")
        sj = _js_expect(text, _js_skip_ws(text, m), "(")
        sj = _js_skip_ws(text, sj)
        m = _js_match_kw(text, sj, "var")
        if m is None:
            raise _JSExprFail("F623 forin key not var")
        sj = _js_skip_ws(text, m)
        kvar, sj = _js_parse_ident(text, sj)
        if kvar in (sname, oname):
            raise _JSExprFail("F623 forin key shadows")
        sj = _js_skip_ws(text, sj)
        m = _js_match_kw(text, sj, "in")
        if m is None:
            raise _JSExprFail("F623 forin no in")
        sj = _js_skip_ws(text, m)
        obj2, sj = _js_parse_ident(text, sj)
        if obj2 != oname:
            raise _JSExprFail("F623 forin iterates another object")
        sj = _js_expect(text, _js_skip_ws(text, sj), ")")
        sj = _js_skip_ws(text, sj)
        braced = False
        if sj < inner_end and text[sj] == "{":
            braced = True
            sj = _js_skip_ws(text, sj + 1)
        s2, sj = _js_parse_ident(text, sj)
        if s2 != sname:
            raise _JSExprFail("F623 forin accum mismatch")
        sj = _js_skip_ws(text, sj)
        if not text.startswith("+=", sj):
            raise _JSExprFail("F623 forin body not +=")
        sj = _js_skip_ws(text, sj + 2)
        obj3, sj = _js_parse_ident(text, sj)
        if obj3 != oname:
            raise _JSExprFail("F623 forin body reads another object")
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, "[")
        k2b, sj = _js_parse_ident(text, _js_skip_ws(text, sj))
        if k2b != kvar:
            raise _JSExprFail("F623 forin body indexes another key")
        sj = _js_expect(text, _js_skip_ws(text, sj), "]")
        sj = _js_skip_ws(text, sj)
        if sj < inner_end and text[sj] == ".":
            raise _JSExprFail("F623 forin member read out of scope")
        sj = _js_expect(text, sj, ";")
        sj = _js_skip_ws(text, sj)
        if braced:
            sj = _js_expect(text, sj, "}")
            sj = _js_skip_ws(text, sj)
        # return s;
        m = _js_match_kw(text, sj, "return")
        if m is None:
            raise _JSExprFail("F623 forin no return")
        sj = _js_skip_ws(text, m)
        s3, sj = _js_parse_ident(text, sj)
        if s3 != sname:
            raise _JSExprFail("F623 forin returns another ident")
        sj = _js_skip_ws(text, sj)
        if sj < inner_end and text[sj] == ";":
            sj += 1
        sj = _js_skip_ws(text, sj)
        if sj != inner_end:
            raise _JSExprFail("F623 forin trailing statements")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        j = _js_expect(text, _js_skip_ws(text, j), "(")
        j = _js_expect(text, _js_skip_ws(text, j), ")")
        if depth >= _JS_EXPR_MAX_DEPTH:
            raise _JSExprFail("F623 forin too deep")
        rewritten = "Object.values(" + fe_text + ").join('')"
        val, rk = _js_parse_additive(rewritten, 0, depth + 1, state)
        rk = _js_skip_ws(rewritten, rk)
        if rk != len(rewritten):
            raise _JSExprFail("F623 forin trailing junk")
        state["ops"] += 1  # the iife wrapper is obfuscation-shaped
        return val, j
    except _JSExprFail:
        return None


def _js_parse_f562_params(text, j):
    """Parse 0-3 identifier params at text[j] (F562).

    Returns (params, next_index); the caller expects `)` or `=>`
    after. Never evals.
    """
    params = []
    n = len(text)
    j = _js_skip_ws(text, j)
    if j < n and text[j] == ")":
        return params, j
    while True:
        p, j = _js_parse_ident(text, j)
        params.append(p)
        if len(params) > 3:
            raise _JSExprFail("groupBy too many params")
        j = _js_skip_ws(text, j)
        if j < n and text[j] == ",":
            j = _js_skip_ws(text, j + 1)
            continue
        return params, j


def _js_parse_f562_result_expr(text, j, params):
    """Parse a groupBy callback result expression at text[j] (F562).

    Returns ("identity", None, next) when the expression is the
    callback's first parameter, or ("literal", key, next) when it
    is a string literal. Anything else fails closed. Never evals.
    """
    n = len(text)
    j = _js_skip_ws(text, j)
    if j < n and text[j] in "'\"":
        val, j = _js_parse_string(text, j)
        return "literal", val, j
    name, j = _js_parse_ident(text, j)
    if params and name == params[0]:
        return "identity", None, j
    raise _JSExprFail("groupBy callback not identity/literal")


def _js_parse_f562_return_body(text, j, params):
    """Parse `{ return EXPR; }` of a groupBy callback (F562).

    text[j] is just after `{`. Returns ((kind, payload),
    next_index_after_}). Never evals.
    """
    n = len(text)
    rk = _js_match_kw(text, _js_skip_ws(text, j), "return")
    if rk is None:
        raise _JSExprFail("groupBy callback not a return")
    kind, payload, rj = _js_parse_f562_result_expr(text, rk, params)
    rj = _js_skip_ws(text, rj)
    if rj < n and text[rj] == ";":
        rj += 1
    rj = _js_expect(text, rj, "}")
    return (kind, payload), rj


def _js_parse_f562_groupby_callback(text, j, state):
    """Parse a groupBy callback at text[j] (F562).

    Recognized (node-verified, v24.20.0): `x=>x`, `(x)=>x`,
    `x=>{return x;}`, `(x)=>{return x;}`, `function(x){return x;}`
    (identity -- the callback returns its first parameter), and
    `()=>\'k\'`, `(x)=>\'k\'`, `x=>{return \'k\';}`,
    `function(){return \'k\';}` (literal -- the callback returns
    a string literal regardless of parameters). 0-3 identifier
    params, ws-tolerant. Returns (kind, payload, next_index) where
    kind is "identity" (payload None) or "literal" (payload the key
    string). Anything else fails closed (documented boundary).
    Never evals.
    """
    n = len(text)
    j = _js_skip_ws(text, j)
    m = _js_match_kw(text, j, "function")
    if m is not None:
        j = _js_skip_ws(text, m)
        j = _js_expect(text, j, "(")
        params, j = _js_parse_f562_params(text, j)
        j = _js_expect(text, j, ")")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, "{")
        (kind, payload), j = _js_parse_f562_return_body(text, j,
                                                        params)
    else:
        if j < n and text[j] == "(":
            params, j = _js_parse_f562_params(text, j + 1)
            j = _js_expect(text, j, ")")
        else:
            p, j = _js_parse_ident(text, j)
            params = [p]
        j = _js_skip_ws(text, j)
        if not text.startswith("=>", j):
            raise _JSExprFail("groupBy callback without =>")
        j = _js_skip_ws(text, j + 2)
        if j < n and text[j] == "{":
            (kind, payload), j = _js_parse_f562_return_body(
                text, j + 1, params)
        else:
            kind, payload, j = _js_parse_f562_result_expr(text, j,
                                                         params)
    state["parts"] += 1
    if state["parts"] > _JS_EXPR_MAX_PARTS:
        raise _JSExprFail("too many parts")
    return kind, payload, j


def _js_parse_f562_groupby(text, i, depth, state, recv):
    """Parse `Object.groupBy(LITARR, CB)` / `Map.groupBy(LITARR, CB)` (F562).

    Desugars the ES2024 grouping builtins node-exactly (v24.20.0):
    each element of the literal array is grouped under
    ToPropertyKey(CB(element, index, array)); the callback is the
    F562 identity-or-literal class (parsed by
    _js_parse_f562_groupby_callback). Elements must be plain string
    literals -- numeric, nested, or marker elements fail closed
    (documented boundary). Object.groupBy returns a null-prototype
    object of arrays (modeled as a _JSObj of _JSArr -- member reads
    route through the _JSObj postfix branch); Map.groupBy returns
    a Map of key -> array (modeled as a _JSMap -- .get resolves
    through the _JSMap postfix branch). Elements were parts-charged
    at the array parse. Returns (value, next_index), or None when
    text[i] is not a groupBy head (the caller falls through). Once
    the `groupBy` member commits the parse, malformed shapes fail
    closed via _JSExprFail. Never evals.
    """
    n = len(text)
    j = i + len(recv)
    if j < n and text[j] in _JS_IDENT_CONT:
        return None  # e.g. Objectx / Mapx -- not the builtin
    j = _js_skip_ws(text, j)
    if j >= n or text[j] != ".":
        return None
    j = _js_skip_ws(text, j + 1)
    m = _js_match_kw(text, j, "groupBy")
    if m is None:
        return None
    # The groupBy member commits the parse: malformed shapes fail
    # closed.
    j = _js_expect(text, m, "(")
    j = _js_skip_ws(text, j)
    if j >= n or text[j] != "[":
        raise _JSExprFail("groupBy arg not an array literal")
    arr, j = _js_parse_array(text, j, depth, state)
    elems = []
    for e in arr.elements:
        if not isinstance(e, str) or isinstance(e, _JSNumStr):
            raise _JSExprFail("groupBy element not a string literal")
        elems.append(e)
    j = _js_skip_ws(text, j)
    j = _js_expect(text, j, ",")
    kind, payload, j = _js_parse_f562_groupby_callback(text, j, state)
    j = _js_skip_ws(text, j)
    j = _js_expect(text, j, ")")
    groups = {}
    order = []
    for e in elems:
        key = e if kind == "identity" else payload
        if key not in groups:
            groups[key] = []
            order.append(key)
        groups[key].append(e)
    if recv == "Object":
        return _JSObj({k: _JSArr(groups[k]) for k in order}), j
    return _JSMap({("s", k): _JSArr(groups[k]) for k in order}), j


def _js_parse_f563_map(text, i, depth, state, _keys_only=False):
    """Parse `new Map(LITENTRIES)` at text[i] (F563).

    Desugars literal map construction node-exactly (v24.20.0):
    LITENTRIES is `[K, V], ...` pairs; keys are string literals or
    canonical numeric literals (a Map keeps 1 and '1' as DISTINCT
    keys -- SameValueZero -- so the entry dict is keyed ("s", key)
    / ("n", key)); values are string literals. Later entries win
    on duplicate keys (node-exact). The value is a _JSMap;
    `.get('lit')` resolves through the _JSMap postfix branch (a
    missing key fails closed -- the decoder never decodes
    `undefined`). `new Map()` is the empty map. Non-literal
    entries fail closed (documented boundary). Returns (_JSMap,
    next_index), or None when text[i] is not a `new Map` head (the
    caller falls through, failing closed on `new` as before).
    Never evals.

    _keys_only (F600): the values are parsed but DISCARDED -- any
    parsed literal type is accepted. The resulting _JSMap must
    only flow to `.keys()` (values are unobservable through the
    keys iterator, node v24.20.0); it must never reach `.get`.
    """
    n = len(text)
    j = _js_match_kw(text, i, "new")
    if j is None:
        return None
    j = _js_match_kw(text, _js_skip_ws(text, j), "Map")
    if j is None:
        return None
    j = _js_skip_ws(text, j)
    if j >= n or text[j] != "(":
        return None  # `new Map` without call -- not a value here
    j = _js_skip_ws(text, j + 1)
    entries = {}
    if j < n and text[j] == ")":
        return _JSMap(entries), j + 1
    if j >= n or text[j] != "[":
        raise _JSExprFail("Map arg not an array literal")
    outer, j = _js_parse_array(text, j, depth, state)
    for p in outer.elements:
        if not isinstance(p, _JSArr) or len(p.elements) != 2:
            raise _JSExprFail("Map entry not a [k,v] pair")
        k, v = p.elements
        if isinstance(k, str) and not isinstance(k, _JSNumStr):
            kid = ("s", k)
        elif isinstance(k, _JSNumStr):
            kid = ("n", str(k))
        else:
            raise _JSExprFail("Map key not a literal")
        if _keys_only:
            # F600: the value is unobservable through the keys
            # iterator -- any parsed literal type is accepted and
            # discarded (keys-only maps never reach `.get`; the
            # caller guarantees the `.keys()` postfix follows).
            entries[kid] = None
        else:
            if not isinstance(v, str) or isinstance(v, _JSNumStr):
                raise _JSExprFail("Map value not a string literal")
            entries[kid] = v  # later wins, node-exact
    j = _js_skip_ws(text, j)
    j = _js_expect(text, j, ")")
    return _JSMap(entries), j


def _js_parse_f600_keys_map(text, i, depth, state):
    """Parse `new Map(LITENTRIES).keys()` at text[i] (F600).

    Keys-only construction for maps with non-string-literal values
    (the filed F600 shapes use numeric values, which the strict
    F563 grammar rejects): values are parsed but discarded --
    unobservable through the keys iterator (node v24.20.0). The
    `.keys()` postfix must follow immediately (dot or
    bracket-string member form, zero args); otherwise None and the
    strict F563 route handles the construction unchanged (the
    re-parse charges parts again -- intentional double charge,
    F469 precedent). Returns (_JSMapKeys, next_index). Never evals.
    """
    n = len(text)
    _m = _js_parse_f563_map(text, i, depth, state, _keys_only=True)
    if _m is None:
        return None
    _mmap, j = _m
    j = _js_skip_ws(text, j)
    if j < n and text[j] == ".":
        _mk = _js_skip_ws(text, j + 1)
        try:
            _mname, _mk = _js_parse_ident(text, _mk)
        except _JSExprFail:
            return None
    elif j < n and text[j] == "[":
        try:
            _mname, _mk = _js_parse_bracket_member(text, j)
        except _JSExprFail:
            return None
    else:
        return None
    if _mname != "keys":
        return None
    _ek = _js_skip_ws(text, _mk)
    if _ek >= n or text[_ek] != "(":
        return None
    _ek = _js_skip_ws(text, _ek + 1)
    if _ek >= n or text[_ek] != ")":
        return None
    _keys = []
    for (_kkind, _kkey) in _mmap.entries.keys():
        _keys.append(_JSNumStr(_kkey) if _kkind == "n" else _kkey)
        state["parts"] += 1  # F452: charge per key
        if state["parts"] > _JS_EXPR_MAX_PARTS:
            raise _JSExprFail("too many parts")
    state["ops"] += 1  # the keys call is obfuscation-shaped
    return _JSMapKeys(_keys), _ek + 1


def _js_parse_f606_params_mutation2_iife(text, i, depth, state):
    """Parse `(function(){DECL p=new URLSearchParams('LIT');[MUT;]*TERM})()` (F606).

    F599 (CLOSED) models `.append`/`.set` statement-form mutations with a
    getAll terminal, but fails the whole shape closed on any other
    mutation statement, so one-token neighbors node-yield the exact
    credential (node v24.20.0) while the decoder produces zero variants.
    Node-exact desugar (v24.20.0):
    - `var|const|let p=new URLSearchParams('LIT')` binds p to the
      _JSURLParams over the form-urlencoded pairs (F576's parse --
      urllib.parse.parse_qsl, node-identical);
    - `p.append('N','V');` / `p.set('N','V');` exactly as in F599
      (engine-exact append; set: first N-pair takes the value, other
      N-pairs dropped, missing name appends);
    - `p.sort();` sorts the pairs by name in UTF-16 code-unit order,
      stable (node-exact; names must be BMP -- code-unit order ==
      code-point order only there, anything else fails closed);
    - `p.delete('N');` removes every pair named N (node-exact);
    - terminal is `return p.getAll('K')<postfix>;` (F584's getAll --
      all K-values in insertion order as a _JSArr -- flowing through
      _js_parse_postfix; the return value must be a string), or the
      has-guarded form
      `if(p.has('N')){return p.getAll('K')<postfix>;}return 'LIT';`
      where the guard is evaluated statically -- the pairs are fully
      known, so both branches are node-exact.
    The invocation must be exactly `()`.

    Bounds (all fail closed -- rejected, never mis-decoded):
    - a `new URL(...)` binding (the .searchParams receiver is
      modeled by the F617 parser, tried later in the dispatch --
      corrected wave-374; a bare `new URL` binding without
      .searchParams still fails closed), a non-literal constructor
      arg;
    - mutation members other than append/set/sort/delete;
    - `.get` terminals (F610's parser owns them), else-clauses on the
      guard, non-literal mutation names/values, extra mutation args,
      a receiver other than the bare bound ident, a missing `;`;
    - a named function, parameters, a directive prologue, extra
      statements, reassignment of the var, non-empty call args.
    Returns (value, next_index), or None when text[i] is not this
    shape. Never evals.
    """
    n = len(text)
    j = _js_skip_ws(text, i)
    if j >= n or text[j] != "(":
        return None
    k = _js_skip_ws(text, j + 1)
    if not text.startswith("function", k):
        return None
    k2 = k + len("function")
    if k2 < n and text[k2] in _JS_IDENT_CONT:
        return None  # functionx -- not our shape
    if k2 < n and text[k2] in _JS_IDENT_START:
        return None  # named function -- not our shape
    try:
        j = _js_skip_ws(text, k2)
        j = _js_expect(text, j, "(")
        j = _js_expect(text, j, ")")
        brace = _js_skip_ws(text, j)
        j = _js_expect(text, brace, "{")
        inner_start, inner_end, j = _js_span_braced(text, brace)
        sj = _js_skip_ws(text, inner_start)
        _kw, m = _js_match_decl_kw(text, sj)
        if _kw is None:
            raise _JSExprFail("F606 decl not var/const/let")
        sj = _js_skip_ws(text, m)
        pname, sj = _js_parse_ident(text, sj)
        if pname == "arguments":
            raise _JSExprFail("F606 binding named arguments")
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, "=")
        sj = _js_skip_ws(text, sj)
        _pv = _js_parse_f576_new_url(text, sj, depth, state)
        if _pv is None or not isinstance(_pv[0], _JSURLParams):
            # A `new URL(...)` binding owns the searchParams receiver
            # (F617, tried later in the dispatch) -- fail closed here.
            raise _JSExprFail("F606 binding not URLSearchParams")
        _pv, sj = _pv
        pairs = list(_pv.pairs)
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, ";")
        # Zero or more mutation statements. Every iteration consumes
        # input, so the loop is bounded; each statement charges the
        # parts budget (F452).
        while True:
            q = _js_skip_ws(text, sj)
            try:
                rname, q = _js_parse_ident(text, q)
            except _JSExprFail:
                break
            if rname != pname:
                break
            q = _js_skip_ws(text, q)
            if q >= n or text[q] not in ".[":
                break
            try:
                _mname, q = _js_f576_member_name(text, q, "f606")
            except _JSExprFail:
                break
            if _mname not in ("append", "set", "sort", "delete"):
                # Unmodeled mutation members fail the whole shape
                # closed rather than mis-decode (documented residual).
                raise _JSExprFail("F606 member not append/set/sort/delete")
            q = _js_skip_ws(text, q)
            if q >= n or text[q] != "(":
                raise _JSExprFail("F606 mutation without paren")
            q = _js_skip_ws(text, q + 1)
            if _mname in ("append", "set"):
                if q >= n or text[q] not in "'\"":
                    raise _JSExprFail("F606 mutation name not a literal")
                _mn, q = _js_parse_string(text, q)
                q = _js_skip_ws(text, q)
                if q >= n or text[q] != ",":
                    raise _JSExprFail("F606 mutation arity")
                q = _js_skip_ws(text, q + 1)
                if q >= n or text[q] not in "'\"":
                    raise _JSExprFail("F606 mutation value not a literal")
                _mv, q = _js_parse_string(text, q)
                q = _js_skip_ws(text, q)
                if q >= n or text[q] != ")":
                    raise _JSExprFail("F606 mutation unterminated")
                if _mname == "append":
                    pairs.append((_mn, _mv))
                else:
                    _seen = False
                    _np = []
                    for _pn, _pvv in pairs:
                        if _pn != _mn:
                            _np.append((_pn, _pvv))
                        elif not _seen:
                            _seen = True
                            _np.append((_pn, _mv))
                    if not _seen:
                        _np.append((_mn, _mv))
                    pairs = _np
            elif _mname == "delete":
                if q >= n or text[q] not in "'\"":
                    raise _JSExprFail("F606 delete name not a literal")
                _mn, q = _js_parse_string(text, q)
                q = _js_skip_ws(text, q)
                if q >= n or text[q] != ")":
                    raise _JSExprFail("F606 delete unterminated")
                pairs = [(_pn, _pvv) for _pn, _pvv in pairs
                         if _pn != _mn]
            else:  # sort
                if q >= n or text[q] != ")":
                    raise _JSExprFail("F606 sort not zero-arg")
                if any(ord(_c) > 0xFFFF for _pn, _ in pairs
                       for _c in _pn):
                    raise _JSExprFail("F606 sort non-BMP name")
                pairs = sorted(pairs, key=lambda _t: _t[0])
            q = _js_skip_ws(text, q + 1)
            if q >= n or text[q] != ";":
                raise _JSExprFail("F606 mutation without semicolon")
            state["parts"] += 1  # the mutation is obfuscation-shaped
            if state["parts"] > _JS_EXPR_MAX_PARTS:
                raise _JSExprFail("too many parts")
            sj = q + 1

        def _ret_getall(q):
            """Parse `return p.getAll('K')<postfix>;`; return (value, next)."""
            rk = _js_match_kw(text, q, "return")
            if rk is None:
                raise _JSExprFail("F606 body not return")
            q = _js_skip_ws(text, rk)
            rname, q = _js_parse_ident(text, q)
            if rname != pname:
                raise _JSExprFail("F606 returns another ident")
            q = _js_skip_ws(text, q)
            if q >= n or text[q] not in ".[":
                raise _JSExprFail("F606 return not a member read")
            _gm, q = _js_f576_member_name(text, q, "f606")
            if _gm != "getAll":
                # `.get` terminals belong to F610's parser; anything
                # else fails closed.
                raise _JSExprFail("F606 return not getAll")
            q = _js_skip_ws(text, q)
            if q >= n or text[q] != "(":
                raise _JSExprFail("F606 getAll without paren")
            q = _js_skip_ws(text, q + 1)
            if q >= n or text[q] not in "'\"":
                raise _JSExprFail("F606 getAll key not a literal")
            _gkey, q = _js_parse_string(text, q)
            q = _js_skip_ws(text, q)
            if q >= n or text[q] != ")":
                raise _JSExprFail("F606 getAll unterminated")
            _gvals = [_pval for _pname2, _pval in pairs
                      if _pname2 == _gkey]
            state["parts"] += len(_gvals)
            if state["parts"] > _JS_EXPR_MAX_PARTS:
                raise _JSExprFail("too many parts")
            q = _js_skip_ws(text, q + 1)
            # The getAll array flows through the normal postfix chain
            # (F584 precedent: .join / .slice / indexed reads); the
            # return value must be a string to be decodable.
            _rval, q = _js_parse_postfix(text, q, _JSArr(_gvals),
                                         depth, state)
            if not isinstance(_rval, str):
                raise _JSExprFail("F606 return not a string")
            q = _js_skip_ws(text, q)
            if q >= n or text[q] != ";":
                raise _JSExprFail("F606 return without semicolon")
            return _rval, q + 1

        # Terminal: `return p.getAll('K')<postfix>;`, or the
        # has-guarded form
        # `if(p.has('N')){return p.getAll('K')<postfix>;}return 'LIT';`.
        q = _js_skip_ws(text, sj)
        if _js_match_kw(text, q, "return") is not None:
            _rval, q = _ret_getall(q)
            q = _js_skip_ws(text, q)
            if q != inner_end:
                raise _JSExprFail("F606 trailing statements")
        else:
            ik = _js_match_kw(text, q, "if")
            if ik is None:
                raise _JSExprFail("F606 body not return/if")
            q = _js_skip_ws(text, ik)
            q = _js_expect(text, q, "(")
            q = _js_skip_ws(text, q)
            hname, q = _js_parse_ident(text, q)
            if hname != pname:
                raise _JSExprFail("F606 guard on another ident")
            q = _js_skip_ws(text, q)
            if q >= n or text[q] not in ".[":
                raise _JSExprFail("F606 guard not a member read")
            _hm, q = _js_f576_member_name(text, q, "f606")
            if _hm != "has":
                # Only the has-guard is modeled; any other
                # if-condition fails closed.
                raise _JSExprFail("F606 guard not has")
            q = _js_skip_ws(text, q)
            if q >= n or text[q] != "(":
                raise _JSExprFail("F606 has without paren")
            q = _js_skip_ws(text, q + 1)
            if q >= n or text[q] not in "'\"":
                raise _JSExprFail("F606 has name not a literal")
            _hn, q = _js_parse_string(text, q)
            q = _js_skip_ws(text, q)
            if q >= n or text[q] != ")":
                raise _JSExprFail("F606 has unterminated")
            q = _js_skip_ws(text, q + 1)
            if q >= n or text[q] != ")":
                raise _JSExprFail("F606 if without close paren")
            q = _js_expect(text, q + 1, "{")
            q = _js_skip_ws(text, q)
            _ival, q = _ret_getall(q)
            q = _js_skip_ws(text, q)
            q = _js_expect(text, q, "}")
            # Fallthrough: exactly `return 'LIT';` -- no else clause
            # (documented residual).
            q = _js_skip_ws(text, q)
            frk = _js_match_kw(text, q, "return")
            if frk is None:
                raise _JSExprFail("F606 guard without fallthrough")
            q = _js_skip_ws(text, frk)
            if q >= n or text[q] not in "'\"":
                raise _JSExprFail("F606 fallthrough not a literal")
            _flit, q = _js_parse_string(text, q)
            q = _js_skip_ws(text, q)
            if q >= n or text[q] != ";":
                raise _JSExprFail("F606 fallthrough without semicolon")
            q = _js_skip_ws(text, q + 1)
            if q != inner_end:
                raise _JSExprFail("F606 trailing statements")
            # The guard is evaluated statically -- the pairs are fully
            # known, so both branches are node-exact.
            _has = False
            for _pn, _ in pairs:
                if _pn == _hn:
                    _has = True
                    break
            _rval = _ival if _has else _flit
        # Invocation: exactly `()`.
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, "(")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        state["ops"] += 1  # the iife wrapper is obfuscation-shaped
        return _rval, j
    except _JSExprFail:
        return None


def _js_parse_f610_params_setget_iife(text, i, depth, state):
    """Parse `(function(){DECL p=new URLSearchParams('LIT');[MUT;]*return p.get('K')<postfix>[+'LIT']*;})()` (F610).

    F599 (CLOSED) models append/set statement-form mutations followed
    by getAll(), and F576 (CLOSED) models `.get` on constructor
    strings, but a set() mutation read back via `.get()` is a
    different read path: set() OVERWRITES (engine-exact -- the first
    N-pair takes the value, other N-pairs dropped, missing name
    appends) while get() returns the FIRST value. Node-exact desugar
    (v24.20.0):
    - `var|const|let p=new URLSearchParams('LIT')` binds p (F576's
      parse -- urllib.parse.parse_qsl, node-identical);
    - `p.append('N','V');` / `p.set('N','V');` exactly as in F599;
    - `return p.get('K')` yields the first K-value as a string; a
      missing name is JS null -- fail closed (the `null+'x'`
      coercion is out of scope, documented residual);
    - the get string flows through _js_parse_postfix, then an
      additive tail of string literals (`+'LIT'`)* -- the filed
      shapes assemble the credential from a set fragment plus a
      literal tail.
    The invocation must be exactly `()`.

    Bounds (all fail closed -- rejected, never mis-decoded):
    - sort/delete/has mutations (F606's parser owns those for getAll
      terminals; the hybrid with a get terminal is an honest
      residual), getAll terminals (F599/F606 own them);
    - a `new URL(...)` binding (the .searchParams receiver is
      modeled by the F617 parser -- corrected wave-374),
      a non-literal constructor arg,
      non-literal mutation names/values, extra mutation args, a
      receiver other than the bare bound ident, a missing `;`, a
      non-literal additive tail;
    - a named function, parameters, a directive prologue, extra
      statements, reassignment of the var, non-empty call args.
    Returns (value, next_index), or None when text[i] is not this
    shape. Never evals.
    """
    n = len(text)
    j = _js_skip_ws(text, i)
    if j >= n or text[j] != "(":
        return None
    k = _js_skip_ws(text, j + 1)
    if not text.startswith("function", k):
        return None
    k2 = k + len("function")
    if k2 < n and text[k2] in _JS_IDENT_CONT:
        return None  # functionx -- not our shape
    if k2 < n and text[k2] in _JS_IDENT_START:
        return None  # named function -- not our shape
    try:
        j = _js_skip_ws(text, k2)
        j = _js_expect(text, j, "(")
        j = _js_expect(text, j, ")")
        brace = _js_skip_ws(text, j)
        j = _js_expect(text, brace, "{")
        inner_start, inner_end, j = _js_span_braced(text, brace)
        sj = _js_skip_ws(text, inner_start)
        _kw, m = _js_match_decl_kw(text, sj)
        if _kw is None:
            raise _JSExprFail("F610 decl not var/const/let")
        sj = _js_skip_ws(text, m)
        pname, sj = _js_parse_ident(text, sj)
        if pname == "arguments":
            raise _JSExprFail("F610 binding named arguments")
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, "=")
        sj = _js_skip_ws(text, sj)
        _pv = _js_parse_f576_new_url(text, sj, depth, state)
        if _pv is None or not isinstance(_pv[0], _JSURLParams):
            # A `new URL(...)` binding owns the searchParams receiver
            # (F617, tried later in the dispatch) -- fail closed here.
            raise _JSExprFail("F610 binding not URLSearchParams")
        _pv, sj = _pv
        pairs = list(_pv.pairs)
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, ";")
        # Zero or more `p.append('N','V');` / `p.set('N','V');`
        # mutation statements. Every iteration consumes input, so the
        # loop is bounded; each statement charges the parts budget
        # (F452).
        while True:
            q = _js_skip_ws(text, sj)
            try:
                rname, q = _js_parse_ident(text, q)
            except _JSExprFail:
                break
            if rname != pname:
                break
            q = _js_skip_ws(text, q)
            if q >= n or text[q] not in ".[":
                break
            try:
                _mname, q = _js_f576_member_name(text, q, "f610")
            except _JSExprFail:
                break
            if _mname not in ("append", "set"):
                # sort/delete/has are F606's family -- fail the whole
                # shape closed rather than mis-decode (documented
                # residual).
                raise _JSExprFail("F610 member not append/set")
            q = _js_skip_ws(text, q)
            if q >= n or text[q] != "(":
                raise _JSExprFail("F610 mutation without paren")
            q = _js_skip_ws(text, q + 1)
            if q >= n or text[q] not in "'\"":
                raise _JSExprFail("F610 mutation name not a literal")
            _mn, q = _js_parse_string(text, q)
            q = _js_skip_ws(text, q)
            if q >= n or text[q] != ",":
                raise _JSExprFail("F610 mutation arity")
            q = _js_skip_ws(text, q + 1)
            if q >= n or text[q] not in "'\"":
                raise _JSExprFail("F610 mutation value not a literal")
            _mv, q = _js_parse_string(text, q)
            q = _js_skip_ws(text, q)
            if q >= n or text[q] != ")":
                raise _JSExprFail("F610 mutation unterminated")
            q = _js_skip_ws(text, q + 1)
            if q >= n or text[q] != ";":
                raise _JSExprFail("F610 mutation without semicolon")
            if _mname == "append":
                pairs.append((_mn, _mv))
            else:
                # Engine-exact set (node v24.20.0): the first pair
                # with the name takes the new value; every other
                # pair with the name is removed; a missing name
                # appends.
                _seen = False
                _np = []
                for _pn, _pvv in pairs:
                    if _pn != _mn:
                        _np.append((_pn, _pvv))
                    elif not _seen:
                        _seen = True
                        _np.append((_pn, _mv))
                if not _seen:
                    _np.append((_mn, _mv))
                pairs = _np
            state["parts"] += 1  # the mutation is obfuscation-shaped
            if state["parts"] > _JS_EXPR_MAX_PARTS:
                raise _JSExprFail("too many parts")
            sj = q + 1
        # `return p.get('K')<postfix>[+'LIT']*;`
        q = _js_skip_ws(text, sj)
        rk = _js_match_kw(text, q, "return")
        if rk is None:
            raise _JSExprFail("F610 body not return")
        q = _js_skip_ws(text, rk)
        rname, q = _js_parse_ident(text, q)
        if rname != pname:
            raise _JSExprFail("F610 returns another ident")
        q = _js_skip_ws(text, q)
        if q >= n or text[q] not in ".[":
            raise _JSExprFail("F610 return not a member read")
        _mname, q = _js_f576_member_name(text, q, "f610")
        if _mname != "get":
            # getAll terminals belong to F599/F606; anything else
            # fails closed.
            raise _JSExprFail("F610 return not get")
        q = _js_skip_ws(text, q)
        if q >= n or text[q] != "(":
            raise _JSExprFail("F610 get without paren")
        q = _js_skip_ws(text, q + 1)
        if q >= n or text[q] not in "'\"":
            raise _JSExprFail("F610 get key not a literal")
        _gkey, q = _js_parse_string(text, q)
        q = _js_skip_ws(text, q)
        if q >= n or text[q] != ")":
            raise _JSExprFail("F610 get unterminated")
        _ghits = [_pval for _pname2, _pval in pairs
                  if _pname2 == _gkey]
        if not _ghits:
            # JS null; the `null+'x'` string coercion is out of scope
            # -- fail closed (documented residual).
            raise _JSExprFail("F610 get of missing name")
        state["parts"] += 1
        if state["parts"] > _JS_EXPR_MAX_PARTS:
            raise _JSExprFail("too many parts")
        q = _js_skip_ws(text, q + 1)
        # The get string flows through the normal postfix chain
        # (.slice / indexed reads); the return value must be a string
        # to be decodable.
        _rval, q = _js_parse_postfix(text, q, _ghits[0], depth, state)
        if not isinstance(_rval, str):
            raise _JSExprFail("F610 return not a string")
        # Additive tail of string literals only -- the filed shapes
        # assemble the credential from a set fragment plus a literal
        # tail; anything else fails closed.
        while True:
            t = _js_skip_ws(text, q)
            if t >= n or text[t] != "+":
                break
            t = _js_skip_ws(text, t + 1)
            if t >= n or text[t] not in "'\"":
                raise _JSExprFail("F610 additive tail not a literal")
            _tail, t = _js_parse_string(text, t)
            if len(_rval) + len(_tail) > _MAX_DECODE_BYTES:
                raise _JSExprFail("concat too long")
            _rval = _rval + _tail
            state["parts"] += 1
            if state["parts"] > _JS_EXPR_MAX_PARTS:
                raise _JSExprFail("too many parts")
            state["ops"] += 1
            q = t
        q = _js_skip_ws(text, q)
        if q >= n or text[q] != ";":
            raise _JSExprFail("F610 return without semicolon")
        q = _js_skip_ws(text, q + 1)
        if q != inner_end:
            raise _JSExprFail("F610 trailing statements")
        # Invocation: exactly `()`.
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, "(")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        state["ops"] += 1  # the iife wrapper is obfuscation-shaped
        return _rval, j
    except _JSExprFail:
        return None


def _js_parse_f649_varbound_members_iife(text, i, depth, state):
    """Parse `(function(){DECL o=structuredClone({LIT});
    return o.M(+o.M)*;})()` at text[i] (F649).

    F536 (CLOSED) models member reads on an INLINE structuredClone
    call, but a var-bound intermediate escapes the receiver model:
    `(function(){var o=structuredClone({a:'f1',b:'f2'});
    return o.a+o.b;})()` node-evaluates to the exact credential
    while the decoder produces zero variants. Node-exact desugar
    (v24.20.0): the var binds the F649 sclone source
    (`_js_parse_f649_sclone_object` -- the F536 deep-copy
    identity, getters evaluated at clone time); each `o.M` /
    `o['M']` term (dot-ident or bracket-string member, F510 head
    discipline) resolves against the cloned props via
    `_jsobj_lookup`; the `+`-joined sum is the decoded value.

    Bounds (all fail closed -- rejected, never mis-decoded):
    - a named function, parameters, a directive prologue, extra
      statements, reassignment of the var, multi-decl
      (`var o=..., p=...`), non-empty call args;
    - a binding source outside the F649 sclone grammar (Maps,
      non-literals -- F536's inline path keeps those);
    - a member read that misses or is non-string (unbound name,
      computed member, missing key, non-string value -- the F510
      string-only discipline);
    - any postfix after the additive (tight scope -- the filed
      shape returns the sum directly).
    Returns (value, next_index), or None when text[i] is not this
    shape. Never evals.
    """
    n = len(text)
    if depth >= _JS_EXPR_MAX_DEPTH:
        return None
    try:
        j = _js_skip_ws(text, i)
        if j >= n or text[j] != "(":
            return None
        k = _js_skip_ws(text, j + 1)
        if not text.startswith("function", k):
            return None
        k2 = k + len("function")
        if k2 < n and text[k2] in _JS_IDENT_CONT:
            return None  # functionx -- not our shape
        if k2 < n and text[k2] in _JS_IDENT_START:
            return None  # named function -- not our shape
        j = _js_skip_ws(text, k2)
        j = _js_expect(text, j, "(")
        j = _js_expect(text, j, ")")
        brace = _js_skip_ws(text, j)
        j = _js_expect(text, brace, "{")
        inner_start, inner_end, j = _js_span_braced(text, brace)
        sj = _js_skip_ws(text, inner_start)
        _kw, m = _js_match_decl_kw(text, sj)
        if _kw is None:
            raise _JSExprFail("F649 decl not var/const/let")
        sj = _js_skip_ws(text, m)
        oname, sj = _js_parse_ident(text, sj)
        if oname == "arguments":
            raise _JSExprFail("F649 binding named arguments")
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, "=")
        sj = _js_skip_ws(text, sj)
        _obj, sj = _js_parse_f649_sclone_object(text, sj, depth, state)
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, ";")
        sj = _js_skip_ws(text, sj)
        m = _js_match_kw(text, sj, "return")
        if m is None:
            raise _JSExprFail("F649 no return")
        sj = _js_skip_ws(text, m)
        # `o.M(+o.M)*` -- dot-ident or bracket-string members on
        # the bare bound ident, F510 head discipline.
        parts = []
        while True:
            sj = _js_skip_ws(text, sj)
            _rname, sj = _js_parse_ident(text, sj)
            if _rname != oname:
                raise _JSExprFail("F649 return not over bound ident")
            sj = _js_skip_ws(text, sj)
            if sj < n and text[sj] == ".":
                sj = _js_skip_ws(text, sj + 1)
                _mem, sj = _js_parse_ident(text, sj)
            elif sj < n and text[sj] == "[":
                _mem, sj = _js_parse_bracket_member(text, sj)
            else:
                raise _JSExprFail("F649 member not dot/bracket")
            _val = _jsobj_lookup(_obj, _mem)
            if not isinstance(_val, str):
                raise _JSExprFail("F649 member not a string")
            parts.append(_val)
            state["parts"] += 1
            if state["parts"] > _JS_EXPR_MAX_PARTS:
                raise _JSExprFail("too many parts")
            sj = _js_skip_ws(text, sj)
            if sj < n and text[sj] == "+":
                sj = sj + 1
                continue
            break
        sj = _js_skip_ws(text, sj)
        sj = _js_expect(text, sj, ";")
        sj = _js_skip_ws(text, sj)
        if sj != inner_end:
            raise _JSExprFail("F649 trailing statements")
        # Invocation: exactly `()`.
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, "(")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        state["ops"] += 1  # the iife wrapper is obfuscation-shaped
        return "".join(parts), j
    except _JSExprFail:
        return None


